import { Book } from "@/lib/types";

export const numbers: Book = {
  id: "numbers",
  name: "4. Mose",
  shortName: "4.Mose",
  testament: "old",
  chapters: [
    { number: 1, verses: [
      { number: 1, text: "Und der HERR redete zu Mose in der Wüste Sinai* im Zelt der Begegnung* am ersten <Tag> des zweiten Monats, im zweiten Jahr* nach ihrem Auszug aus dem Land Ägypten, und sprach:", heading: "Zählung der kampffähigen Männer", footnotes: ["℘ Kap. 9,1; 10,11; 2Mo 19,1; 5Mo 1,3; 2,7.14", "℘ Kap. 12,4; 3Mo 1,1", "℘ V. 27.31; Kap. 5,16"] },
      { number: 2, text: "Nehmt die Summe der ganzen Gemeinde der Söhne Israel auf nach ihren Sippen, nach ihren Vaterhäusern, nach der Zahl der Namen, alles Männliche nach ihren Köpfen*!", footnotes: ["℘ Kap. 26,2; 2Mo 30,12"] },
      { number: 3, text: "Von zwanzig Jahren an und darüber*, jeden, der mit dem Heer auszieht in Israel, die sollt ihr mustern nach ihren Heer<esverbänd>en, du und Aaron!", footnotes: ["℘ Kap. 3,15.40; 4,3.47"] },
      { number: 4, text: "Und je ein Mann für jeden* Stamm soll bei euch sein, ein Mann, der das Haupt von seinem Vaterhaus ist*.", footnotes: ["w. den", "℘ V. 44; Kap. 4,34; Jos 22,14"] },
      { number: 5, text: "*Und dies sind die Namen der Männer, die euch beistehen sollen: für Ruben: Elizur, der Sohn Schedëurs;", footnotes: ["℘ V. 5-15: Kap. 2,3-29; 7,12-78; 10,14-27; 1Mo 35,23-26; 1Chr 27,16-22"] },
      { number: 6, text: "für Simeon: Schelumiël, der Sohn Zurischaddais;" },
      { number: 7, text: "für Juda: Nachschon, der Sohn Amminadabs*;", footnotes: ["℘ 2Mo 6,23; Rt 4,20; 1Chr 2,10"] },
      { number: 8, text: "für Issaschar: Netanel, der Sohn Zuars;" },
      { number: 9, text: "für Sebulon: Eliab, der Sohn Helons;" },
      { number: 10, text: "für die Söhne Josefs: für Ephraim: Elischama*, der Sohn Ammihuds; für Manasse: Gamliël, der Sohn Pedazurs;", footnotes: ["℘ 1Chr 7,26"] },
      { number: 11, text: "für Benjamin: Abidan, der Sohn des Gidoni;" },
      { number: 12, text: "für Dan: Ahiëser, der Sohn Ammischaddais;" },
      { number: 13, text: "für Asser: Pagiël, der Sohn Ochrans;" },
      { number: 14, text: "für Gad: Eljasaf, der Sohn Deguëls;" },
      { number: 15, text: "für Naftali: Ahira, der Sohn Enans." },
      { number: 16, text: "Das sind die Berufenen der Gemeinde, die Fürsten der Stämme ihrer Väter; sie waren die Häupter der Tausendschaften Israels*.", footnotes: ["℘ Kap. 7,2; 16,2"] },
      { number: 17, text: "Und Mose und Aaron nahmen diese mit Namen bezeichneten Männer," },
      { number: 18, text: "und sie versammelten die ganze Gemeinde am ersten <Tag> des zweiten Monats. Und sie ließen sich in die Geburtsverzeichnisse eintragen nach ihren Sippen, nach ihren Vaterhäusern*, nach der Zahl der Namen, von zwanzig Jahren an und darüber, nach ihrer Kopfzahl,", footnotes: ["℘ 2Mo 6,14"] },
      { number: 19, text: "wie der HERR dem Mose geboten hatte*. Und so musterte er sie in der Wüste Sinai*.", footnotes: ["℘ V. 54; Kap. 2,34; 3,51; 2Mo 40,32", "℘ Kap. 26,63.64"] },
      { number: 20, text: "*Da waren die Söhne Rubens, des Erstgeborenen Israels: ihre Generationenfolge* nach ihren Sippen, nach ihren Vaterhäusern, nach der Zahl der Namen, nach ihrer Kopfzahl, alles Männliche von zwanzig Jahren an und darüber, jeder, der mit dem Heer auszog;", footnotes: ["℘ V. 20-42: Kap. 26,5-57; 1Mo 35,23-26", "o. Entstehung, Entstehungsgeschichte; vgl. Anm. zu 1Mo 5,1"] },
      { number: 21, text: "ihre Gemusterten vom Stamm Ruben waren 46 500." },
      { number: 22, text: "Von den Söhnen Simeon: ihre Generationenfolge* nach ihren Sippen, nach ihren Vaterhäusern, seine Gemusterten nach der Zahl der Namen, nach ihrer Kopfzahl, alles Männliche von zwanzig Jahren an und darüber, jeder, der mit dem Heer auszog;", footnotes: ["o. Entstehung, Entstehungsgeschichte; vgl. Anm. zu 1Mo 5,1"] },
      { number: 23, text: "ihre Gemusterten vom Stamm Simeon waren 59 300." },
      { number: 24, text: "Von den Söhnen Gad: ihre Generationenfolge* nach ihren Sippen, nach ihren Vaterhäusern, nach der Zahl der Namen, von zwanzig Jahren an und darüber, jeder, der mit dem Heer auszog;", footnotes: ["o. Entstehung, Entstehungsgeschichte; vgl. Anm. zu 1Mo 5,1"] },
      { number: 25, text: "ihre Gemusterten vom Stamm Gad waren 45 650." },
      { number: 26, text: "Von den Söhnen Juda: ihre Generationenfolge* nach ihren Sippen, nach ihren Vaterhäusern, nach der Zahl der Namen, von zwanzig Jahren an und darüber, jeder, der mit dem Heer auszog;", footnotes: ["o. Entstehung, Entstehungsgeschichte; vgl. Anm. zu 1Mo 5,1"] },
      { number: 27, text: "ihre Gemusterten vom Stamm Juda waren 74 600." },
      { number: 28, text: "Von den Söhnen Issaschar: ihre Generationenfolge* nach ihren Sippen, nach ihren Vaterhäusern, nach der Zahl der Namen, von zwanzig Jahren an und darüber, jeder, der mit dem Heer auszog;", footnotes: ["o. Entstehung, Entstehungsgeschichte; vgl. Anm. zu 1Mo 5,1"] },
      { number: 29, text: "ihre Gemusterten vom Stamm Issaschar waren 54 400." },
      { number: 30, text: "Von den Söhnen Sebulon: ihre Generationenfolge* nach ihren Sippen, nach ihren Vaterhäusern, nach der Zahl der Namen, von zwanzig Jahren an und darüber, jeder, der mit dem Heer auszog;", footnotes: ["o. Entstehung, Entstehungsgeschichte; vgl. Anm. zu 1Mo 5,1"] },
      { number: 31, text: "ihre Gemusterten vom Stamm Sebulon waren 57 400." },
      { number: 32, text: "Von den Söhnen Josef: von den Söhnen Ephraim: ihre Generationenfolge* nach ihren Sippen, nach ihren Vaterhäusern, nach der Zahl der Namen, von zwanzig Jahren an und darüber, jeder, der mit dem Heer auszog;", footnotes: ["o. Entstehung, Entstehungsgeschichte; vgl. Anm. zu 1Mo 5,1"] },
      { number: 33, text: "ihre Gemusterten vom Stamm Ephraim waren 40 500." },
      { number: 34, text: "Von den Söhnen Manasse: ihre Generationenfolge* nach ihren Sippen, nach ihren Vaterhäusern, nach der Zahl der Namen, von zwanzig Jahren an und darüber, jeder, der mit dem Heer auszog;", footnotes: ["o. Entstehung, Entstehungsgeschichte; vgl. Anm. zu 1Mo 5,1"] },
      { number: 35, text: "ihre Gemusterten vom Stamm Manasse waren 32 200." },
      { number: 36, text: "Von den Söhnen Benjamin: ihre Generationenfolge* nach ihren Sippen, nach ihren Vaterhäusern, nach der Zahl der Namen, von zwanzig Jahren an und darüber, jeder, der mit dem Heer auszog;", footnotes: ["o. Entstehung, Entstehungsgeschichte; vgl. Anm. zu 1Mo 5,1"] },
      { number: 37, text: "ihre Gemusterten vom Stamm Benjamin waren 35 400." },
      { number: 38, text: "Von den Söhnen Dan: ihre Generationenfolge* nach ihren Sippen, nach ihren Vaterhäusern, nach der Zahl der Namen, von zwanzig Jahren an und darüber, jeder, der mit dem Heer auszog;", footnotes: ["o. Entstehung, Entstehungsgeschichte; vgl. Anm. zu 1Mo 5,1"] },
      { number: 39, text: "ihre Gemusterten vom Stamm Dan waren 62 700." },
      { number: 40, text: "Von den Söhnen Asser: ihre Generationenfolge* nach ihren Sippen, nach ihren Vaterhäusern, nach der Zahl der Namen, von zwanzig Jahren an und darüber, jeder, der mit dem Heer auszog;", footnotes: ["o. Entstehung, Entstehungsgeschichte; vgl. Anm. zu 1Mo 5,1"] },
      { number: 41, text: "ihre Gemusterten vom Stamm Asser waren 41 500." },
      { number: 42, text: "Die Söhne Naftali: ihre Generationenfolge* nach ihren Sippen, nach ihren Vaterhäusern, nach der Zahl der Namen, von zwanzig Jahren an und darüber, jeder, der mit dem Heer auszog;", footnotes: ["o. Entstehung, Entstehungsgeschichte; vgl. Anm. zu 1Mo 5,1"] },
      { number: 43, text: "ihre Gemusterten vom Stamm Naftali waren 53 400." },
      { number: 44, text: "Das sind die Gemusterten, die Mose musterte <zusammen mit> Aaron und den Fürsten Israels, den zwölf Männern, je ein Mann für sein Vaterhaus*.", footnotes: ["℘ V. 4"] },
      { number: 45, text: "Und es waren alle Gemusterten der Söhne Israel nach ihren Vaterhäusern von zwanzig Jahren an und darüber — jeder, der mit dem Heer auszog in Israel —," },
      { number: 46, text: "es waren all die Gemusterten 603 550*. —", footnotes: ["℘ Kap. 2,32; 11,21; 26,51; 2Mo 12,37"] },
      { number: 47, text: "Die aber Leviten waren nach dem Stamm ihrer Väter, wurden nicht unter ihnen gemustert*.", footnotes: ["℘ Kap. 26,62"] },
      { number: 48, text: "Und der HERR redete zu Mose und sprach:", heading: "Aussonderung der Leviten" },
      { number: 49, text: "Nur den Stamm Levi sollst du nicht mustern und ihre Summe nicht aufnehmen unter den Söhnen Israel*,", footnotes: ["℘ Kap. 2,33"] },
      { number: 50, text: "sondern setze du die Leviten <als Aufseher> ein über die Wohnung des Zeugnisses und über all ihr Gerät und über alles, was zu ihr gehört! Sie sollen die Wohnung und all ihr Gerät tragen, und sie sollen sie bedienen und sich rings um die Wohnung herum lagern*.", footnotes: ["℘ Kap. 3,6-9.23-38; 4,3-33; 18,5"] },
      { number: 51, text: "Und wenn die Wohnung aufbricht, sollen die Leviten sie abbauen; und wenn die Wohnung sich lagert*, sollen die Leviten sie aufrichten*. Der Fremde* aber, der sich <ihr> nähert, soll getötet werden*.", footnotes: ["w. beim Lagern der Wohnung", "℘ Kap. 10,17.21", "d. h. ein Unbefugter", "℘ Kap. 3,10.38; 4,15; 17,5.28; 18,7.22; 1Sam 6,19; 2Sam 6,7"] },
      { number: 52, text: "Und die Söhne Israel sollen sich lagern — jeder an seinem Lager<platz> und jeder bei seinem Feldzeichen — nach ihren Heer<esverbänd>en*.", footnotes: ["℘ Kap. 2,2-34"] },
      { number: 53, text: "Die Leviten aber sollen rings um die Wohnung des Zeugnisses herum lagern, damit nicht ein Zorn über die Gemeinde der Söhne Israel komme; und die Leviten sollen den Dienst an der Wohnung des Zeugnisses versehen*.", footnotes: ["℘ Kap. 3,7.8; 8,24-26; 16,9; 18,3.4; 31,30.47; 2Chr 13,10.11"] },
      { number: 54, text: "Und die Söhne Israel taten nach allem, was der HERR dem Mose befohlen hatte; so taten sie <es>*.", footnotes: ["℘ V. 19; Kap. 8,20.22; 9,5; 36,10"] },
    ]},
    { number: 2, verses: [
      { number: 1, text: "Und der HERR redete zu Mose und zu Aaron und sprach:", heading: "Lagerordnung" },
      { number: 2, text: "Die Söhne Israel sollen <so> lagern: jeder bei seiner Abteilung, bei den Zeichen ihrer Vaterhäuser*; rings um das Zelt der Begegnung her, <jeweils> gegenüber sollen sie lagern.", footnotes: ["℘ Kap. 1,52"] },
      { number: 3, text: "*Und zwar die nach Osten, nach <Sonnen>aufgang hin Lagernden, <das ist> die Abteilung des Lagers Juda, nach ihren Heer<esverbänd>en <geordnet>: und der Fürst der Söhne Juda, Nachschon, der Sohn Amminadabs*,", footnotes: ["℘ V. 3-29: Kap. 1,5-15; 1Mo 35,23-26", "℘ Kap. 1,7; Lk 3,33"] },
      { number: 4, text: "und sein Heer und ihre Gemusterten, 74 600." },
      { number: 5, text: "Und die neben ihm Lagernden, <das ist> der Stamm Issaschar und der Fürst der Söhne Issaschar, Netanel, der Sohn Zuars," },
      { number: 6, text: "und sein Heer und dessen Gemusterte, 54 400." },
      { number: 7, text: "Der Stamm Sebulon und der Fürst der Söhne Sebulon, Eliab, der Sohn Helons," },
      { number: 8, text: "und sein Heer und dessen Gemusterte, 57 400." },
      { number: 9, text: "Alle Gemusterten vom Lager Juda: 186 400, nach ihren Heer<esverbänd>en <geordnet>; sie sollen zuerst aufbrechen*.", footnotes: ["℘ Kap. 10,14-16"] },
      { number: 10, text: "Die Abteilung des Lagers Ruben gegen Süden hin, nach ihren Heer<esverbänd>en <geordnet>; und der Fürst der Söhne Ruben, Elizur, der Sohn Schedëurs," },
      { number: 11, text: "und sein Heer und dessen Gemusterte, 46 500." },
      { number: 12, text: "Und die neben ihm Lagernden, <das ist> der Stamm Simeon und der Fürst der Söhne Simeon, Schelumiël, der Sohn Zurischaddais," },
      { number: 13, text: "und sein Heer und ihre Gemusterten, 59 300." },
      { number: 14, text: "Und der Stamm Gad und der Fürst der Söhne Gad, Eljasaf, der Sohn Deguëls," },
      { number: 15, text: "und sein Heer und ihre Gemusterten, 45 650." },
      { number: 16, text: "Alle Gemusterten vom Lager Ruben: 151 450, nach ihren Heer<esverbänd>en <geordnet>; und sie sollen als Zweite aufbrechen*.", footnotes: ["℘ Kap. 10,18-20"] },
      { number: 17, text: "Und dann soll das Zelt der Begegnung aufbrechen, das Lager der Leviten in der Mitte der <andern> Lager; wie sie lagern, so sollen sie aufbrechen, jeder an seiner Stelle, nach ihren Abteilungen." },
      { number: 18, text: "Die Abteilung des Lagers Ephraim, nach ihren Heer<esverbänd>en <geordnet>, nach Westen hin; und der Fürst der Söhne Ephraim, Elischama, der Sohn Ammihuds," },
      { number: 19, text: "und sein Heer und ihre Gemusterten, 40 500." },
      { number: 20, text: "Und neben ihm der Stamm Manasse und der Fürst der Söhne Manasse, Gamliël, der Sohn Pedazurs," },
      { number: 21, text: "und sein Heer und ihre Gemusterten, 32 200." },
      { number: 22, text: "Und der Stamm Benjamin und der Fürst der Söhne Benjamin, Abidan, der Sohn des Gidoni," },
      { number: 23, text: "und sein Heer und ihre Gemusterten, 35 400." },
      { number: 24, text: "Alle Gemusterten vom Lager Ephraim: 108 100, nach ihren Heer<esverbänd>en <geordnet>; und sie sollen als Dritte aufbrechen*.", footnotes: ["℘ Kap. 10,22-24"] },
      { number: 25, text: "Die Abteilung des Lagers Dan nach Norden hin, nach ihren Heer<esverbänd>en <geordnet>: und der Fürst der Söhne Dan, Ahiëser, der Sohn Ammischaddais," },
      { number: 26, text: "und sein Heer und ihre Gemusterten, 62 700." },
      { number: 27, text: "Und die neben ihm Lagernden: der Stamm Asser und der Fürst der Söhne Asser, Pagiël, der Sohn Ochrans," },
      { number: 28, text: "und sein Heer und ihre Gemusterten, 41 500." },
      { number: 29, text: "Und der Stamm Naftali und der Fürst der Söhne Naftali, Ahira, der Sohn Enans," },
      { number: 30, text: "und sein Heer und ihre Gemusterten, 53 400." },
      { number: 31, text: "Alle Gemusterten vom Lager Dan: 157 600; sie sollen zuletzt aufbrechen nach ihren Abteilungen*.", footnotes: ["℘ Kap. 10,25-27"] },
      { number: 32, text: "Das sind die Gemusterten der Söhne Israel nach ihren Vaterhäusern. Alle Gemusterten der Lager, nach ihren Heer<esverbänd>en, waren 603 550*.", footnotes: ["℘ Kap. 1,46"] },
      { number: 33, text: "Aber die Leviten wurden nicht unter den Söhnen Israel gemustert, ganz wie der HERR dem Mose befohlen hatte*.", footnotes: ["℘ Kap. 1,49"] },
      { number: 34, text: "Und die Söhne Israel taten nach allem, was der HERR dem Mose geboten hatte*: So lagerten sie sich nach ihren Abteilungen, und so brachen sie auf, jeder nach seinen Sippen, bei seinem Vaterhaus*.", footnotes: ["℘ Kap. 1,19.54", "℘ Kap. 10,12.28"] },
    ]},
    { number: 3, verses: [
      { number: 1, text: "Und das ist die Generationenfolge* Aarons und Moses an dem Tag, da der HERR auf dem Berg Sinai mit Mose redete*.", heading: "Zählung der Leviten", footnotes: ["o. Entstehung, Entstehungsgeschichte; vgl. Anm. zu 1Mo 5,1", "℘ 3Mo 27,34"] },
      { number: 2, text: "Und das sind die Namen der Söhne Aarons: der Erstgeborene Nadab und Abihu, Eleasar und Itamar*.", footnotes: ["℘ 2Mo 6,23; 1Chr 5,29"] },
      { number: 3, text: "Das sind die Namen der Söhne Aarons, der gesalbten Priester, die geweiht worden waren*, um den Priesterdienst auszuüben*.", footnotes: ["w. deren Hand gefüllt worden war", "℘ 2Mo 28,41"] },
      { number: 4, text: "Und Nadab und Abihu starben vor dem HERRN, als sie in der Wüste Sinai fremdes Feuer vor dem HERRN darbrachten*; und sie hatten keine Söhne. Und Eleasar und Itamar übten den Priesterdienst vor ihrem Vater Aaron aus*.", footnotes: ["℘ Kap. 16,35; 26,61; 3Mo 10,1.2", "℘ 1Chr 24,1.2"] },
      { number: 5, text: "Und der HERR redete zu Mose und sprach:" },
      { number: 6, text: "Lass den Stamm Levi herannahen* und stelle ihn vor den Priester Aaron, dass sie ihm dienen*!", footnotes: ["℘ Kap. 16,10; 5Mo 10,8", "℘ Kap. 8,16.19; 18,2.6; 1Chr 6,33; 15,2; Esr 6,18"] },
      { number: 7, text: "Und sie sollen den Dienst für ihn und den Dienst für die ganze Gemeinde versehen vor dem Zelt der Begegnung, um die Arbeit <an> der Wohnung zu verrichten*;", footnotes: ["℘ Kap. 1,53"] },
      { number: 8, text: "und sie sollen alle Geräte des Zeltes der Begegnung in Ordnung halten und den Dienst der Söhne Israel <versehen>, um die Arbeit an der Wohnung zu verrichten*.", footnotes: ["℘ 1Chr 23,27-32; 2Chr 29,11"] },
      { number: 9, text: "Und du sollst die Leviten dem Aaron und seinen Söhnen geben; zu eigen sind sie ihm gegeben* von den Söhnen Israel*.", footnotes: ["w. Gegebene, <ja> Gegebene sind sie ihm. — Das Wort »Gegebene« wurde später zur Bezeichnung für die Tempeldiener; vgl. 1Chr 9,2; Esr 8,20.", "℘ Kap. 8,16.19; 18,2.6; 1Chr 6,33; 15,2; Esr 6,18"] },
      { number: 10, text: "Und Aaron und seine Söhne sollst du beauftragen, dass sie ihr Priesteramt versehen*. Der Fremde* aber, der sich <ihr> nähert, soll getötet werden*.", footnotes: ["℘ Kap. 18,7; 5Mo 18,5; 1Kö 12,31", "d. h. ein Unbefugter", "℘ V. 38; Kap. 1,51; Neh 6,11"] },
      { number: 11, text: "Und der HERR redete zu Mose und sprach:" },
      { number: 12, text: "Und ich, siehe, ich habe die Leviten mitten aus den Söhnen Israel genommen anstelle aller Erstgeburt, die zuerst den Mutterschoß durchbricht unter den Söhnen Israel; und die Leviten sollen mir gehören*.", footnotes: ["℘ V. 41.45; Kap. 8,16-18; 18,6"] },
      { number: 13, text: "Denn mein ist alle Erstgeburt: An dem Tag, da ich alle Erstgeburt im Land Ägypten schlug*, habe ich alle Erstgeburt in Israel für mich geheiligt vom Menschen bis zum Vieh*. Mir sollen sie gehören, mir, dem HERRN*.", footnotes: ["℘ Kap. 33,4; 2Mo 12,29", "℘ 2Mo 13,2.12", "℘ V. 41.45; Kap. 8,16-18; 18,6"] },
      { number: 14, text: "*Und der HERR redete zu Mose in der Wüste Sinai und sprach:", footnotes: ["℘ V. 14-39: vgl. 1Chr 6,1-48"] },
      { number: 15, text: "Mustere die Söhne Levis nach ihren Vaterhäusern, nach ihren Sippen; alles Männliche von einem Monat an und darüber sollst du mustern*!", footnotes: ["℘ V. 40; Kap. 1,3; 26,57"] },
      { number: 16, text: "Und Mose musterte sie nach dem Befehl des HERRN, wie ihm geboten worden war." },
      { number: 17, text: "*Und dies waren die Söhne Levis nach ihren Namen: Gerschon und Kehat und Merari*.", footnotes: ["℘ V. 17-39: Kap. 26,57-62", "℘ 1Mo 46,11; 1Chr 23,6"] },
      { number: 18, text: "Und dies sind die Namen der Söhne Gerschons nach ihren Sippen: Libni und Schimi*.", footnotes: ["℘ 2Mo 6,16-19; Sach 12,13"] },
      { number: 19, text: "Und die Söhne Kehats nach ihren Sippen: Amram und Jizhar, Hebron und Usiël*.", footnotes: ["℘ 2Mo 6,16-19; Sach 12,13"] },
      { number: 20, text: "Und die Söhne Meraris nach ihren Sippen: Machli und Muschi. Das sind die Sippen Levis nach ihren Vaterhäusern*.", footnotes: ["℘ 2Mo 6,16-19; Sach 12,13"] },
      { number: 21, text: "Von Gerschon: die Sippe der Libniter und die Sippe der Schimiter*; das sind die Sippen der Gerschoniter*.", footnotes: ["℘ 2Mo 6,16-19; Sach 12,13", "℘ Kap. 4,22"] },
      { number: 22, text: "Ihre Gemusterten nach der Zahl aller Männlichen von einem Monat an und darüber, ihre Gemusterten: 7 500." },
      { number: 23, text: "Die Sippen der Gerschoniter lagerten hinter der Wohnung nach Westen hin." },
      { number: 24, text: "Und der Fürst des Vaterhauses der Gerschoniter war Eljasaf, der Sohn Laëls." },
      { number: 25, text: "Und der Dienst der Söhne Gerschons am Zelt der Begegnung war: die Wohnung und das Zelt, seine Decke und der Vorhang vom Eingang des Zeltes der Begegnung" },
      { number: 26, text: "und die Behänge des Vorhofs und der Vorhang vom Eingang des Vorhofs, der rings um die Wohnung her und um den Altar her ist, und seine* Seile für alle Arbeit daran*.", footnotes: ["d. h. des Zeltes der Begegnung", "℘ Kap. 4,24-28"] },
      { number: 27, text: "Und von Kehat: die Sippe der Amramiter und die Sippe der Jizhariter und die Sippe der Hebroniter und die Sippe der Usiëliter; das sind die Sippen der Kehatiter*.", footnotes: ["℘ Kap. 4,2; Jos 21,5; 1Chr 23,12"] },
      { number: 28, text: "Nach der Zahl aller Männlichen von einem Monat an und darüber, 8 600, die den Dienst am Heiligtum versahen." },
      { number: 29, text: "Die Sippen der Söhne Kehats lagerten an der Seite der Wohnung nach Süden hin." },
      { number: 30, text: "Und der Fürst des Vaterhauses der Sippen der Kehatiter war Elizafan, der Sohn Usiëls*.", footnotes: ["℘ 2Mo 6,22"] },
      { number: 31, text: "Und ihr Dienst war: die Lade und der Tisch und der Leuchter und die Altäre und die Geräte des Heiligtums, mit denen man den Dienst verrichtet, und der Vorhang und alle <dazugehörige> Arbeit*.", footnotes: ["℘ Kap. 4,4-15; 5Mo 10,8"] },
      { number: 32, text: "Und der oberste der Fürsten* Levis war der Priester Eleasar, der Sohn Aarons; er war Aufseher über die, die den Dienst am Heiligtum versahen*.", footnotes: ["w. der Fürst der Fürsten", "℘ Hes 40,45"] },
      { number: 33, text: "Von Merari: die Sippe der Machliter und die Sippe der Muschiter; das sind die Sippen Meraris*.", footnotes: ["℘ Kap. 4,29; 1Chr 23,21"] },
      { number: 34, text: "Und ihre Gemusterten nach der Zahl aller Männlichen von einem Monat an und darüber: 6 200." },
      { number: 35, text: "Und der Fürst des Vaterhauses der Sippen Meraris war Zuriël, der Sohn Abihajils. Sie lagerten an der Seite der Wohnung nach Norden hin." },
      { number: 36, text: "Und der Dienst der Söhne Meraris war: die Bretter der Wohnung und ihre Riegel und ihre Säulen und ihre Fußgestelle und all ihre Geräte und alle Arbeit daran" },
      { number: 37, text: "und die Säulen des Vorhofs ringsum und deren Fußgestelle und ihre Pflöcke und ihre Seile*.", footnotes: ["℘ Kap. 4,29-33"] },
      { number: 38, text: "Und die vor der Wohnung nach Osten hin vor dem Zelt der Begegnung gegen <Sonnen>aufgang zu Lagernden waren Mose und Aaron und seine Söhne, die den Dienst am Heiligtum versahen, <alles,> was den Söhnen Israel aufgetragen war. — Der Fremde* aber, der sich <ihr> nähert, soll getötet werden.", footnotes: ["d. h. ein Unbefugter"] },
      { number: 39, text: "Alle gemusterten Leviten, die Mose und Aaron nach dem Befehl des HERRN nach ihren Sippen musterten, alles Männliche von einem Monat an und darüber, war 22 000." },
      { number: 40, text: "Und der HERR sprach zu Mose: Mustere alle männlichen Erstgeborenen der Söhne Israel von einem Monat an und darüber, und nimm die Zahl ihrer Namen auf*!", footnotes: ["℘ V. 15"] },
      { number: 41, text: "Und du sollst die Leviten für mich, den HERRN, nehmen anstelle aller Erstgeborenen unter den Söhnen Israel und das Vieh der Leviten anstelle alles Erstgeborenen unter dem Vieh der Söhne Israel*.", footnotes: ["℘ V. 12.13"] },
      { number: 42, text: "Und Mose musterte, wie der HERR es ihm geboten hatte, alle Erstgeborenen unter den Söhnen Israel." },
      { number: 43, text: "Und alle männlichen Erstgeborenen nach der Zahl der Namen, von einem Monat an und darüber, nach ihren Gemusterten, waren 22 273." },
      { number: 44, text: "Und der HERR redete zu Mose und sprach:" },
      { number: 45, text: "Nimm die Leviten anstelle aller Erstgeborenen unter den Söhnen Israel und das Vieh der Leviten anstelle ihres Viehes; und die Leviten sollen mir gehören, mir, dem HERRN*!", footnotes: ["℘ V. 12.13"] },
      { number: 46, text: "Und was den Loskauf der 273 betrifft: Die von den Erstgeborenen der Söhne Israel überzählig sind über die <Zahl der> Leviten <hinaus>," },
      { number: 47, text: "da sollst du je fünf Schekel für den Kopf nehmen; nach dem Schekel des Heiligtums sollst du sie nehmen, den Schekel zu zwanzig Gera*.", footnotes: ["℘ Kap. 7,13; 18,16; 2Mo 30,13"] },
      { number: 48, text: "Und das Geld sollst du als Loskauf der Überzähligen unter ihnen an Aaron und seine Söhne geben." },
      { number: 49, text: "Und Mose nahm das Geld des Loskaufs von denen, die überzählig waren über die durch die Leviten Losgekauften <hinaus>;" },
      { number: 50, text: "von den Erstgeborenen der Söhne Israel nahm er das Geld, 1 365 <Schekel> nach dem Schekel des Heiligtums." },
      { number: 51, text: "Und Mose gab das Geld des Loskaufs Aaron und seinen Söhnen nach dem Befehl des HERRN, wie der HERR dem Mose geboten hatte*.", footnotes: ["℘ Kap. 1,19.54; 2Mo 12,50"] },
    ]},
    { number: 4, verses: [
      { number: 1, text: "Und der HERR redete zu Mose und zu Aaron und sprach:", heading: "Dienst der Leviten beim Aufbruch des Lagers" },
      { number: 2, text: "Nimm die Summe der Söhne Kehats aus der Mitte der Söhne Levis auf, nach ihren Sippen, nach ihren Vaterhäusern*,", footnotes: ["℘ Kap. 3,27.28"] },
      { number: 3, text: "von dreißig Jahren an und darüber* bis zu fünfzig Jahren, alle, die in den Dienst* treten, um die Arbeit am Zelt der Begegnung zu verrichten!*", footnotes: ["℘ V. 47; Kap. 1,3; 1Chr 23,3.24.27", "Das Wort bedeutet an anderen Stellen Kriegsdienst.", "℘ V. 23.30.47; Kap. 8,24-26"] },
      { number: 4, text: "Das ist der Dienst der Söhne Kehats am Zelt der Begegnung: das Hochheilige." },
      { number: 5, text: "Und Aaron und seine Söhne sollen beim Aufbruch des Lagers hineingehen und den verhüllenden Vorhang* abnehmen und die Lade des Zeugnisses damit bedecken*;", footnotes: ["℘ 2Mo 26,31-33", "℘ 2Mo 40,3"] },
      { number: 6, text: "und sie sollen eine Decke aus Delfinhaut* darüber legen und ein Tuch ganz aus violettem Purpur oben darüber breiten und ihre Stangen daran anbringen*.", footnotes: ["w. aus Tachaschhaut. — Wahrscheinlich Haut des großen Tümmlers, einer Delfinart; nach anderen: aus Dachsfell, o. aus Seekuhhäuten, o. aus weich gegerbtem Leder", "℘ 2Mo 25,10-21"] },
      { number: 7, text: "Und über den Tisch der Schaubrote sollen sie ein Tuch aus violettem Purpur breiten und darauf die Schüsseln und Schalen und Opferschalen stellen und die Kannen* zum Trankopfer; und das ständige Brot soll auf ihm sein;", footnotes: ["o. Trinkschalen"] },
      { number: 8, text: "und darüber sollen sie ein Tuch aus Karmesin breiten und es mit einer Decke aus Delfinhaut* bedecken; und sie sollen seine Stangen daran anbringen*.", footnotes: ["w. aus Tachaschhaut. — Wahrscheinlich Haut des großen Tümmlers, einer Delfinart; nach anderen: aus Dachsfell, o. aus Seekuhhäuten, o. aus weich gegerbtem Leder", "℘ 2Mo 25,23-30"] },
      { number: 9, text: "Und sie sollen ein Tuch aus violettem Purpur nehmen und den Leuchter des Lichts bedecken und seine Lampen und seine Dochtscheren und seine Feuerbecken* und alle seine Ölgefäße, womit man den Dienst an ihm verrichtet;", footnotes: ["Das sind Gefäße zur Aufbewahrung oder zum Transport brennender Kohlen."] },
      { number: 10, text: "und sie sollen ihn und alle seine Geräte in eine Decke aus Delfinhaut* tun und <alles> auf die Trage legen*.", footnotes: ["w. aus Tachaschhaut. — Wahrscheinlich Haut des großen Tümmlers, einer Delfinart; nach anderen: aus Dachsfell, o. aus Seekuhhäuten, o. aus weich gegerbtem Leder", "℘ 2Mo 25,31-39"] },
      { number: 11, text: "Und über den goldenen Altar sollen sie ein Tuch aus violettem Purpur breiten und ihn mit einer Decke aus Delfinhaut* bedecken und seine Stangen daran anbringen*.", footnotes: ["w. aus Tachaschhaut. — Wahrscheinlich Haut des großen Tümmlers, einer Delfinart; nach anderen: aus Dachsfell, o. aus Seekuhhäuten, o. aus weich gegerbtem Leder", "℘ 2Mo 30,1-5"] },
      { number: 12, text: "Und sie sollen alle Geräte des Dienstes nehmen, womit man den Dienst im Heiligtum verrichtet*, und sie in ein Tuch aus violettem Purpur legen und sie mit einer Decke aus Delfinhaut* bedecken und auf die Trage legen.", footnotes: ["℘ 2Mo 25,9; 1Chr 9,28", "w. aus Tachaschhaut. — Wahrscheinlich Haut des großen Tümmlers, einer Delfinart; nach anderen: aus Dachsfell, o. aus Seekuhhäuten, o. aus weich gegerbtem Leder"] },
      { number: 13, text: "Und sie sollen den Altar von der Fettasche reinigen und ein Tuch aus rotem Purpur über ihn breiten" },
      { number: 14, text: "und auf ihn alle seine Geräte legen, mit denen man den Dienst auf ihm verrichtet: die Feuerbecken* und die Fleischgabeln und die Schaufeln und die Sprengschalen, alle Geräte des Altars; und sie sollen eine Decke aus Delfinhaut* darüber breiten und seine Stangen daran anbringen*.", footnotes: ["Das sind Gefäße zur Aufbewahrung oder zum Transport brennender Kohlen.", "w. aus Tachaschhaut. — Wahrscheinlich Haut des großen Tümmlers, einer Delfinart; nach anderen: aus Dachsfell, o. aus Seekuhhäuten, o. aus weich gegerbtem Leder", "℘ 2Mo 27,1-8"] },
      { number: 15, text: "Und wenn Aaron und seine Söhne beim Aufbruch des Lagers das Zudecken des Heiligtums und aller Geräte des Heiligtums beendet haben, dann sollen danach die Söhne Kehats kommen, um es zu tragen*, damit sie das Heilige nicht berühren und sterben*. Das ist es, was die Söhne Kehats vom Zelt der Begegnung zu tragen haben*.", footnotes: ["℘ Kap. 3,31; 7,9; 10,21; 2Sam 15,24; 1Kö 8,3; 1Chr 15,2.15", "℘ Kap. 1,51; 18,3; 2Mo 19,21", "℘ Kap. 3,31"] },
      { number: 16, text: "Und der Priester Eleasar, der Sohn Aarons, hat die Aufsicht über das Öl für das Licht und <über> das wohlriechende Räucherwerk und das ständige Speisopfer und das Salböl*, die Aufsicht über die ganze Wohnung und alles, was darin ist, über das Heiligtum und über seine Geräte.", footnotes: ["℘ 2Mo 25,6; 29,40-42; 30,23-38"] },
      { number: 17, text: "Und der HERR redete zu Mose und zu Aaron und sprach:" },
      { number: 18, text: "Ihr sollt den Stamm der Sippen der Kehatiter nicht umkommen lassen aus der Mitte der Leviten*;", footnotes: ["℘ 2Mo 30,33.38"] },
      { number: 19, text: "sondern das sollt ihr mit ihnen tun, damit sie leben und nicht sterben*, wenn sie dem Allerheiligsten nahen: Aaron und seine Söhne sollen hineingehen und sie, jeden einzeln, an seine Arbeit und an seine Traglast stellen;", footnotes: ["℘ Kap. 1,51; 18,3; 2Mo 19,21"] },
      { number: 20, text: "aber sie sollen nicht hineingehen, dass sie <auch nur> einen Augenblick das Heilige sehen und sterben*.", footnotes: ["℘ Kap. 1,51; 18,3; 2Mo 19,21"] },
      { number: 21, text: "Und der HERR redete zu Mose und sprach:" },
      { number: 22, text: "Nimm auch die Summe der Söhne Gerschon auf, nach ihren Vaterhäusern, nach ihren Sippen*!", footnotes: ["℘ Kap. 3,21.22"] },
      { number: 23, text: "Von dreißig Jahren an und darüber bis zu fünfzig Jahren sollst du sie mustern, alle, die in den Dienst* treten, um die Arbeit am Zelt der Begegnung zu verrichten*.", footnotes: ["s. Anm. zu V. 3", "℘ V. 3"] },
      { number: 24, text: "Dies ist die Arbeit der Sippen der Gerschoniter beim Arbeiten und beim Tragen:" },
      { number: 25, text: "Sie sollen tragen die Zeltdecken der Wohnung und das Zelt der Begegnung, seine Decke und die Decke aus Delfinhaut*, die oben darüber ist, und den Vorhang vom Eingang des Zeltes der Begegnung*", footnotes: ["w. aus Tachaschhaut. — Wahrscheinlich Haut des großen Tümmlers, einer Delfinart; nach anderen: aus Dachsfell, o. aus Seekuhhäuten, o. aus weich gegerbtem Leder", "℘ Kap. 3,25.26; 2Mo 26,1-14.36"] },
      { number: 26, text: "und die Behänge des Vorhofs und den Vorhang vom Eingang des Tores des Vorhofs, der rings um die Wohnung und um den Altar herum ist, und ihre Seile und alle Geräte<, die zu> ihrer Arbeit <gehören>; und alles, was an ihnen zu tun ist, sollen sie ausführen*.", footnotes: ["℘ 2Mo 27,9.11.16.19"] },
      { number: 27, text: "Nach dem Befehl Aarons und seiner Söhne soll alle Arbeit der Söhne der Gerschoniter geschehen hinsichtlich all ihrer Traglast und all ihrer Arbeit; und ihr sollt ihnen den Dienst für alles das übertragen, was sie zu tragen haben." },
      { number: 28, text: "Das ist die Arbeit der Sippen der Söhne der Gerschoniter am Zelt der Begegnung*; und ihr Dienst soll geschehen unter der Hand des Priesters Itamar*, des Sohnes Aarons.", footnotes: ["℘ Kap. 7,7", "℘ 2Mo 38,21"] },
      { number: 29, text: "Die Söhne Meraris: Nach ihren Sippen, nach ihren Vaterhäusern sollst du sie mustern*;", footnotes: ["℘ Kap. 3,33.34"] },
      { number: 30, text: "von dreißig Jahren an und darüber bis zu fünfzig Jahren sollst du sie mustern, alle, die in den Dienst treten, um die Arbeit am Zelt der Begegnung zu verrichten*.", footnotes: ["℘ V. 3"] },
      { number: 31, text: "Und das ist der Dienst, den sie beim Tragen zu tun haben* bei all ihrer Arbeit am Zelt der Begegnung: die Bretter der Wohnung und ihre Riegel und ihre Säulen und ihre Fußgestelle*", footnotes: ["w. das ist der Dienst ihrer Traglast", "℘ 2Mo 26,15-29"] },
      { number: 32, text: "und die Säulen des Vorhofs ringsum und ihre Fußgestelle und ihre Pflöcke und ihre Seile mit allen ihren Geräten und mit all der Arbeit daran. Und mit Namen sollt ihr <ihnen> die Geräte zuweisen für den Dienst, den sie beim Tragen zu tun haben*.", footnotes: ["w. für den Dienst ihrer Traglast\n℘ V. 49; Kap. 3,36.37; 2Mo 27,9-19; Eph 4,7"] },
      { number: 33, text: "Das ist die Arbeit der Sippen der Söhne Meraris nach all ihrer Arbeit am Zelt der Begegnung unter der Hand des Priesters Itamar*, des Sohnes Aarons*.", footnotes: ["℘ Kap. 7,8", "℘ Kap. 7,8"] },
      { number: 34, text: "Und Mose und Aaron und die Fürsten der Gemeinde* musterten die Söhne der Kehatiter nach ihren Sippen und nach ihren Vaterhäusern,", footnotes: ["℘ Kap. 1,4"] },
      { number: 35, text: "von dreißig Jahren an und darüber bis zu fünfzig Jahren, alle, die in den Dienst* traten zur Arbeit am Zelt der Begegnung.", footnotes: ["s. Anm. zu V. 3"] },
      { number: 36, text: "Und ihre Gemusterten, nach ihren Sippen, waren 2 750." },
      { number: 37, text: "Das sind die Gemusterten der Sippen der Kehatiter, alle, die am Zelt der Begegnung dienten, die Mose und Aaron musterten nach dem Befehl des HERRN<, den er> durch Mose <gegeben hatte>." },
      { number: 38, text: "Und die Gemusterten der Söhne Gerschons, nach ihren Sippen und nach ihren Vaterhäusern," },
      { number: 39, text: "von dreißig Jahren an und darüber bis zu fünfzig Jahren, alle, die in den Dienst* traten zur Arbeit am Zelt der Begegnung:", footnotes: ["s. Anm. zu V. 3"] },
      { number: 40, text: "ihre Gemusterten, nach ihren Sippen, nach ihren Vaterhäusern, waren 2 630." },
      { number: 41, text: "Das sind die Gemusterten der Sippen der Söhne Gerschons, alle, die am Zelt der Begegnung arbeiteten, die Mose und Aaron musterten nach dem Befehl des HERRN." },
      { number: 42, text: "Und die Gemusterten der Sippen der Söhne Meraris, nach ihren Sippen, nach ihren Vaterhäusern," },
      { number: 43, text: "von dreißig Jahren an und darüber bis zu fünfzig Jahren, alle, die in den Dienst* traten zur Arbeit am Zelt der Begegnung:", footnotes: ["s. Anm. zu V. 3"] },
      { number: 44, text: "ihre Gemusterten, nach ihren Sippen, waren 3 200." },
      { number: 45, text: "Das sind die Gemusterten der Sippen der Söhne Meraris, die Mose und Aaron musterten nach dem Befehl des HERRN<, den er> durch Mose <gegeben hatte>." },
      { number: 46, text: "Alle Gemusterten, die Mose und Aaron und die Fürsten Israels musterten, die Leviten, nach ihren Sippen und nach ihren Vaterhäusern," },
      { number: 47, text: "von dreißig Jahren an und darüber* bis zu fünfzig Jahren, alle, die antraten, um die Arbeit der Betreuung* und die Arbeit des Tragens am Zelt der Begegnung zu verrichten*:", footnotes: ["℘ V. 3", "w. die Arbeit der Arbeit <am Zelt>", "℘ Kap. 7,8"] },
      { number: 48, text: "ihre Gemusterten waren 8 580." },
      { number: 49, text: "Nach dem Befehl des HERRN musterte man sie durch Mose, jeden Einzelnen zu seiner Arbeit und zu seiner Traglast; und sie wurden von ihm gemustert, wie der HERR dem Mose befohlen hatte." },
    ]},
    { number: 5, verses: [
      { number: 1, text: "Und der HERR redete zu Mose und sprach:", heading: "Verfahren bei Unreinheit, Veruntreuung und bei Verdacht auf Ehebruch" },
      { number: 2, text: "Befiehl den Söhnen Israel, dass sie alle Aussätzigen* und alle, die an einem Ausfluss leiden*, und alle durch eine Leiche* Verunreinigten* aus dem Lager hinausschicken!", footnotes: ["℘ Kap. 12,14; 3Mo 13,45.46", "℘ 3Mo 15,2-15", "w. Seele", "℘ Kap. 19,11-16"] },
      { number: 3, text: "Sowohl Mann als auch Frau sollt ihr hinausschicken, vor das Lager sollt ihr sie hinausschicken, damit sie nicht ihr Lager unrein machen, in deren Mitte ich wohne*.", footnotes: ["℘ 3Mo 15,31; 5Mo 23,15"] },
      { number: 4, text: "Und die Söhne Israel taten so und schickten sie vor das Lager hinaus*; wie der HERR zu Mose geredet hatte, so taten die Söhne Israel*.", footnotes: ["℘ 2Chr 26,21", "℘ 2Mo 12,50"] },
      { number: 5, text: "Und der HERR redete zu Mose und sprach:" },
      { number: 6, text: "Rede zu den Söhnen Israel: Wenn ein Mann oder eine Frau irgendeine von all den Sünden der Menschen tun, so dass sie eine Untreue gegen den HERRN begehen, und dieser Mensch* schuldig wird*,", footnotes: ["w. diese Seele", "℘ 3Mo 5,21.22"] },
      { number: 7, text: "dann sollen sie ihre Sünde bekennen*, die sie getan haben; und der Schuldige* soll seine Schuld erstatten nach ihrer vollen Summe und soll <noch> ein Fünftel davon hinzufügen* und es dem geben, an dem er schuldig geworden ist.", footnotes: ["℘ 3Mo 5,5; Jos 7,19", "w. er", "℘ 3Mo 5,16.24"] },
      { number: 8, text: "Und wenn der <andere> Mann keinen Löser hat, dem die Schuld erstattet werden kann, dann gehört der erstattete Schuldbetrag dem HERRN zugunsten des Priesters, ebenso wie der Widder der Versöhnung, womit der Priester* Sühnung für ihn erwirkt*. —", footnotes: ["w. er", "℘ 3Mo 7,7"] },
      { number: 9, text: "Und jedes Hebopfer von allen heiligen Gaben* der Söhne Israel, die sie dem Priester darbringen, soll ihm gehören*.", footnotes: ["o. heilige(n) Dinge(n)\n℘ 5Mo 12,26", "℘ 2Mo 29,28"] },
      { number: 10, text: "Ihm sollen eines jeden heilige Gaben* gehören; was jemand dem Priester gibt, soll diesem gehören*.", footnotes: ["o. heilige(n) Dinge(n)", "℘ 2Mo 29,28"] },
      { number: 11, text: "Und der HERR redete zu Mose und sprach:" },
      { number: 12, text: "Rede zu den Söhnen Israel und sage zu ihnen: Wenn die Frau irgendeines Mannes auf Abwege gerät und Untreue gegen ihn begeht*,", footnotes: ["℘ 2Mo 20,14"] },
      { number: 13, text: "und ein <anderer> Mann liegt bei ihr zur Begattung, und es bleibt* verborgen vor den Augen ihres Mannes, und sie hat sich im Verborgenen unrein gemacht*, und es ist kein Zeuge gegen sie da, und sie ist nicht ertappt worden*;", footnotes: ["w. ist", "℘ Hes 33,26", "℘ Spr 7,18-21"] },
      { number: 14, text: "und der Geist der Eifersucht kommt über ihn, und er wird eifersüchtig auf seine Frau, und sie hat sich <wirklich> unrein gemacht; oder <aber> der Geist der Eifersucht kommt über ihn, und er wird eifersüchtig auf seine Frau, und sie hat sich nicht unrein gemacht:" },
      { number: 15, text: "Dann soll der Mann seine Frau zum Priester bringen und <als> ihre Opfergabe* ihretwegen ein zehntel Efa Gerstenmehl darbringen; er soll kein Öl darauf gießen und keinen Weihrauch darauf legen; denn es ist ein Speisopfer der Eifersucht, ein Erinnerungsspeisopfer, das Schuld in Erinnerung bringt.", footnotes: ["℘ 3Mo 1,2"] },
      { number: 16, text: "Und der Priester soll sie herantreten lassen und sie vor den HERRN stellen." },
      { number: 17, text: "Und der Priester nehme heiliges Wasser in einem Tongefäß; und der Priester nehme von dem Staub, der auf dem Fußboden der Wohnung ist und tue ihn in das Wasser." },
      { number: 18, text: "Und der Priester stelle die Frau vor den HERRN und lasse das Haupthaar der Frau herabhängen und lege auf ihre Hände das Erinnerungsspeisopfer; es ist ein Speisopfer der Eifersucht; und das Fluch bringende Wasser der Bitterkeit soll in der Hand des Priesters sein." },
      { number: 19, text: "Und der Priester soll sie beschwören und zu der Frau sprechen: Wenn kein Mann bei dir gelegen hat und wenn du, die du unter deinem Mann bist, nicht auf Abwege geraten bist in Unreinheit, dann bleibe unversehrt von diesem Fluch bringenden Wasser der Bitterkeit!" },
      { number: 20, text: "Wenn du aber, die du unter deinem Mann bist, auf Abwege geraten bist und dich unrein gemacht hast und ein Mann bei dir gelegen hat außer deinem <eigenen> Mann —" },
      { number: 21, text: "und <so> soll der Priester die Frau beschwören mit dem Schwur der Verfluchung*; und der Priester soll zu der Frau sprechen —: Dann mache der HERR dich zur Verfluchung und zum Schwur inmitten deines Volkes, indem der HERR deine Hüfte schwinden und deinen Bauch anschwellen lässt,", footnotes: ["o. und <so> soll der Priester die Frau den Schwur der Verfluchung schwören lassen"] },
      { number: 22, text: "und es komme dieses Fluch bringende Wasser in deine Eingeweide, um den Bauch anschwellen und die Hüfte schwinden zu lassen! Und die Frau soll sagen: Amen, Amen*!", footnotes: ["℘ Ps 41,14"] },
      { number: 23, text: "Und der Priester soll diese Verfluchungen in ein Buch schreiben und sie in das Wasser der Bitterkeit <hinein> abwischen;" },
      { number: 24, text: "und er soll die Frau das Fluch bringende Wasser der Bitterkeit trinken lassen, damit das Fluch bringende Wasser zur Bitterkeit in sie komme." },
      { number: 25, text: "Und der Priester nehme aus der Hand der Frau das Speisopfer der Eifersucht und schwinge das Speisopfer vor dem HERRN und bringe es zum Altar;" },
      { number: 26, text: "und der Priester nehme eine Handvoll von dem Speisopfer als dessen Askara* und räuchere es auf dem Altar*; und danach soll er die Frau das Wasser trinken lassen.", footnotes: ["d. i. der zu verbrennende Teil des Speisopfers", "℘ 3Mo 2,2.9"] },
      { number: 27, text: "Und wenn er sie das Wasser hat trinken lassen, dann wird es geschehen, wenn sie sich unrein gemacht und Untreue begangen hat gegen ihren Mann, dass das Fluch bringende Wasser zur Bitterkeit in sie kommen wird, und ihr Bauch wird anschwellen und ihre Hüfte schwinden; und die Frau wird zum Fluch werden inmitten ihres Volkes*.", footnotes: ["℘ Ps 109,18"] },
      { number: 28, text: "Wenn aber die Frau sich nicht unrein gemacht hat und rein ist, dann wird sie unversehrt bleiben und Samen empfangen." },
      { number: 29, text: "Das ist das Gesetz der Eifersucht: Wenn eine Frau, die unter ihrem Mann ist, auf Abwege gerät und sich unrein macht*", footnotes: ["℘ Hes 33,26"] },
      { number: 30, text: "oder wenn über einen Mann der Geist der Eifersucht kommt und er eifersüchtig wird auf seine Frau, dann soll er die Frau vor den HERRN stellen, und der Priester soll <mit> ihr tun nach diesem ganzen Gesetz." },
      { number: 31, text: "Und der Mann wird frei sein von Schuld; eine solche Frau aber soll ihre Schuld tragen*.", footnotes: ["℘ Mt 1,19; Hebr 13,4"] },
    ]},
    { number: 6, verses: [
      { number: 1, text: "Und der HERR redete zu Mose:", heading: "Gesetz des Abgesonderten" },
      { number: 2, text: "Rede zu den Söhnen Israel und sprich zu ihnen: Wenn <jemand,> ein Mann oder eine Frau, etwas Besonderes tut, indem er das Gelübde* eines Nasiräers* gelobt*, um für den HERRN geweiht zu sein,", footnotes: ["℘ Kap. 30,3", "d. h. eines Abgesonderten, o. Geweihten", "℘ Apg 21,23.24"] },
      { number: 3, text: "dann soll er sich des Weins und des Rauschtranks enthalten: Essig von Wein und Essig von Rauschtrank soll er nicht trinken*; und keinerlei Traubensaft soll er trinken, und <auch> Trauben, frische oder getrocknete, soll er nicht essen.", footnotes: ["℘ 3Mo 10,9; Ri 13,4.14; Am 2,12; Lk 1,15"] },
      { number: 4, text: "Alle Tage seiner Weihe soll er von allem, was vom Weinstock bereitet wird, von den Kernen bis zu den Schalen, nicht essen." },
      { number: 5, text: "Alle Tage des Gelübdes seiner Weihe soll kein Schermesser über sein Haupt kommen. Bis die Tage erfüllt sind, die er sich für den HERRN geweiht hat, soll er heilig sein; er soll das Haar seines Hauptes frei wachsen lassen*.", footnotes: ["℘ Ri 16,17.19"] },
      { number: 6, text: "Alle Tage, die er sich für den HERRN geweiht hat, soll er sich keiner Leiche nähern*.", footnotes: ["w. nicht zu der Seele eines Toten hineingehen\n℘ Kap. 19,11.16"] },
      { number: 7, text: "Wegen seines Vaters und wegen seiner Mutter, wegen seines Bruders und wegen seiner Schwester, <auch> ihretwegen soll er sich nicht unrein machen, wenn sie sterben; denn die Weihe seines Gottes ist auf seinem Haupt*.", footnotes: ["℘ 3Mo 21,10-12"] },
      { number: 8, text: "Alle Tage seiner Weihe ist er dem HERRN heilig*.", footnotes: ["℘ 1Sam 1,27.28"] },
      { number: 9, text: "Und wenn jemand unversehens <und> plötzlich neben ihm stirbt und er das Haupt seiner Weihe unrein macht, dann soll er sein Haupt an dem Tag seiner Reinigung scheren; am siebten Tag soll er es scheren." },
      { number: 10, text: "Und am achten Tag soll er zwei Turteltauben oder zwei junge Tauben zum Priester bringen an den Eingang des Zeltes der Begegnung." },
      { number: 11, text: "Und der Priester soll die eine als Sündopfer und die andere als Brandopfer opfern und Sühnung für ihn erwirken, weil er sich an einer Leiche* versündigt hat*; und <der Priester> soll sein Haupt an diesem Tag <wieder> heiligen.", footnotes: ["w. an der Seele", "℘ 3Mo 5,7-10"] },
      { number: 12, text: "Und er soll die Tage seiner Weihe <nochmals> für den HERRN weihen und ein einjähriges Lamm als Schuldopfer darbringen; die vorigen Tage aber sind verfallen, weil seine Weihe unrein gemacht worden ist." },
      { number: 13, text: "Und dies ist das Gesetz des Nasiräers*: An dem Tag, an dem die Tage seiner Weihe erfüllt sind, soll man ihn an den Eingang des Zeltes der Begegnung bringen.", footnotes: ["s. Anm. zu V. 2"] },
      { number: 14, text: "Und er soll dem HERRN seine Gabe darbringen: ein einjähriges Lamm ohne Fehler als Brandopfer* und ein einjähriges weibliches Lamm ohne Fehler als Sündopfer und einen Widder ohne Fehler als Heilsopfer*", footnotes: ["℘ 3Mo 1,10", "o. Friedensopfer; o. Abschlussopfer; o. Gemeinschaftsopfer\n℘ 3Mo 3,6"] },
      { number: 15, text: "und einen Korb mit ungesäuerten Broten: Weizengrieß-Kuchen, gemengt* mit Öl, und ungesäuerte Fladen, bestrichen* mit Öl*, und das dazugehörende Speisopfer und die dazugehörenden Trankopfer*.", footnotes: ["o. angefeuchtet", "w. gesalbt", "℘ 3Mo 7,12", "℘ Kap. 15,3-7"] },
      { number: 16, text: "Und der Priester soll sie vor dem HERRN darbringen und sein Sündopfer und sein Brandopfer opfern." },
      { number: 17, text: "Und den Widder soll er als Heilsopfer* dem HERRN opfern samt dem Korb mit ungesäuerten Broten; und der Priester soll sein Speisopfer und sein Trankopfer opfern.", footnotes: ["o. Friedensopfer; o. Abschlussopfer; o. Gemeinschaftsopfer"] },
      { number: 18, text: "Und der Nasiräer* soll an dem Eingang des Zeltes der Begegnung sein geweihtes Haupt scheren* und das Haar seines geweihten Hauptes nehmen und es auf das Feuer legen, das unter dem Heilsopfer* ist.", footnotes: ["s. Anm. zu V. 2", "℘ Apg 21,24", "o. Friedensopfer; o. Abschlussopfer; o. Gemeinschaftsopfer"] },
      { number: 19, text: "Und der Priester nehme die gekochte Vorderkeule von dem Widder und einen ungesäuerten Kuchen und einen ungesäuerten Fladen aus dem Korb und lege sie auf die Hände des Nasiräers*, nachdem er <das Zeichen> seiner Weihe abgeschoren hat.", footnotes: ["s. Anm. zu V. 2"] },
      { number: 20, text: "Und der Priester schwinge sie als Schwingopfer vor dem HERRN; es ist dem Priester heilig samt der Brust des Schwingopfers und samt dem Schenkel des Hebopfers*. Und danach kann der Nasiräer* Wein trinken.", footnotes: ["℘ 2Mo 29,27.28; 3Mo 7,32-34", "s. Anm. zu V. 2"] },
      { number: 21, text: "Das ist das Gesetz des Nasiräers*, der aufgrund seiner Weihe dem HERRN seine Gabe gelobt, abgesehen von dem, was seine Hand <sonst noch> aufbringen kann. Gemäß seinem Gelübde, das er abgelegt hat, soll er tun, nach dem Gesetz seiner Weihe*.", footnotes: ["s. Anm. zu V. 2", "℘ Apg 21,26"] },
      { number: 22, text: "Und der HERR redete zu Mose und sprach:", heading: "Der priesterliche Segen" },
      { number: 23, text: "Rede zu Aaron und zu seinen Söhnen und sprich: So sollt ihr die Söhne Israel segnen*! Sprecht zu ihnen:", footnotes: ["℘ 3Mo 9,22; 1Chr 23,13; 2Chr 30,27"] },
      { number: 24, text: "Der HERR segne dich* und behüte dich*!", footnotes: ["℘ Rt 2,4", "℘ Ps 121,7.8"] },
      { number: 25, text: "Der HERR lasse sein Angesicht über dir leuchten* und sei dir gnädig!*", footnotes: ["℘ Ps 4,7; 119,135; Dan 9,17", "℘ 1Mo 43,29"] },
      { number: 26, text: "Der HERR erhebe sein Angesicht auf dich und gebe dir Frieden!*", footnotes: ["℘ Jes 26,12; Joh 14,27; 16,33; 20,19; 2Thes 3,16; 3Jo 15"] },
      { number: 27, text: "Und so sollen sie meinen Namen* auf die Söhne Israel legen, und ich werde sie segnen*.", footnotes: ["℘ 2Chr 7,14; Dan 9,19", "℘ Kap. 23,20; Ps 115,12-15"] },
    ]},
    { number: 7, verses: [
      { number: 1, text: "Und es geschah an dem Tag, da Mose das Aufrichten der Wohnung vollendet und sie gesalbt und mit allen ihren Geräten geheiligt hatte* sowie den Altar und alle seine Geräte und er sie gesalbt und geheiligt hatte,", heading: "Gaben der Stammesfürsten für das Heiligtum", footnotes: ["℘ 2Mo 29,36; 30,29; 40,9-11"] },
      { number: 2, text: "brachten die Fürsten Israels, die Häupter ihrer Vaterhäuser, sie, die Fürsten der Stämme, die Führer der Gemusterten*,", footnotes: ["℘ Kap. 1,4-16"] },
      { number: 3, text: "sie brachten ihre Gabe vor den HERRN: sechs Planwagen und zwölf Rinder, einen Wagen für zwei Fürsten und ein Rind für einen; und sie brachten sie vor die Wohnung." },
      { number: 4, text: "Und der HERR redete zu Mose und sprach:" },
      { number: 5, text: "Nimm sie von ihnen an, und sie sollen zur Verwendung bei der Arbeit an dem Zelt der Begegnung sein, und gib sie den Leviten, jedem entsprechend seiner Arbeit!" },
      { number: 6, text: "Und Mose nahm die Wagen und die Rinder und gab sie den Leviten." },
      { number: 7, text: "Zwei Wagen und vier Rinder gab er den Söhnen Gerschons, entsprechend ihrer Arbeit*;", footnotes: ["℘ Kap. 4,24-28"] },
      { number: 8, text: "und vier Wagen und acht Rinder gab er den Söhnen Meraris, entsprechend ihrer Arbeit* unter der Hand des Priesters Itamar, des Sohnes Aarons.", footnotes: ["℘ Kap. 4,29-33"] },
      { number: 9, text: "Aber den Söhnen Kehats gab er nichts; denn ihnen oblag die Arbeit am Heiligtum: auf der Schulter trugen sie <es>*.", footnotes: ["℘ Kap. 4,4-15; 2Sam 6,3"] },
      { number: 10, text: "Und die Fürsten brachten die Einweihungsgabe* des Altars an dem Tag, da er gesalbt wurde; und die Fürsten brachten ihre Gabe vor den Altar.", footnotes: ["℘ 1Kö 8,63"] },
      { number: 11, text: "Und der HERR sprach zu Mose: Sie sollen täglich — jeweils ein Fürst — ihre Gabe zur Einweihung des Altars bringen." },
      { number: 12, text: "*Und es geschah, der, der am ersten Tag seine Gabe brachte, war Nachschon, der Sohn Amminadabs, vom Stamm Juda.", footnotes: ["℘ V. 12-78: Kap. 1,5-15; 1Mo 35,23-26"] },
      { number: 13, text: "Und seine Gabe war: eine silberne Schüssel, 130 <Schekel> ihr Gewicht, eine silberne Sprengschale, siebzig Schekel nach dem Schekel<gewicht> des Heiligtums*, beide voller Weizengrieß, gemengt* mit Öl, zum Speisopfer*;", footnotes: ["℘ Kap. 3,47", "o. angefeuchtet", "℘ Kap. 15,4; 28,5.13; 29,6; 3Mo 2,1"] },
      { number: 14, text: "eine Schale, zehn <Schekel> Gold, voller Räucherwerk*;", footnotes: ["℘ 2Mo 30,34-37"] },
      { number: 15, text: "ein Jungstier, ein Widder, ein einjähriges Lamm zum Brandopfer*;", footnotes: ["℘ 3Mo 1,2.3.10"] },
      { number: 16, text: "ein Ziegenbock* zum Sündopfer*;", footnotes: ["w. Haariger/n der Ziegen", "℘ 3Mo 4,23"] },
      { number: 17, text: "und zum Heilsopfer* zwei Rinder, fünf Widder, fünf Böcke, fünf einjährige Lämmer*. Das war die Gabe Nachschons, des Sohnes Amminadabs.", footnotes: ["o. Friedensopfer; o. Abschlussopfer; o. Gemeinschaftsopfer", "℘ 3Mo 3,1.6"] },
      { number: 18, text: "Am zweiten Tag brachte Netanel, der Sohn Zuars, der Fürst von Issaschar<, seine Gabe>;" },
      { number: 19, text: "er brachte seine Gabe: eine silberne Schüssel, 130 <Schekel> ihr Gewicht, eine silberne Sprengschale, siebzig Schekel nach dem Schekel<gewicht> des Heiligtums, beide voller Weizengrieß, gemengt* mit Öl, zum Speisopfer;", footnotes: ["o. angefeuchtet"] },
      { number: 20, text: "eine Schale, zehn <Schekel> Gold, voller Räucherwerk;" },
      { number: 21, text: "einen Jungstier, einen Widder, ein einjähriges Lamm zum Brandopfer;" },
      { number: 22, text: "einen Ziegenbock* zum Sündopfer;", footnotes: ["w. Haariger/n der Ziegen"] },
      { number: 23, text: "und zum Heilsopfer* zwei Rinder, fünf Widder, fünf Böcke, fünf einjährige Lämmer. Das war die Gabe Netanels, des Sohnes Zuars.", footnotes: ["o. Friedensopfer; o. Abschlussopfer; o. Gemeinschaftsopfer"] },
      { number: 24, text: "Am dritten Tag der Fürst der Söhne Sebulon, Eliab, der Sohn Helons." },
      { number: 25, text: "Seine Gabe war: eine silberne Schüssel, 130 <Schekel> ihr Gewicht, eine silberne Sprengschale, siebzig Schekel nach dem Schekel<gewicht> des Heiligtums, beide voller Weizengrieß, gemengt* mit Öl, zum Speisopfer;", footnotes: ["o. angefeuchtet"] },
      { number: 26, text: "eine Schale, zehn <Schekel> Gold, voller Räucherwerk;" },
      { number: 27, text: "ein Jungstier, ein Widder, ein einjähriges Lamm zum Brandopfer;" },
      { number: 28, text: "ein Ziegenbock* zum Sündopfer;", footnotes: ["w. Haariger/n der Ziegen"] },
      { number: 29, text: "und zum Heilsopfer* zwei Rinder, fünf Widder, fünf Böcke, fünf einjährige Lämmer. Das war die Gabe Eliabs, des Sohnes Helons.", footnotes: ["o. Friedensopfer; o. Abschlussopfer; o. Gemeinschaftsopfer"] },
      { number: 30, text: "Am vierten Tag der Fürst der Söhne Ruben, Elizur, der Sohn Schedëurs." },
      { number: 31, text: "Seine Gabe war: eine silberne Schüssel, 130 <Schekel> ihr Gewicht, eine silberne Sprengschale, siebzig Schekel nach dem Schekel<gewicht> des Heiligtums, beide voller Weizengrieß, gemengt* mit Öl, zum Speisopfer;", footnotes: ["o. angefeuchtet"] },
      { number: 32, text: "eine Schale, zehn <Schekel> Gold, voller Räucherwerk;" },
      { number: 33, text: "ein Jungstier, ein Widder, ein einjähriges Lamm zum Brandopfer;" },
      { number: 34, text: "ein Ziegenbock* zum Sündopfer;", footnotes: ["w. Haariger/n der Ziegen"] },
      { number: 35, text: "und zum Heilsopfer* zwei Rinder, fünf Widder, fünf Böcke, fünf einjährige Lämmer. Das war die Opfergabe Elizurs, des Sohnes Schedëurs.", footnotes: ["o. Friedensopfer; o. Abschlussopfer; o. Gemeinschaftsopfer"] },
      { number: 36, text: "Am fünften Tag der Fürst der Söhne Simeon, Schelumiël, der Sohn Zurischaddais." },
      { number: 37, text: "Seine Gabe war: eine silberne Schüssel, 130 <Schekel> ihr Gewicht, eine silberne Sprengschale, siebzig Schekel nach dem Schekel<gewicht> des Heiligtums, beide voller Weizengrieß, gemengt* mit Öl, zum Speisopfer;", footnotes: ["o. angefeuchtet"] },
      { number: 38, text: "eine Schale, zehn <Schekel> Gold, voller Räucherwerk;" },
      { number: 39, text: "ein Jungstier, ein Widder, ein einjähriges Lamm zum Brandopfer;" },
      { number: 40, text: "ein Ziegenbock* zum Sündopfer;", footnotes: ["w. Haariger/n der Ziegen"] },
      { number: 41, text: "und zum Heilsopfer* zwei Rinder, fünf Widder, fünf Böcke, fünf einjährige Lämmer. Das war die Gabe Schelumiëls, des Sohnes Zurischaddais.", footnotes: ["o. Friedensopfer; o. Abschlussopfer; o. Gemeinschaftsopfer"] },
      { number: 42, text: "Am sechsten Tag der Fürst der Söhne Gad, Eljasaf, der Sohn Deguëls." },
      { number: 43, text: "Seine Gabe war: eine silberne Schüssel, 130 <Schekel> ihr Gewicht, eine silberne Sprengschale, siebzig Schekel nach dem Schekel<gewicht> des Heiligtums, beide voller Weizengrieß, gemengt* mit Öl, zum Speisopfer;", footnotes: ["o. angefeuchtet"] },
      { number: 44, text: "eine Schale, zehn <Schekel> Gold, voller Räucherwerk;" },
      { number: 45, text: "ein Jungstier, ein Widder, ein einjähriges Lamm zum Brandopfer;" },
      { number: 46, text: "ein Ziegenbock* zum Sündopfer;", footnotes: ["w. Haariger/n der Ziegen"] },
      { number: 47, text: "und zum Heilsopfer* zwei Rinder, fünf Widder, fünf Böcke, fünf einjährige Lämmer. Das war die Gabe Eljasafs, des Sohnes Deguëls.", footnotes: ["o. Friedensopfer; o. Abschlussopfer; o. Gemeinschaftsopfer"] },
      { number: 48, text: "Am siebten Tag der Fürst der Söhne Ephraim, Elischama, der Sohn Ammihuds." },
      { number: 49, text: "Seine Gabe war: eine silberne Schüssel, 130 <Schekel> ihr Gewicht, eine silberne Sprengschale, siebzig Schekel nach dem Schekel<gewicht> des Heiligtums, beide voller Weizengrieß, gemengt* mit Öl, zum Speisopfer;", footnotes: ["o. angefeuchtet"] },
      { number: 50, text: "eine Schale, zehn <Schekel> Gold, voller Räucherwerk;" },
      { number: 51, text: "ein Jungstier, ein Widder, ein einjähriges Lamm zum Brandopfer;" },
      { number: 52, text: "ein Ziegenbock* zum Sündopfer;", footnotes: ["w. Haariger/n der Ziegen"] },
      { number: 53, text: "und zum Heilsopfer* zwei Rinder, fünf Widder, fünf Böcke, fünf einjährige Lämmer. Das war die Gabe Elischamas, des Sohnes Ammihuds.", footnotes: ["o. Friedensopfer; o. Abschlussopfer; o. Gemeinschaftsopfer"] },
      { number: 54, text: "Am achten Tag der Fürst der Söhne Manasse, Gamliël, der Sohn Pedazurs." },
      { number: 55, text: "Seine Gabe war: eine silberne Schüssel, 130 <Schekel> ihr Gewicht, eine silberne Sprengschale, siebzig Schekel nach dem Schekel<gewicht> des Heiligtums, beide voller Weizengrieß, gemengt* mit Öl, zum Speisopfer;", footnotes: ["o. angefeuchtet"] },
      { number: 56, text: "eine Schale, zehn <Schekel> Gold, voller Räucherwerk;" },
      { number: 57, text: "ein Jungstier, ein Widder, ein einjähriges Lamm zum Brandopfer;" },
      { number: 58, text: "ein Ziegenbock* zum Sündopfer;", footnotes: ["w. Haariger der Ziegen"] },
      { number: 59, text: "und zum Heilsopfer* zwei Rinder, fünf Widder, fünf Böcke, fünf einjährige Lämmer. Das war die Gabe Gamliëls, des Sohnes Pedazurs.", footnotes: ["o. Friedensopfer; o. Abschlussopfer; o. Gemeinschaftsopfer"] },
      { number: 60, text: "Am neunten Tag der Fürst der Söhne Benjamin, Abidan, der Sohn des Gidoni." },
      { number: 61, text: "Seine Gabe war: eine silberne Schüssel, 130 <Schekel> ihr Gewicht, eine silberne Sprengschale, siebzig Schekel nach dem Schekel<gewicht> des Heiligtums, beide voller Weizengrieß, gemengt* mit Öl, zum Speisopfer;", footnotes: ["o. angefeuchtet"] },
      { number: 62, text: "eine Schale, zehn <Schekel> Gold, voller Räucherwerk;" },
      { number: 63, text: "ein Jungstier, ein Widder, ein einjähriges Lamm zum Brandopfer;" },
      { number: 64, text: "ein Ziegenbock* zum Sündopfer;", footnotes: ["w. Haariger der Ziegen"] },
      { number: 65, text: "und zum Heilsopfer* zwei Rinder, fünf Widder, fünf Böcke, fünf einjährige Lämmer. Das war die Gabe Abidans, des Sohnes des Gidoni.", footnotes: ["o. Friedensopfer; o. Abschlussopfer; o. Gemeinschaftsopfer"] },
      { number: 66, text: "Am zehnten Tag der Fürst der Söhne Dan, Ahiëser, der Sohn Ammischaddais." },
      { number: 67, text: "Seine Gabe war: eine silberne Schüssel, 130 <Schekel> ihr Gewicht, eine silberne Sprengschale, siebzig Schekel nach dem Schekel<gewicht> des Heiligtums, beide voller Weizengrieß, gemengt* mit Öl, zum Speisopfer;", footnotes: ["o. angefeuchtet"] },
      { number: 68, text: "eine Schale, zehn <Schekel> Gold, voller Räucherwerk;" },
      { number: 69, text: "ein Jungstier, ein Widder, ein einjähriges Lamm zum Brandopfer;" },
      { number: 70, text: "ein Ziegenbock* zum Sündopfer;", footnotes: ["w. Haariger der Ziegen"] },
      { number: 71, text: "und zum Heilsopfer* zwei Rinder, fünf Widder, fünf Böcke, fünf einjährige Lämmer. Das war die Gabe Ahiësers, des Sohnes Ammischaddais.", footnotes: ["o. Friedensopfer; o. Abschlussopfer; o. Gemeinschaftsopfer"] },
      { number: 72, text: "Am elften Tag der Fürst der Söhne Asser, Pagiël, der Sohn Ochrans." },
      { number: 73, text: "Seine Gabe war: eine silberne Schüssel, 130 <Schekel> ihr Gewicht, eine silberne Sprengschale, siebzig Schekel nach dem Schekel<gewicht> des Heiligtums, beide voller Weizengrieß, gemengt* mit Öl, zum Speisopfer;", footnotes: ["o. angefeuchtet"] },
      { number: 74, text: "eine Schale, zehn <Schekel> Gold, voller Räucherwerk;" },
      { number: 75, text: "ein Jungstier, ein Widder, ein einjähriges Lamm zum Brandopfer;" },
      { number: 76, text: "ein Ziegenbock* zum Sündopfer;", footnotes: ["w. Haariger der Ziegen"] },
      { number: 77, text: "und zum Heilsopfer* zwei Rinder, fünf Widder, fünf Böcke, fünf einjährige Lämmer. Das war die Gabe Pagiëls, des Sohnes Ochrans.", footnotes: ["o. Friedensopfer; o. Abschlussopfer; o. Gemeinschaftsopfer"] },
      { number: 78, text: "Am zwölften Tag der Fürst der Söhne Naftali, Ahira, der Sohn Enans." },
      { number: 79, text: "Seine Gabe war: eine silberne Schüssel, 130 <Schekel> ihr Gewicht, eine silberne Sprengschale, siebzig Schekel nach dem Schekel<gewicht> des Heiligtums, beide voller Weizengrieß, gemengt* mit Öl, zum Speisopfer;", footnotes: ["o. angefeuchtet"] },
      { number: 80, text: "eine Schale, zehn <Schekel> Gold, voller Räucherwerk;" },
      { number: 81, text: "ein Jungstier, ein Widder, ein einjähriges Lamm zum Brandopfer;" },
      { number: 82, text: "ein Ziegenbock* zum Sündopfer;", footnotes: ["w. Haariger der Ziegen"] },
      { number: 83, text: "und zum Heilsopfer* zwei Rinder, fünf Widder, fünf Böcke, fünf einjährige Lämmer. Das war die Gabe Ahiras, des Sohnes Enans.", footnotes: ["o. Friedensopfer; o. Abschlussopfer; o. Gemeinschaftsopfer"] },
      { number: 84, text: "Das war die Einweihungsgabe des Altars von den Fürsten Israels an dem Tag, da er gesalbt wurde: zwölf silberne Schüsseln, zwölf silberne Sprengschalen, zwölf goldene Schalen;" },
      { number: 85, text: "130 <Schekel wog> eine silberne Schüssel und siebzig eine Sprengschale, alles Silber der Gefäße war 2 400 <Schekel> nach dem Schekel<gewicht> des Heiligtums;" },
      { number: 86, text: "zwölf goldene Schalen voller Räucherwerk, je zehn <Schekel> eine Schale nach dem Schekel<gewicht> des Heiligtums: alles Gold der Schalen war 120 <Schekel>." },
      { number: 87, text: "Alle Rinder zum Brandopfer waren <zusammen> zwölf Stiere; <dazu> zwölf Widder, zwölf einjährige Lämmer, samt ihrem Speisopfer; und zwölf Ziegenböcke* zum Sündopfer.", footnotes: ["w. Haarige der Ziegen"] },
      { number: 88, text: "Und alle Rinder zum Heilsopfer* waren <zusammen> vierundzwanzig Stiere; <dazu> sechzig Widder, sechzig Böcke, sechzig einjährige Lämmer. Das war die Einweihungsgabe des Altars, nachdem er gesalbt worden war.", footnotes: ["o. Friedensopfer; o. Abschlussopfer; o. Gemeinschaftsopfer"] },
      { number: 89, text: "Und wenn Mose in das Zelt der Begegnung hineinging, um mit ihm zu reden*, dann hörte er die Stimme zu ihm reden von der Deckplatte* herab, die auf der Lade des Zeugnisses war, zwischen den beiden Cherubim hervor*; und er redete zu ihm.", footnotes: ["℘ Kap. 11,17; 12,8; 2Mo 33,9.11", "s. Anm. zu 3Mo 16,2", "℘ 2Mo 25,22"] },
    ]},
    { number: 8, verses: [
      { number: 1, text: "*Und der HERR redete zu Mose und sprach:", heading: "Gesetz über den Leuchter im Heiligtum und über die Weihe der Leviten", footnotes: ["℘ V. 1-4: 2Mo 25,31-40"] },
      { number: 2, text: "Rede zu Aaron und sage zu ihm: Wenn du die Lampen aufsetzt, dann sollen die sieben Lampen <den Raum> vor dem Leuchter erhellen." },
      { number: 3, text: "Und Aaron machte es so: Er setzte dessen Lampen auf<, so dass sie den Raum> vor dem Leuchter <erhellten>, wie der HERR dem Mose befohlen hatte*.", footnotes: ["℘ 2Mo 39,37; 40,25"] },
      { number: 4, text: "Und das war die Machart des Leuchters: Getriebene Arbeit in Gold; von seinem Fuß bis zu seinen Blüten, alles war getriebene Arbeit; nach der Gestalt, die der HERR dem Mose gezeigt, so hatte man* den Leuchter gemacht.", footnotes: ["w. er"] },
      { number: 5, text: "Und der HERR redete zu Mose und sprach:" },
      { number: 6, text: "Nimm die Leviten aus der Mitte der Söhne Israel und reinige sie*!", footnotes: ["℘ 5Mo 10,8; Mal 3,3"] },
      { number: 7, text: "Und so sollst du mit ihnen tun, um sie zu reinigen: Sprenge Entsündigungswasser* auf sie, und sie sollen das Schermesser über ihren ganzen Körper* gehen lassen und ihre Kleider waschen und sich reinigen*.", footnotes: ["℘ Kap. 19,9", "w. über ihr ganzes Fleisch", "℘ 3Mo 14,8.9"] },
      { number: 8, text: "Und sie sollen einen Jungstier nehmen und das dazugehörige Speisopfer: Weizengrieß, gemengt* mit Öl*; und einen andern Jungstier sollst du zum Sündopfer nehmen.", footnotes: ["o. angefeuchtet", "℘ 3Mo 2,1"] },
      { number: 9, text: "Und du sollst die Leviten vor das Zelt der Begegnung hinzutreten lassen* und die ganze Gemeinde der Söhne Israel versammeln*.", footnotes: ["℘ 2Mo 29,4", "℘ 3Mo 8,3"] },
      { number: 10, text: "Und du sollst die Leviten vor den HERRN hintreten lassen, und die Söhne Israel sollen ihre Hände auf die Leviten legen." },
      { number: 11, text: "Und Aaron soll die Leviten als Schwingopfer von den Söhnen Israel vor dem HERRN darbringen*, damit sie zum Verrichten des Dienstes für den HERRN da sind*.", footnotes: ["w. schwingen", "℘ 5Mo 10,8"] },
      { number: 12, text: "Und die Leviten sollen ihre Hände auf den Kopf der Stiere legen; und den einen sollst du als Sündopfer und den anderen als Brandopfer dem HERRN opfern, um für die Leviten Sühnung zu erwirken*.", footnotes: ["℘ 3Mo 8,14.15"] },
      { number: 13, text: "Und so sollst du die Leviten vor Aaron und vor seine Söhne stellen und sie dem HERRN als Schwingopfer darbringen*.", footnotes: ["w. schwingen"] },
      { number: 14, text: "Und du sollst die Leviten aus der Mitte der Söhne Israel aussondern, damit die Leviten mir gehören*.", footnotes: ["℘ Kap. 3,9.12"] },
      { number: 15, text: "Und danach sollen die Leviten kommen, um das Zelt der Begegnung zu bedienen. So sollst du sie reinigen und sie als Schwingopfer darbringen*.", footnotes: ["w. schwingen"] },
      { number: 16, text: "Denn sie sind mir ganz zu eigen gegeben aus der Mitte der Söhne Israel*, als Ersatz für alles*, was den Mutterschoß durchbricht, <für> jeden Erstgeborenen aus den Söhnen Israel habe ich sie für mich genommen.", footnotes: ["℘ Kap. 3,9.12", "w. anstelle all dessen"] },
      { number: 17, text: "Denn mir <gehört> alles Erstgeborene unter den Söhnen Israel an Menschen und an Vieh. An dem Tag, da ich alle Erstgeburt im Land Ägypten schlug*, habe ich sie für mich geheiligt.", footnotes: ["℘ 2Mo 12,29"] },
      { number: 18, text: "Und ich habe die Leviten genommen als Ersatz für alle* Erstgeborenen unter den Söhnen Israel*;", footnotes: ["w. anstelle aller", "℘ Kap. 3,9.12"] },
      { number: 19, text: "und ich habe die Leviten dem Aaron und seinen Söhnen als Gabe* aus der Mitte der Söhne Israel gegeben*, den Dienst der Söhne Israel am Zelt der Begegnung auszuüben und für die Söhne Israel Sühnung zu erwirken, damit unter den Söhnen Israel keine Plage dadurch entsteht, dass die Söhne Israel sich dem Heiligtum nähern*.", footnotes: ["w. als Gegebene; vgl. Anm. zu Kap. 3,9", "℘ Kap. 3,6", "℘ Kap. 1,50-54; 2Mo 12,50"] },
      { number: 20, text: "Und Mose und Aaron und die ganze Gemeinde der Söhne Israel machten es so mit den Leviten; nach allem, was der HERR dem Mose wegen der Leviten geboten hatte, so machten es die Söhne Israel mit ihnen*.", footnotes: ["℘ Kap. 1,50-54; 2Mo 12,50"] },
      { number: 21, text: "Und die Leviten entsündigten sich und wuschen ihre Kleider; und Aaron brachte sie als Schwingopfer vor dem HERRN dar*; und Aaron erwirkte Sühnung für sie zu ihrer Reinigung.", footnotes: ["w. und Aaron schwang sie als Schwingopfer vor dem HERRN"] },
      { number: 22, text: "Danach kamen die Leviten, um ihren Dienst am Zelt der Begegnung auszuüben vor Aaron und vor seinen Söhnen. Ganz wie der HERR dem Mose hinsichtlich der Leviten geboten hatte, so machten sie es mit ihnen*.", footnotes: ["℘ Kap. 1,50-54; 2Mo 12,50"] },
      { number: 23, text: "Und der HERR redete zu Mose und sprach:" },
      { number: 24, text: "Das ist es, was für die Leviten <gilt>: Von fünfundzwanzig Jahren an und darüber soll er eintreten, um die Arbeit zu tun im Dienst am Zelt der Begegnung*.", footnotes: ["℘ Kap. 4,3.23.30.47"] },
      { number: 25, text: "Aber von fünfzig Jahren an soll er aus der Arbeit des Dienstes austreten und nicht länger dienen;" },
      { number: 26, text: "er mag seinen Brüdern bei der Wahrnehmung der Aufgaben am Zelt der Begegnung helfen, aber Arbeit soll er nicht <mehr> tun. So sollst du es mit den Leviten in ihren Aufgaben machen." },
    ]},
    { number: 9, verses: [
      { number: 1, text: "Und der HERR redete zu Mose in der Wüste Sinai, im zweiten Jahr nach ihrem Auszug aus dem Land Ägypten, im ersten Monat*, und sprach:", heading: "Passah und Nachpassah", footnotes: ["℘ Kap. 1,1"] },
      { number: 2, text: "Die Söhne Israel sollen das Passah feiern zu seiner festgesetzten Zeit*;", footnotes: ["℘ 2Mo 12,1-14"] },
      { number: 3, text: "am vierzehnten Tag in diesem Monat, zwischen den zwei Abenden*, sollt ihr es feiern zu seiner festgesetzten Zeit*; nach allen seinen Ordnungen und nach allen seinen Vorschriften sollt ihr es feiern.", footnotes: ["d. h. entweder zwischen Sonnenuntergang und völliger Nacht oder zwischen Niedergang (15 Uhr) und Untergang der Sonne", "℘ 2Mo 12,1-14"] },
      { number: 4, text: "Und Mose redete zu den Söhnen Israel, dass sie das Passah feiern sollten." },
      { number: 5, text: "Und sie feierten das Passah im ersten <Monat> am vierzehnten Tag des Monats, zwischen den zwei Abenden*, in der Wüste Sinai; nach allem, was der HERR dem Mose befohlen hatte, so machten es die Söhne Israel*.", footnotes: ["d. h. entweder zwischen Sonnenuntergang und völliger Nacht oder zwischen Niedergang (15 Uhr) und Untergang der Sonne", "℘ Kap. 8,20.22"] },
      { number: 6, text: "Aber es waren Männer da, die unrein waren wegen der Leiche* eines Menschen und an jenem Tag das Passah nicht feiern konnten*; und sie traten an jenem Tag vor Mose und vor Aaron*.", footnotes: ["w. Seele", "℘ Kap. 19,11.16; Joh 18,28", "℘ Kap. 27,2.21"] },
      { number: 7, text: "Und diese Männer sagten zu ihm: Wir sind unrein wegen der Leiche* eines Menschen. Warum soll es uns verwehrt sein*, die Opfergabe des HERRN nicht zur festgesetzten Zeit inmitten der Söhne Israel darzubringen*?", footnotes: ["w. Seele", "w. sollen wir verkürzt werden", "℘ 2Chr 30,17-19"] },
      { number: 8, text: "Und Mose sagte zu ihnen: Bleibt stehen, und ich will hören, was der HERR euretwegen gebietet*. —", footnotes: ["℘ Kap. 27,5; 3Mo 24,12"] },
      { number: 9, text: "Und der HERR redete zu Mose und sprach:" },
      { number: 10, text: "Rede zu den Söhnen Israel: Wenn irgendjemand bei euch oder bei euren <künftigen> Generationen unrein ist wegen einer Leiche*, oder er ist auf einer weiten Reise* und will <trotzdem> dem HERRN Passah feiern:", footnotes: ["w. Seele", "w. auf einem fernen Weg"] },
      { number: 11, text: "im zweiten Monat, am vierzehnten Tag, zwischen den zwei Abenden*, sollen sie es feiern*; mit ungesäuertem Brot und bitteren Kräutern sollen sie es essen*;", footnotes: ["s. Anm. zu V. 3", "℘ 2Chr 30,2", "℘ 2Mo 12,8"] },
      { number: 12, text: "sie sollen nichts davon übrig lassen bis zum Morgen und sollen kein Bein* an ihm zerbrechen; nach allen Ordnungen des Passah sollen sie es feiern*.", footnotes: ["o. keinen Knochen", "℘ 2Mo 12,10.46"] },
      { number: 13, text: "Der Mann aber, der rein ist und nicht auf einer Reise* und es unterlässt, das Passah zu feiern, diese Seele soll ausgerottet werden aus ihren Völkern*; denn er hat die Opfergabe des HERRN nicht zur festgesetzten Zeit dargebracht; dieser Mann soll seine Sünde tragen*.", footnotes: ["w. auf einem Weg", "d. h. aus ihrer Volksgemeinschaft\n℘ Kap. 15,30.31; 19,13.20; 2Mo 30,33.38", "℘ 3Mo 24,15"] },
      { number: 14, text: "Und wenn ein Fremder bei euch wohnt und dem HERRN Passah feiern will, soll er es feiern nach der Ordnung des Passah und nach seiner Vorschrift. Ein <und dieselbe> Ordnung soll für euch sein, sowohl für den Fremden als auch für den Einheimischen des Landes*.", footnotes: ["℘ 2Mo 12,48.49; Esr 6,21"] },
      { number: 15, text: "Und an dem Tag, als die Wohnung aufgestellt wurde, bedeckte die Wolke die Wohnung des Zeltes des Zeugnisses*; und am Abend war sie über der Wohnung wie das Aussehen* eines Feuers* bis zum Morgen*.", heading: "Wolken- und Feuersäule", footnotes: ["℘ Kap. 17,7; 2Mo 40,34; Offb 15,5.8", "o. die Erscheinung", "℘ 2Mo 40,38", "℘ Kap. 10,34; 14,14; 2Mo 13,21"] },
      { number: 16, text: "So war es ständig: die Wolke bedeckte sie, und des Nachts <war es wie> das Aussehen* eines Feuers*.", footnotes: ["o. die Erscheinung", "℘ 2Mo 40,38"] },
      { number: 17, text: "Und sooft die Wolke sich von dem Zelt erhob, brachen danach die Söhne Israel auf; und an dem Ort, wo die Wolke sich niederließ*, dort lagerten die Söhne Israel*.", footnotes: ["o. ruhte", "℘ Kap. 10,11.12.33.34"] },
      { number: 18, text: "Nach dem Befehl des HERRN brachen die Söhne Israel auf, und nach dem Befehl des HERRN lagerten sie; alle Tage, während die Wolke auf der Wohnung ruhte, lagerten sie." },
      { number: 19, text: "Und wenn die Wolke viele Tage auf der Wohnung stehen blieb, verrichteten die Söhne Israel den Dienst des HERRN und brachen nicht auf." },
      { number: 20, text: "Und es kam vor, dass die Wolke <nur> wenige Tage auf der Wohnung war — nach dem Befehl des HERRN lagerten sie sich, und nach dem Befehl des HERRN brachen sie <auch> auf." },
      { number: 21, text: "Und es kam vor, dass die Wolke <nur> vom Abend bis zum <nächsten> Morgen da war und die Wolke sich am Morgen erhob, dann brachen sie auf. Oder einen Tag und eine Nacht* — erhob sich die Wolke, so brachen sie auf.", footnotes: ["w. bei Tag und bei Nacht"] },
      { number: 22, text: "Oder <dauerte es> zwei Tage oder einen Monat oder eine längere Zeit* — wenn die Wolke auf der Wohnung verweilte, indem sie darauf ruhte, dann lagerten die Söhne Israel und brachen nicht auf; und wenn sie sich <dann> erhob, brachen sie auf.", footnotes: ["w. oder Tage"] },
      { number: 23, text: "Nach dem Befehl des HERRN lagerten sie, und nach dem Befehl des HERRN brachen sie auf; sie verrichteten den Dienst des HERRN nach dem Befehl des HERRN durch Mose*.", footnotes: ["℘ Kap. 10,13; 2Mo 17,1"] },
    ]},
    { number: 10, verses: [
      { number: 1, text: "Und der HERR redete zu Mose und sprach:", heading: "Silberne Trompeten" },
      { number: 2, text: "Mache dir zwei Trompeten aus Silber! In getriebener Arbeit sollst du sie machen; und sie sollen dir zur Berufung der Gemeinde und zum Aufbruch der Lager dienen*.", footnotes: ["℘ Jer 4,5; Joe 2,1.15.16"] },
      { number: 3, text: "Bläst man sie <beide>, dann soll sich die ganze Gemeinde zu dir versammeln am Eingang des Zeltes der Begegnung*.", footnotes: ["℘ Jer 4,5; Joe 2,1.15.16"] },
      { number: 4, text: "Und wenn man <nur> eine bläst, dann sollen sich die Fürsten zu dir versammeln, die Häupter der Tausendschaften Israels*.", footnotes: ["℘ Kap. 1,16; 7,2"] },
      { number: 5, text: "Und blast ihr das Lärmsignal, dann sollen die Lager aufbrechen, die nach Osten hin lagern*;", footnotes: ["℘ Kap. 2,3"] },
      { number: 6, text: "und blast ihr das Lärmsignal zum zweiten Mal, dann sollen die Lager aufbrechen, die nach Süden hin lagern*; zu ihrem Aufbruch sollen sie das Lärmsignal blasen*.", footnotes: ["℘ Kap. 2,10", "w. Lärm schlagen"] },
      { number: 7, text: "Aber um die Versammlung zu versammeln, sollt ihr <nur> blasen, aber kein Lärmsignal geben." },
      { number: 8, text: "Die Söhne Aarons, die Priester, sollen in die Hörner stoßen. Das soll für euch zur ewigen Ordnung sein bei euren Generationen." },
      { number: 9, text: "Und wenn ihr in eurem Land in den Kampf zieht gegen den Bedränger, der euch bedrängt*, dann sollt ihr mit den Trompeten das Lärmsignal geben*; und es wird an euch gedacht werden vor dem HERRN, eurem Gott, und ihr werdet gerettet werden vor euren Feinden*.", footnotes: ["℘ 5Mo 20,1", "w. Lärm schlagen\n℘ Kap. 31,6", "℘ 2Chr 13,12-15"] },
      { number: 10, text: "Und an euren Freudentagen und an euren Festen* und an euren Neumonden* sollt ihr in die Trompeten blasen* bei euren Brandopfern und bei euren Heilsopfern*; und sie sollen euch bei eurem Gott in Erinnerung bringen. Ich bin der HERR, euer Gott.", footnotes: ["o. zu euren Festzeiten", "w. an den Anfängen eurer Monate\n℘ 1Sam 20,5", "℘ 3Mo 25,9; Jos 6,4; Ps 81,4", "o. Friedensopfern; o. Abschlussopfern; o. Gemeinschaftsopfern"] },
      { number: 11, text: "Und es geschah im zweiten Jahr, im zweiten Monat, am zwanzigsten <Tag> des Monats*, da erhob sich die Wolke von der Wohnung des Zeugnisses*.", heading: "Aufbruch vom Sinai", footnotes: ["℘ Kap. 1,1", "℘ Kap. 9,17"] },
      { number: 12, text: "Und die Söhne Israel brachen auf nach ihrer Aufbruchsordnung* aus der Wüste Sinai*; und die Wolke ließ sich nieder* in der Wüste Paran*.", footnotes: ["w. nach ihren Aufbrüchen\n℘ 5Mo 1,7.19", "℘ Kap. 33,16; 2Mo 19,1.2", "o. ruhte", "℘ Kap. 12,16; 13,3.26; 1Mo 21,21; 1Kö 11,18"] },
      { number: 13, text: "So brachen sie zum ersten Mal auf nach dem Befehl des HERRN durch Mose*.", footnotes: ["℘ Kap. 9,20-23"] },
      { number: 14, text: "*Und die Abteilung des Lagers der Söhne Juda brach zuerst auf nach ihren Heer<esverbänd>en*; und über seinem Heer<esverband> war Nachschon, der Sohn Amminadabs.", footnotes: ["℘ V. 14-27: Kap. 1,5-15; 1Mo 35,23-26", "℘ Kap. 2,9"] },
      { number: 15, text: "Und über dem Heer<esverband> des Stammes der Söhne Issaschar war Netanel, der Sohn Zuars;" },
      { number: 16, text: "und über dem Heer<esverband> des Stammes der Söhne Sebulon war Eliab, der Sohn Helons." },
      { number: 17, text: "Und die Wohnung wurde abgebaut*, und es brachen auf die Söhne Gerschon und die Söhne Merari, die die Wohnung trugen*.", footnotes: ["℘ Kap. 1,51", "℘ Kap. 4,24-33"] },
      { number: 18, text: "Und die Abteilung des Lagers Ruben brach auf nach seinen Heer<esverbänd>en*; und über seinem Heer<esverband> war Elizur, der Sohn Schedëurs.", footnotes: ["℘ Kap. 2,16"] },
      { number: 19, text: "Und über dem Heer<esverband> des Stammes der Söhne Simeon war Schelumiël, der Sohn Zurischaddais;" },
      { number: 20, text: "und über dem Heer<esverband> des Stammes der Söhne Gad war Eljasaf, der Sohn Deguëls." },
      { number: 21, text: "Und die Kehatiter brachen auf, die das Heiligtum trugen*; und man richtete die Wohnung auf*, bis sie <an>kamen.", footnotes: ["℘ Kap. 4,15", "℘ Kap. 1,51"] },
      { number: 22, text: "Und die Abteilung des Lagers der Söhne Ephraim brach auf nach ihren Heer<esverbänd>en*; und über seinem Heer<esverband> war Elischama, der Sohn Ammihuds.", footnotes: ["℘ Kap. 2,24"] },
      { number: 23, text: "Und über dem Heer<esverband> des Stammes der Söhne Manasse war Gamliël, der Sohn Pedazurs;" },
      { number: 24, text: "und über dem Heer<esverband> des Stammes der Söhne Benjamin war Abidan, der Sohn des Gidoni." },
      { number: 25, text: "Und die Abteilung des Lagers der Söhne Dan, das die Nachhut aller Lager bildete, brach auf nach ihren Heer<esverbänd>en*; und über seinem Heer<esverband> war Ahiëser, der Sohn Ammischaddais.", footnotes: ["℘ Kap. 2,31"] },
      { number: 26, text: "Und über dem Heer<esverband> des Stammes der Söhne Asser war Pagiël, der Sohn Ochrans;" },
      { number: 27, text: "und über dem Heer<esverband> des Stammes der Söhne Naftali war Ahira, der Sohn Enans. —" },
      { number: 28, text: "Das war die Aufbruchsordnung* der Söhne Israel nach ihren Heer<esverbänd>en; und so brachen sie auf*.", footnotes: ["w. Das waren ihre Aufbrüche", "℘ Kap. 2,34"] },
      { number: 29, text: "Und Mose sagte zu Hobab*, dem Sohn Reguëls, des Midianiters, des Schwiegervaters Moses*: Wir brechen auf zu dem Ort, von dem der HERR gesagt hat: »Ich will ihn euch geben.«* Komm mit uns! Dann werden wir dir Gutes tun; denn der HERR hat Gutes über Israel geredet*.", footnotes: ["℘ Ri 1,16; 4,11", "℘ 2Mo 2,18-21", "℘ 1Mo 17,8; 2Mo 6,8", "d. h. hat Israel Gutes zugesagt"] },
      { number: 30, text: "Doch er sagte zu ihm: Ich will nicht mitkommen, sondern in mein Land und zu meiner Verwandtschaft will ich gehen*.", footnotes: ["℘ 2Mo 18,27"] },
      { number: 31, text: "Er aber sagte: Verlass uns doch nicht! Denn du weißt* doch, wo wir in der Wüste lagern können; und du sollst unser Auge* sein.", footnotes: ["o. erkennst", "w. unsere Augen"] },
      { number: 32, text: "Und es soll geschehen, wenn du mit uns kommst und jenes Gute geschieht, das der HERR an uns tun will, dann werden wir dir auch Gutes tun*.", footnotes: ["℘ 1Sam 14,6"] },
      { number: 33, text: "Und sie brachen auf von dem Berg des HERRN*, drei Tagereisen weit, und die Lade des Bundes des HERRN zog drei Tagereisen vor ihnen her, um ihnen einen Ruheplatz auszusuchen*;", footnotes: ["℘ 2Mo 3,1", "℘ 5Mo 1,33"] },
      { number: 34, text: "und die Wolke des HERRN war über ihnen am Tag*, wenn sie aus dem Lager zogen.", footnotes: ["℘ 2Mo 13,21; 40,38"] },
      { number: 35, text: "Und es geschah, wenn die Lade aufbrach, sagte Mose: Steh auf, HERR*, dass deine Feinde sich zerstreuen und deine Hasser vor dir fliehen*!", footnotes: ["℘ Ps 3,8", "℘ 1Sam 4,3; Ps 68,2"] },
      { number: 36, text: "Und wenn sie ruhte, sagte er: Kehre zurück, HERR*, zu der großen Menge* der Tausendschaften Israels!*", footnotes: ["℘ Ps 90,13", "w. zu den Zehntausenden", "℘ Ps 132,8"] },
    ]},
    { number: 11, verses: [
      { number: 1, text: "Und es geschah, als das Volk sich in Klagen erging, da war es böse in den Ohren des HERRN. Und als der HERR es hörte*, da erglühte sein Zorn, und ein Feuer des HERRN brannte unter ihnen und fraß am Rand des Lagers*.", heading: "Begehren nach Fleisch — Moses Resignation — Siebzig Älteste — Wachteln und Gottesgericht", footnotes: ["℘ Kap. 12,2", "℘ Kap. 16,35; 5Mo 9,22; Ps 78,21"] },
      { number: 2, text: "Und das Volk schrie zu Mose*; und Mose betete zu dem HERRN*, da legte sich das Feuer*.", footnotes: ["℘ Kap. 21,7", "℘ 2Mo 10,18", "℘ 5Mo 9,19"] },
      { number: 3, text: "Und man gab diesem Ort den Namen Tabera, weil ein Feuer des HERRN unter ihnen gebrannt hatte*.", footnotes: ["℘ Kap. 16,35; 5Mo 9,22; Ps 78,21"] },
      { number: 4, text: "Und das hergelaufene <Volk>, das in ihrer Mitte war*, gierte voller Begierde, und auch die Söhne Israel weinten* wieder und sagten: Wer wird uns Fleisch zu essen geben*?", footnotes: ["℘ 2Mo 12,38", "℘ Kap. 14,1", "℘ V. 18; 2Mo 16,12; Ps 78,18-20; 1Kor 10,6"] },
      { number: 5, text: "Wir denken an die Fische, die wir in Ägypten umsonst aßen, an die Gurken und an die Melonen und an den Lauch und an die Zwiebeln und an den Knoblauch*;", footnotes: ["℘ 2Mo 16,3; Jer 42,14"] },
      { number: 6, text: "und nun ist unsere Kehle* vertrocknet; gar nichts ist da, nur auf das Manna <sehen> unsere Augen*.", footnotes: ["o. Seele", "℘ Kap. 21,5"] },
      { number: 7, text: "Das Manna aber war wie Koriandersamen* und sein Aussehen wie das Aussehen des Bdelliumharzes*.", footnotes: ["℘ 2Mo 16,23.31", "℘ 1Mo 2,12"] },
      { number: 8, text: "Das Volk lief umher, und sie sammelten <es> und mahlten es mit Handmühlen oder zerstießen es in Mörsern; und sie kochten es in Töpfen, auch machten sie Brotfladen daraus; und sein Geschmack war wie der Geschmack von Ölkuchen*.", footnotes: ["℘ 2Mo 16,23.31"] },
      { number: 9, text: "Und wenn nachts der Tau auf das Lager herabfiel, dann fiel <auch> das Manna darauf herab*.", footnotes: ["℘ 2Mo 16,13.14"] },
      { number: 10, text: "Und als Mose das Volk, alle seine Sippen*, jeden am Eingang seines Zeltes, weinen hörte und der Zorn des HERRN heftig entbrannte*, da war es böse in den Augen des Mose.", footnotes: ["w. entsprechend seinen Sippen", "℘ Kap. 12,9; Hebr 3,10"] },
      { number: 11, text: "Und Mose sagte zu dem HERRN: Warum hast du an deinem Knecht <so> schlecht gehandelt, und warum habe ich nicht in deinen Augen Gunst gefunden, dass du die Last dieses ganzen Volkes auf mich legst*?", footnotes: ["℘ 2Mo 5,22"] },
      { number: 12, text: "Bin ich etwa mit diesem ganzen Volk schwanger gewesen, oder habe etwa ich es geboren, dass du zu mir sagst: »Trage es an deiner Brust, wie der Betreuer den Säugling trägt«*, in das Land, das du ihren* Vätern zugeschworen hast*?", footnotes: ["℘ 5Mo 1,31; 1Thes 2,7", "w. seinen; d. h. des Volkes", "℘ 2Mo 6,8"] },
      { number: 13, text: "Woher soll ich Fleisch haben, um es diesem ganzen Volk zu geben*? Denn sie weinen vor mir* und sagen: »Gib uns Fleisch, damit wir essen!«", footnotes: ["℘ V. 20; 2Kö 4,43; 7,2; Mt 14,17", "w. gegen mich"] },
      { number: 14, text: "Ich allein kann dieses ganze Volk nicht tragen, denn es ist mir zu schwer*.", footnotes: ["℘ 2Mo 18,18"] },
      { number: 15, text: "Und wenn du so mit mir tust, dann bringe mich doch um, wenn ich in deinen Augen Gunst gefunden habe, damit ich mein Unglück nicht <mehr> ansehen <muss>!*", footnotes: ["℘ 2Mo 32,32; 1Kö 19,4"] },
      { number: 16, text: "Und der HERR sprach zu Mose: Versammle mir siebzig Männer aus den Ältesten Israels*, von denen du erkannt hast, dass sie Älteste des Volkes und seine Aufseher* sind, und führe sie zu dem Zelt der Begegnung, dass sie sich dort mit dir <zusammen> aufstellen!", footnotes: ["℘ 2Mo 24,1.9", "w. Schreiber; d. i. eine Beamtenbezeichnung"] },
      { number: 17, text: "Und ich werde herabkommen und dort mit dir reden*, und ich werde von dem Geist nehmen, der auf dir ist, und auf sie legen, damit sie mit dir an der Last des Volkes tragen und du sie nicht <mehr> allein tragen musst*.", footnotes: ["℘ Kap. 7,89", "℘ 2Mo 18,22"] },
      { number: 18, text: "Und zu dem Volk sollst du sagen: Heiligt euch für morgen*! Dann werdet ihr Fleisch essen; denn ihr habt vor den Ohren des HERRN geweint und gesagt: »Wer wird uns Fleisch zu essen geben? Denn in Ägypten ging es uns gut.« Der HERR wird euch Fleisch geben, und ihr werdet essen*.", footnotes: ["℘ 2Mo 19,10", "℘ 2Mo 16,8"] },
      { number: 19, text: "Nicht <nur> einen Tag sollt ihr essen, und nicht <nur> zwei Tage und nicht <nur> fünf Tage und nicht <nur> zehn Tage und nicht <nur> zwanzig Tage," },
      { number: 20, text: "sondern einen ganzen Monat, bis es euch zur Nase herauskommt und es euch zum Ekel wird, weil ihr den HERRN, der in eurer Mitte ist, verworfen und vor ihm geweint und gesagt habt: »Warum nur sind wir aus Ägypten ausgezogen*?«", footnotes: ["℘ Kap. 14,3; 16,13; 20,4; 21,5; 2Mo 16,3; Apg 7,39"] },
      { number: 21, text: "Und Mose sagte: 600 000 <Mann>* Fußvolk <zählt> das Volk, in dessen Mitte ich bin, und da sagst du: »Fleisch will ich ihnen geben, dass sie einen ganzen Monat <davon> essen!«", footnotes: ["℘ Kap. 1,46"] },
      { number: 22, text: "Können <so viele> Schafe und Rinder für sie geschlachtet werden, dass es für sie ausreicht? Oder sollen alle Fische des Meeres für sie eingesammelt werden, dass es für sie ausreicht?*", footnotes: ["℘ V. 13"] },
      { number: 23, text: "Und der HERR sprach zu Mose: Ist die Hand des HERRN <zu> kurz?* Jetzt sollst du sehen, ob mein Wort für dich eintrifft oder nicht*.", footnotes: ["℘ Jes 50,2; Jer 32,17.27", "℘ 2Mo 6,1"] },
      { number: 24, text: "Da ging Mose hinaus und redete zum Volk die Worte des HERRN; und er versammelte siebzig Männer aus den Ältesten des Volkes und stellte sie rings um das Zelt auf." },
      { number: 25, text: "Und der HERR kam in der Wolke herab* und redete zu ihm und nahm von dem Geist, der auf ihm war, und legte ihn auf die siebzig Männer, die Ältesten*. Und es geschah, sobald der Geist auf sie kam*, weissagten* sie*; <später> aber nicht mehr*.", footnotes: ["℘ Kap. 12,5", "℘ Neh 9,20", "℘ Kap. 24,2; 2Kö 2,15", "D. i. hier prophetische Ergriffenheit, o. prophetische Begeisterung.", "℘ 1Sam 19,20", "w. und sie fuhren nicht fort. — Die aram. und lat. Üs. lesen: und sie hörten nicht auf"] },
      { number: 26, text: "Und zwei Männer blieben im Lager zurück, der Name des einen war Eldad und der Name des andern Medad; und auch auf sie kam der Geist — sie waren nämlich unter den Aufgeschriebenen, waren aber nicht zum Zelt hinausgegangen —, und sie weissagten* im Lager.", footnotes: ["D. i. hier prophetische Ergriffenheit, o. prophetische Begeisterung."] },
      { number: 27, text: "Da lief ein junger Mann hin und berichtete es Mose und sagte: Eldad und Medad weissagen* im Lager.", footnotes: ["D. i. hier prophetische Ergriffenheit, o. prophetische Begeisterung."] },
      { number: 28, text: "Und Josua, der Sohn des Nun, der <schon> von seiner Jugend an der Diener des Mose gewesen war*, antwortete: Mein Herr, Mose, halte sie zurück!*", footnotes: ["℘ 2Mo 24,13; Jos 1,1", "℘ Mk 9,38"] },
      { number: 29, text: "Aber Mose sagte zu ihm: Eiferst du für mich? Mögen doch alle im Volk* des HERRN Propheten sein, dass der HERR seinen Geist auf sie lege!*", footnotes: ["w. Möge doch das ganze Volk", "℘ Joe 3,1.2; 1Kor 14,5"] },
      { number: 30, text: "Und Mose zog sich in das Lager zurück, er und die Ältesten Israels." },
      { number: 31, text: "Und ein Wind ging von dem HERRN aus und trieb Wachteln vom Meer herbei und warf sie auf das Lager <herab>, eine Tagereise weit *in der einen Richtung* und eine Tagereise weit *in der andern Richtung*, rings um das Lager* und zwei Ellen <hoch lagen sie> auf dem Erdboden.", footnotes: ["w. hier", "w. hier", "w. hier", "w. hier", "℘ 2Mo 16,13"] },
      { number: 32, text: "Und das Volk machte sich auf diesen ganzen Tag und die ganze Nacht und den ganzen folgenden Tag, und sie sammelten die Wachteln ein; wer wenig sammelte, hatte zehn Homer gesammelt; und sie breiteten sie sich <zum Dörren> aus* rings um das Lager her.", footnotes: ["mit korrigiertem Text: und sie schlachteten sie für sich"] },
      { number: 33, text: "Das Fleisch war noch zwischen ihren Zähnen, es war noch nicht zerkaut, da entbrannte der Zorn des HERRN gegen das Volk, und der HERR schlug das Volk mit einer sehr großen Plage*.", footnotes: ["w. schlug das Volk einen sehr großen Schlag\n℘ Kap. 17,11; Ps 78,26-31"] },
      { number: 34, text: "Und man gab diesem Ort den Namen Kibrot-Hattaawa*, weil man dort das Volk begrub, das gierig gewesen war.", footnotes: ["d. h. Gräber der Gier, o. des Begehrens (V. 4)\n℘ Kap. 33,16; 5Mo 9,22"] },
      { number: 35, text: "Von Kibrot-Hattaawa brach das Volk auf nach Hazerot; und sie waren in Hazerot*.", footnotes: ["℘ Kap. 33,17"] },
    ]},
    { number: 12, verses: [
      { number: 1, text: "Und Mirjam und Aaron* redeten* gegen Mose* wegen der kuschitischen Frau, die er genommen hatte; denn er hatte eine kuschitische Frau genommen*.", heading: "Auflehnung Aarons und Mirjams gegen Mose", footnotes: ["℘ Kap. 26,59", "w. Und Mirjam redete und Aaron", "℘ Kap. 16,2", "℘ 2Mo 2,21"] },
      { number: 2, text: "Und sie sagten: Hat der HERR nur etwa mit* Mose geredet? Hat er nicht auch mit* uns geredet?* Und der HERR hörte es*.", footnotes: ["o. durch", "o. durch", "℘ 2Mo 4,14-16; 15,20", "℘ Kap. 11,1; Hes 35,13"] },
      { number: 3, text: "Der Mann Mose aber war sehr demütig*, mehr als alle Menschen, die auf dem Erdboden waren.", footnotes: ["o. gebeugt\n℘ 2Kor 10,1"] },
      { number: 4, text: "Da sprach der HERR plötzlich zu Mose und zu Aaron und zu Mirjam: Geht hinaus, ihr drei, zum Zelt der Begegnung*! Und sie gingen hinaus, die drei.", footnotes: ["℘ Kap. 1,1"] },
      { number: 5, text: "Und der HERR kam in einer Wolkensäule herab* und stand im Eingang des Zeltes; und er rief Aaron und Mirjam, und die beiden traten hinaus.", footnotes: ["℘ Kap. 11,25"] },
      { number: 6, text: "Und er sprach: Hört doch meine Worte! Wenn ein Prophet des HERRN unter euch ist, dem will ich mich in einer Erscheinung zu erkennen geben*, im Traum will ich mit ihm reden*.", footnotes: ["℘ 1Sam 3,21; 2Sam 7,4; Dan 2,19; 7,1; Hos 12,11; Sach 1,8", "℘ 1Mo 28,12-16; 1Sam 28,6; 1Kö 3,5; Hi 4,13; Joe 3,1"] },
      { number: 7, text: "So steht <es> nicht <mit> meinem Knecht Mose. Er ist treu in meinem ganzen Haus*;", footnotes: ["℘ Hebr 3,2.5"] },
      { number: 8, text: "mit ihm rede ich von Mund zu Mund*, <im> Sehen und nicht in Rätselworten, und die Gestalt des HERRN schaut er*. Warum habt ihr euch nicht gefürchtet, gegen meinen Knecht, gegen Mose, zu reden?", footnotes: ["℘ Kap. 7,89; 2Mo 19,19; 33,1; 5Mo 34,10", "℘ 2Mo 34,6; 5Mo 18,15.18"] },
      { number: 9, text: "Und der Zorn des HERRN entbrannte gegen sie*, und er ging weg.", footnotes: ["℘ Kap. 11,10"] },
      { number: 10, text: "Und die Wolke wich vom Zelt, und siehe, Mirjam war aussätzig wie Schnee*; und Aaron wandte sich zu Mirjam um, und siehe, sie war aussätzig*.", footnotes: ["℘ 2Mo 4,6; 3Mo 13,13", "℘ 5Mo 24,9; 2Chr 26,19"] },
      { number: 11, text: "Da sagte Aaron zu Mose: Ach, mein Herr, lege doch nicht die Sünde auf uns, durch die wir töricht gehandelt und uns versündigt haben!*", footnotes: ["℘ 2Sam 24,10"] },
      { number: 12, text: "Lass <Mirjam> doch nicht sein wie ein Totgeborenes, dessen Fleisch, wenn es aus seiner Mutter Leib hervorkommt, zur Hälfte verwest ist!" },
      { number: 13, text: "Und Mose schrie zu dem HERRN und sagte: Gott, ach, heile sie doch!*", footnotes: ["℘ 2Mo 15,26; 1Kö 13,6; Lk 6,28"] },
      { number: 14, text: "Und der HERR sprach zu Mose: Hätte ihr Vater ihr ins Gesicht gespuckt*, müsste sie sich nicht sieben Tage lang schämen*? Sie soll sieben Tage außerhalb des Lagers eingeschlossen werden*, danach soll sie wieder aufgenommen werden.", footnotes: ["℘ 5Mo 25,9", "o. sollte sie nicht . . . beschimpft sein", "℘ Kap. 5,2; 3Mo 13,4.50"] },
      { number: 15, text: "So wurde Mirjam sieben Tage außerhalb des Lagers eingeschlossen; und das Volk brach nicht auf, bis Mirjam wieder aufgenommen worden war." },
      { number: 16, text: "Danach aber brach das Volk von Hazerot auf*; und sie lagerten in der Wüste Paran*.", footnotes: ["℘ Kap. 33,18", "℘ Kap. 10,12"] },
    ]},
    { number: 13, verses: [
      { number: 1, text: "*Und der HERR redete zu Mose und sprach:", heading: "Sendung der Kundschafter und ihr Bericht", footnotes: ["℘ Kap. 13; 14: 5Mo 1,19-46"] },
      { number: 2, text: "Sende dir Männer aus, dass sie das Land Kanaan auskundschaften*, das ich den Söhnen Israel gebe! Je einen Mann für den Stamm* seiner Väter sollt ihr aussenden, jeder ein Fürst unter ihnen.", footnotes: ["℘ V. 16.17; Jos 2,1", "℘ Jos 3,12"] },
      { number: 3, text: "Und Mose sandte sie aus der Wüste Paran* nach dem Befehl des HERRN, alle Männer, die Häupter der Söhne Israel waren*.", footnotes: ["℘ V. 26; Kap. 10,12", "℘ Kap. 34,17.18"] },
      { number: 4, text: "*Und das sind ihre Namen: für den Stamm Ruben: Schammua, der Sohn Sakkurs;", footnotes: ["℘ V. 4-15: Kap. 34,19-28; 1Mo 35,23-26"] },
      { number: 5, text: "für den Stamm Simeon: Schafat, der Sohn Horis;" },
      { number: 6, text: "für den Stamm Juda: Kaleb, der Sohn Jefunnes*;", footnotes: ["℘ Kap. 14,6.24; 34,19; Jos 14,6; 1Chr 4,15"] },
      { number: 7, text: "für den Stamm Issaschar: Jigal, der Sohn Josefs;" },
      { number: 8, text: "für den Stamm Ephraim: Hoschea, der Sohn Nuns*;", footnotes: ["℘ Kap. 27,18.22; 2Mo 17,9; 5Mo 32,44; 1Chr 7,27"] },
      { number: 9, text: "für den Stamm Benjamin: Palti, der Sohn Rafus;" },
      { number: 10, text: "für den Stamm Sebulon: Gaddiël, der Sohn Sodis;" },
      { number: 11, text: "für den Stamm Josef, <und zwar> für den Stamm Manasse: Gaddi, der Sohn Susis;" },
      { number: 12, text: "für den Stamm Dan: Ammiël, der Sohn Gemallis;" },
      { number: 13, text: "für den Stamm Asser: Setur, der Sohn Michaels;" },
      { number: 14, text: "für den Stamm Naftali: Nachbi, der Sohn Wofsis;" },
      { number: 15, text: "für den Stamm Gad: Gëuël, der Sohn Machis." },
      { number: 16, text: "Das sind die Namen der Männer, die Mose aussandte, um das Land auszukundschaften. Und Mose nannte Hoschea*, den Sohn des Nun, Josua*.", footnotes: ["d. h. Rettung", "d. h. der HERR ist Rettung\n℘ Kap. 27,18.22; 2Mo 17,9; 5Mo 32,44; 1Chr 7,27"] },
      { number: 17, text: "Und Mose sandte sie, das Land Kanaan auszukundschaften, und sagte zu ihnen: Zieht hier hinauf an der Südseite, und steigt auf das Gebirge*,", footnotes: ["℘ Jos 10,40"] },
      { number: 18, text: "und seht das Land an, wie es <beschaffen> ist; und das Volk, das darin wohnt, ob es stark oder schwach, ob es gering oder zahlreich ist;" },
      { number: 19, text: "und wie das Land ist, in dem es wohnt, ob es gut oder schlecht ist; und wie die Städte sind, in denen es wohnt, ob <es> in Lagern oder in Festungen <wohnt>;" },
      { number: 20, text: "und wie das Land ist, ob es fett oder mager ist, ob Bäume darin sind oder nicht*. Und seid mutig* und nehmt <etwas> von der Frucht des Landes! Die Tage aber waren die Tage der ersten Trauben.", footnotes: ["℘ Jos 2,1", "℘ 5Mo 31,6"] },
      { number: 21, text: "Und sie zogen hinauf und kundschafteten das Land aus, von der Wüste Zin* bis Rehob, <von wo> man nach Hamat geht*.", footnotes: ["℘ Kap. 34,3.4", "℘ Kap. 34,8; Ri 18,28"] },
      { number: 22, text: "Und sie zogen an der Südseite hinauf und kamen bis Hebron*, und dort waren Ahiman, Scheschai und Talmai, die Söhne Enaks*. Hebron aber war sieben Jahre vor Zoan* in Ägypten erbaut worden.", footnotes: ["℘ 1Mo 13,18", "℘ Jos 11,21; 15,14", "℘ Ps 78,12.43; Jes 19,11"] },
      { number: 23, text: "Und sie kamen bis in das Tal* Eschkol* und schnitten dort eine Weinranke mit <nur> einer Traube ab und trugen sie zu zweit an einer Stange, auch Granatäpfel und Feigen*.", footnotes: ["Das hebr. Wort bezeichnet allgemein alle Wildbäche und Flüsse Palästinas, und zwar sowohl den Fluss selbst als auch die Schlucht oder das Tal, in dem er fließt.", "d. h. Traube\n℘ Kap. 32,9", "℘ 5Mo 8,8"] },
      { number: 24, text: "Diesen Ort nannte man Tal Eschkol* wegen der Traube, die die Söhne Israel dort abgeschnitten hatten.", footnotes: ["d. h. Traube"] },
      { number: 25, text: "Und sie kehrten am Ende von vierzig Tagen von der Erkundung des Landes zurück*.", footnotes: ["℘ Kap. 14,34"] },
      { number: 26, text: "Und sie gingen hin und kamen zu Mose und zu Aaron und zu der ganzen Gemeinde der Söhne Israel in die Wüste Paran* nach Kadesch*; und sie erstatteten ihnen und der ganzen Gemeinde Bericht und zeigten ihnen die Frucht des Landes.", footnotes: ["℘ V. 3", "℘ Kap. 20,1; 32,8; 33,36; Jos 14,7"] },
      { number: 27, text: "Und sie erzählten ihm und sagten: Wir sind in das Land gekommen, wohin du uns gesandt hast; und wirklich, es fließt von Milch und Honig über*, und das ist seine Frucht*.", footnotes: ["℘ Kap. 14,8; 16,13.14; 2Mo 3,8.17", "℘ Kap. 14,7"] },
      { number: 28, text: "Allerdings ist das Volk stark, das in dem Land wohnt, und die Städte <sind> befestigt <und> sehr groß*; und auch die Söhne Enaks haben wir dort gesehen.", footnotes: ["℘ Jos 14,12"] },
      { number: 29, text: "Amalek wohnt im Lande des Südens*, und die Hetiter und die Jebusiter und die Amoriter wohnen auf dem Gebirge, und die Kanaaniter* wohnen am Meer und am Ufer des Jordan*.", footnotes: ["℘ Kap. 14,45; 2Mo 17,8; 1Sam 27,8", "℘ 1Mo 15,20.21; 5Mo 7,1; 20,17; Jos 3,10; Ri 3,5; Neh 9,8", "℘ Jos 5,1; 9,1"] },
      { number: 30, text: "Und Kaleb beschwichtigte das Volk, <das> gegenüber Mose <murrte>, und sagte: Lasst uns nur hinaufziehen und es in Besitz nehmen, denn wir werden es gewiss bezwingen*!", footnotes: ["℘ Kap. 14,7.9"] },
      { number: 31, text: "Aber die Männer, die mit ihm hinaufgezogen waren, sagten: Wir können nicht gegen das Volk hinaufziehen, denn es ist stärker als wir*.", footnotes: ["℘ Kap. 32,7-9"] },
      { number: 32, text: "Und sie brachten unter den Söhnen Israel ein böses Gerücht über das Land auf, das sie ausgekundschaftet hatten*, und sagten: Das Land, das wir durchzogen haben, um es zu erkunden, ist ein Land, das seine Bewohner frisst*; und alles Volk, das wir darin gesehen haben, sind Leute von hohem Wuchs*;", footnotes: ["℘ Ps 106,24", "℘ Hes 36,13", "℘ Am 2,9"] },
      { number: 33, text: "auch haben wir dort die Riesen* gesehen, die Söhne Enaks von den Riesen*; und wir waren in unseren Augen wie Heuschrecken, und so waren wir auch in ihren Augen*.", footnotes: ["hebr. Nefilim", "℘ 1Mo 6,4", "℘ 1Sam 17,24"] },
    ]},
    { number: 14, verses: [
      { number: 1, text: "*Da erhob die ganze Gemeinde ihre Stimme und schrie, und das Volk weinte* in jener Nacht.", heading: "Der Protest der Gemeinde und Gottes Gerichtsankündigung", footnotes: ["℘ Kap. 13; 14: 5Mo 1,19-46", "℘ Kap. 11,4; Jos 14,8"] },
      { number: 2, text: "Und alle Söhne Israel murrten gegen Mose und gegen Aaron*, und die ganze Gemeinde sagte zu ihnen: Wären wir doch im Land Ägypten gestorben, oder wären wir doch in dieser Wüste gestorben*!", footnotes: ["℘ Kap. 17,6; 20,2; 5Mo 9,23; Ps 106,24.25", "℘ V. 28; 2Mo 14,11"] },
      { number: 3, text: "Wozu bringt uns der HERR in dieses Land? Damit wir durchs Schwert fallen und unsere Frauen und unsere kleinen Kinder zur Beute werden? Wäre es nicht besser für uns, nach Ägypten zurückzukehren*?", footnotes: ["℘ Kap. 11,20; Neh 9,17; Jer 42,14.19; Apg 7,39"] },
      { number: 4, text: "Und sie sagten einer zum andern: Lasst uns ein Haupt <über uns> setzen und nach Ägypten zurückkehren!*", footnotes: ["℘ Kap. 11,20; Neh 9,17; Jer 42,14.19; Apg 7,39"] },
      { number: 5, text: "Da fielen Mose und Aaron auf ihr Angesicht vor der ganzen Versammlung der Gemeinde der Söhne Israel*.", footnotes: ["℘ Kap. 16,4.22; 17,10"] },
      { number: 6, text: "Und Josua, der Sohn des Nun, und Kaleb, der Sohn des Jefunne*, von denen, die das Land ausgekundschaftet hatten, zerrissen ihre Kleider*", footnotes: ["℘ Kap. 13,6.8.30", "℘ Ri 11,35"] },
      { number: 7, text: "und sagten zu der ganzen Gemeinde der Söhne Israel: Das Land, das wir durchzogen haben, um es auszukundschaften, das Land ist sehr, sehr gut*.", footnotes: ["℘ Kap. 13,27; Ri 18,9"] },
      { number: 8, text: "Wenn der HERR Gefallen an uns hat*, so wird er uns in dieses Land bringen und es uns geben, ein Land, das von Milch und Honig überfließt*.", footnotes: ["℘ Ps 147,11", "℘ Kap. 13,27; 2Kö 18,32"] },
      { number: 9, text: "Nur empört euch nicht gegen den HERRN*! Und fürchtet doch nicht das Volk des Landes, denn unser Brot werden sie sein! Ihr Schutz* ist von ihnen gewichen, und der HERR ist mit uns*. Fürchtet sie nicht*!", footnotes: ["℘ Kap. 17,6; 20,2; 5Mo 9,23; Ps 106,24.25", "w. Schatten", "℘ Jos 14,12; 2Chr 20,17; Ps 46,8.12; Jes 8,10; Röm 8,31", "℘ Kap. 13,30; 2Mo 14,13; 5Mo 1,21.29; 20,3"] },
      { number: 10, text: "Und die ganze Gemeinde sagte, dass man sie steinigen solle*. Da erschien die Herrlichkeit des HERRN an dem Zelt der Begegnung allen Söhnen Israel*.", footnotes: ["℘ 2Mo 17,4", "℘ Kap. 16,19; 17,7; 2Mo 16,10"] },
      { number: 11, text: "Und der HERR sprach zu Mose: Wie lange will mich dieses Volk verachten, und wie lange wollen sie mir nicht glauben* bei all den Zeichen, die ich in ihrer Mitte getan habe*?", footnotes: ["o. mir misstrauen", "℘ V. 27; 2Mo 16,28; 23,21; Ps 78,32; Mt 17,17; Joh 12,37"] },
      { number: 12, text: "Ich will es mit der Pest schlagen und es austilgen*; und ich will dich zu einer Nation machen, größer und stärker als sie*.", footnotes: ["o. enterben\n℘ Hes 20,13", "℘ 2Mo 32,10"] },
      { number: 13, text: "Und Mose sagte zu dem HERRN: Dann werden es die Ägypter hören*. Denn durch deine Macht hast du dieses Volk aus ihrer Mitte heraufgeführt*;", footnotes: ["℘ Jos 7,9", "℘ 2Mo 32,11; 5Mo 9,26.28; Hes 20,9"] },
      { number: 14, text: "und man wird es den Bewohnern dieses Landes sagen. Sie haben gehört, dass du, HERR, in der Mitte dieses Volkes bist, dass du, HERR, Auge in Auge dich sehen lässt* und dass deine Wolke über ihnen steht und du in einer Wolkensäule vor ihnen hergehst bei Tag und in einer Feuersäule bei Nacht*.", footnotes: ["℘ 5Mo 5,4.24", "℘ 2Mo 13,21; 33,16"] },
      { number: 15, text: "Und wenn du dieses Volk wie einen Mann tötest, werden die Nationen, die die Kunde von dir gehört haben, sagen:" },
      { number: 16, text: "Weil der HERR dieses Volk nicht in das Land bringen konnte, das er ihnen zugeschworen hatte, darum hat er sie in der Wüste hingeschlachtet*.", footnotes: ["℘ 2Mo 32,12; 5Mo 9,28"] },
      { number: 17, text: "Und nun möge sich doch die Macht des Herrn groß erweisen, so wie du geredet hast, als du sprachst:" },
      { number: 18, text: "»Der HERR ist langsam zum Zorn und groß an Gnade*, der Schuld und <Treue>bruch vergibt, aber keineswegs ungestraft lässt*, der die Schuld der Väter heimsucht an den Kindern, an der dritten und vierten <Generation>*.«", footnotes: ["℘ Ps 86,15", "o. nicht völlig ungestraft lässt", "℘ 2Mo 20,5; Hi 21,19; Jer 32,18; Kla 5,7"] },
      { number: 19, text: "Vergib doch die Schuld dieses Volkes nach der Größe deiner Gnade und so, wie du diesem Volk vergeben hast von Ägypten an bis hierher!*", footnotes: ["℘ 2Mo 32,32; Dan 9,19; Am 7,2.5"] },
      { number: 20, text: "Und der HERR sprach: Ich habe vergeben nach deinem Wort*.", footnotes: ["℘ 2Mo 32,14"] },
      { number: 21, text: "Jedoch, so wahr ich lebe* und von der Herrlichkeit des HERRN die ganze Erde erfüllt werden wird*:", footnotes: ["℘ 5Mo 32,40", "℘ 2Mo 9,16; Ps 57,6.12; 72,19"] },
      { number: 22, text: "Alle die Männer, die meine Herrlichkeit und meine Zeichen gesehen haben, die ich in Ägypten und in der Wüste getan habe, und mich nun zehnmal* geprüft und nicht gehört haben auf meine Stimme,", footnotes: ["℘ 1Mo 31,7"] },
      { number: 23, text: "werden das Land nicht sehen*, das ich ihren Vätern zugeschworen habe! Alle, die mich verachtet haben, sollen es nicht sehen*.", footnotes: ["w. wenn sie das Land sehen werden<, dann . . .!> — Der Satz ist eine hebr. Schwurformel, deren zweiter Teil nicht ausgesprochen wurde.", "℘ Kap. 32,11; Jer 18,10; Hebr 3,11.18"] },
      { number: 24, text: "Aber meinen Knecht Kaleb — weil ein anderer Geist in ihm war und er mir völlig nachgefolgt ist —, ihn werde ich in das Land bringen, in das er hineingegangen ist; und seine Nachkommen sollen es besitzen*.", footnotes: ["℘ Kap. 32,12; Jos 14,6.9"] },
      { number: 25, text: "Die Amalekiter aber und die Kanaaniter wohnen in der Ebene. Morgen wendet euch und brecht auf zur Wüste in der Richtung zum Schilfmeer*!*", footnotes: ["w. den Weg des Schilfmeers", "℘ Ri 11,16"] },
      { number: 26, text: "Und der HERR redete zu Mose und Aaron und sprach:" },
      { number: 27, text: "Wie lange <soll es> mit dieser bösen Gemeinde <weitergehen>, dass sie gegen mich murrt?* Das Murren der Söhne Israel, womit sie gegen mich murren, habe ich gehört*.", footnotes: ["℘ V. 11", "℘ 2Mo 16,9"] },
      { number: 28, text: "Sage zu ihnen: So wahr ich lebe*, spricht der HERR*, wenn ich es nicht so mit euch machen werde, wie ihr vor meinen Ohren geredet habt*!", footnotes: ["℘ 5Mo 32,40", "w. ist der Ausspruch des HERRN", "Der Satz ist eine hebr. Schwurformel, deren zweiter Teil nicht ausgesprochen wurde.\n℘ V. 2"] },
      { number: 29, text: "In dieser Wüste sollen eure Leichen fallen*, ja, alle eure Gemusterten nach eurer ganzen Zahl, von zwanzig Jahren an und darüber*, die ihr gegen mich gemurrt habt.", footnotes: ["℘ Kap. 26,65; Ps 106,26; 1Kor 10,5", "℘ Kap. 1,45.46; 26,64.65"] },
      { number: 30, text: "Niemals sollt ihr in das Land kommen*, in dem euch wohnen zu lassen ich meine Hand <zum Schwur> erhoben habe*, außer Kaleb, dem Sohn des Jefunne, und Josua, dem Sohn des Nun!", footnotes: ["w. Wenn ihr in das Land kommen werdet<, dann . . .!>; s. vorige Anm.", "℘ Ps 95,11"] },
      { number: 31, text: "Und eure kleinen Kinder, von denen ihr gesagt habt, sie werden zur Beute werden, sie will ich hineinbringen, und sie sollen das Land kennenlernen, das ihr verworfen habt*.", footnotes: ["℘ Neh 9,24; Ps 106,24"] },
      { number: 32, text: "Ihr aber, eure Leichen sollen in dieser Wüste fallen*!", footnotes: ["℘ Kap. 26,65; Ps 106,26; 1Kor 10,5"] },
      { number: 33, text: "Und eure Kinder sollen vierzig Jahre* lang in der Wüste Hirten sein* und eure Hurereien tragen*, bis eure Leiber in der Wüste umkommen*.", footnotes: ["℘ Kap. 32,13; Hebr 3,9.17", "w. weiden", "℘ Hes 23,35", "w. bis eure Leichen in der Wüste vollständig sind"] },
      { number: 34, text: "Nach der Zahl der Tage, die ihr das Land ausgekundschaftet habt, vierzig Tage*, je einen Tag für ein Jahr*, sollt ihr vierzig Jahre* lang eure Sünden tragen*, und ihr sollt erkennen, was es ist, wenn ich mich abwende*!", footnotes: ["℘ Kap. 13,25", "℘ Hes 4,6", "℘ Hes 23,35", "℘ Hes 23,35", "w. und ihr sollt meine Abwendung erkennen\n℘ Hos 9,12"] },
      { number: 35, text: "Ich, der HERR, habe es geredet*. Wenn ich das nicht tun werde an dieser ganzen bösen Gemeinde, die sich gegen mich zusammengerottet hat*! In dieser Wüste sollen sie umkommen, und dort sollen sie sterben!*", footnotes: ["℘ Kap. 23,19; Hes 20,36", "Der Satz ist eine hebr. Schwurformel, deren zweiter Teil nicht ausgesprochen wurde.", "℘ 2Mo 23,21; Jos 5,6; Ps 78,33; Jud 5"] },
      { number: 36, text: "Und die Männer, die Mose ausgesandt hatte, das Land auszukundschaften, und die zurückkehrten und die ganze Gemeinde gegen ihn zum Murren verleitet hatten, indem sie ein böses Gerede über das Land aufbrachten," },
      { number: 37, text: "diese Männer, die ein böses Gerede über das Land aufgebracht hatten, starben durch eine Plage* vor dem HERRN*.", footnotes: ["w. durch einen Schlag", "℘ Kap. 16,35; 20,3; 3Mo 10,2; 1Kor 10,10"] },
      { number: 38, text: "Aber Josua, der Sohn des Nun, und Kaleb, der Sohn des Jefunne, blieben am Leben von jenen Männern, die ausgezogen waren, um das Land auszukundschaften*.", footnotes: ["℘ Jos 14,10"] },
      { number: 39, text: "Und als Mose diese Worte zu allen Söhnen Israel redete, trauerte das Volk sehr*.", footnotes: ["℘ 2Mo 33,4"] },
      { number: 40, text: "Und sie machten sich am <nächsten> Morgen früh auf, um auf die Höhe des Gebirges hinaufzuziehen, und sagten: Hier sind wir und wollen an den Ort hinaufziehen, von dem der HERR geredet hat; denn wir haben gesündigt." },
      { number: 41, text: "Aber Mose sagte: Warum denn übertretet ihr den Befehl des HERRN <schon wieder>*? Es wird <euch> nicht gelingen*.", footnotes: ["℘ 1Sam 15,19", "℘ 2Chr 24,20"] },
      { number: 42, text: "Zieht nicht hinauf — denn der HERR ist nicht in eurer Mitte —, damit ihr nicht vor euren Feinden geschlagen werdet*!", footnotes: ["℘ Jos 7,12; Ri 16,20; 2Chr 15,2; Ps 44,10"] },
      { number: 43, text: "Denn die Amalekiter und die Kanaaniter stehen euch dort gegenüber*, und ihr werdet durchs Schwert fallen. Weil ihr euch von der Nachfolge des HERRN* abgewandt habt, wird der HERR nicht mit euch sein*.", footnotes: ["w. sind dort vor euch", "w. von hinter dem HERRN her", "℘ Jos 7,12; Ri 16,20; 2Chr 15,2; Ps 44,10"] },
      { number: 44, text: "Doch sie waren so vermessen, auf die Höhe des Gebirges hinaufzuziehen; aber die Lade des Bundes des HERRN und Mose wichen nicht aus der Mitte des Lagers." },
      { number: 45, text: "Da kamen die Amalekiter* und die Kanaaniter, die auf jenem Gebirge wohnten, herab und schlugen und versprengten sie bis nach Horma*.", footnotes: ["℘ Kap. 13,29; 1Sam 27,8", "℘ Kap. 21,3; Ri 1,17; 1Sam 4,2"] },
    ]},
    { number: 15, verses: [
      { number: 1, text: "Und der HERR redete zu Mose und sprach:", heading: "Verordnungen für Opfer im Land Kanaan" },
      { number: 2, text: "Rede zu den Söhnen Israel und sprich zu ihnen: Wenn ihr in das Land eurer Wohnsitze kommt, das ich euch geben werde," },
      { number: 3, text: "und ihr dem HERRN ein Feueropfer opfert, ein Brandopfer* oder ein Schlachtopfer, um ein Gelübde zu erfüllen oder als freiwillige Gabe* oder an euren Festen*, um dem HERRN einen wohlgefälligen Geruch* zu bereiten* von Rindern oder Schafen;", footnotes: ["℘ 3Mo 1,2.3", "℘ 3Mo 7,16; 22,18.21", "w. festgesetzten Zeiten\n℘ 3Mo 23", "o. Geruch der Befriedigung o. Beschwichtigung", "℘ 3Mo 1,9"] },
      { number: 4, text: "dann soll der, der dem HERRN seine Gabe darbringt, als Speisopfer darbringen ein Zehntel Weizengrieß, gemengt* mit einem viertel Hin Öl*;", footnotes: ["o. angefeuchtet", "℘ Kap. 7,13; 3Mo 6,14"] },
      { number: 5, text: "und als Trankopfer sollst du ein viertel Hin Wein opfern* zu dem Brandopfer oder zu dem Schlachtopfer, bei jedem Schaf*.", footnotes: ["℘ Kap. 28,7.14; 3Mo 23,13", "℘ 2Mo 29,40; Esr 7,17"] },
      { number: 6, text: "Oder bei einem Widder sollst du als Speisopfer zwei Zehntel Weizengrieß opfern, gemengt* mit einem drittel Hin Öl;", footnotes: ["o. angefeuchtet"] },
      { number: 7, text: "und als Trankopfer sollst du ein drittel Hin Wein darbringen*: ein wohlgefälliger Geruch* für den HERRN.", footnotes: ["℘ Kap. 6,15; Phil 2,17", "o. Geruch der Befriedigung o. Beschwichtigung"] },
      { number: 8, text: "Und wenn du ein junges Rind als Brandopfer oder als Schlachtopfer opferst, um ein Gelübde zu erfüllen, oder als Heilsopfer* für den HERRN,", footnotes: ["o. Friedensopfer; o. Abschlussopfer; o. Gemeinschaftsopfer"] },
      { number: 9, text: "dann soll man zu dem jungen Rind als Speisopfer drei Zehntel Weizengrieß darbringen, gemengt* mit einem halben Hin Öl;", footnotes: ["o. angefeuchtet"] },
      { number: 10, text: "und als Trankopfer sollst du ein halbes Hin Wein darbringen: ein Feueropfer von wohlgefälligem Geruch* für den HERRN.", footnotes: ["o. Geruch der Befriedigung o. Beschwichtigung"] },
      { number: 11, text: "So soll es gemacht werden bei jedem Rind oder bei jedem Widder oder bei jedem Schaf oder bei jeder Ziege;" },
      { number: 12, text: "nach der Zahl, die ihr opfert, sollt ihr so bei einem jeden machen nach ihrer Zahl." },
      { number: 13, text: "Jeder Einheimische soll das so tun, wenn er ein Feueropfer von wohlgefälligem Geruch* dem HERRN darbringt.", footnotes: ["o. Geruch der Befriedigung o. Beschwichtigung"] },
      { number: 14, text: "Und wenn ein Fremder bei euch wohnt oder wer in eurer Mitte ist bei euren <künftigen> Generationen, und er opfert dem HERRN ein Feueropfer von wohlgefälligem Geruch*, dann soll er es ebenso tun, wie ihr es tut.", footnotes: ["o. Geruch der Befriedigung o. Beschwichtigung"] },
      { number: 15, text: "In der Versammlung soll ein <und dieselbe> Ordnung <gelten> für euch und für den Fremden, der <bei euch> wohnt, eine ewige Ordnung für eure Generationen*; wie ihr, so soll der Fremde sein vor dem HERRN.", footnotes: ["℘ 2Mo 12,14; Est 9,27"] },
      { number: 16, text: "Ein <und dasselbe> Gesetz und ein <und dasselbe> Recht soll für euch <gelten> und für den Fremden, der bei euch wohnt*.", footnotes: ["℘ 2Mo 12,49; Jos 8,33; 1Kö 8,41.42"] },
      { number: 17, text: "Und der HERR redete zu Mose und sprach:" },
      { number: 18, text: "Rede zu den Söhnen Israel und sage zu ihnen: Wenn ihr in das Land kommt, in das ich euch bringen werde," },
      { number: 19, text: "dann soll es geschehen, wenn ihr von dem Brot des Landes esst, dann sollt ihr dem HERRN ein Hebopfer abheben:" },
      { number: 20, text: "als Erstling eures Schrotmehls sollt ihr einen Kuchen als Hebopfer abheben; wie das Hebopfer der Tenne, so sollt ihr dieses abheben*.", footnotes: ["℘ 3Mo 2,12; 23,17; Spr 3,9; Hes 44,30"] },
      { number: 21, text: "Von dem Erstling eures Schrotmehls sollt ihr dem HERRN ein Hebopfer geben in <allen> euren <künftigen> Generationen*.", footnotes: ["℘ 2Mo 23,19; Neh 10,38; Röm 11,16"] },
      { number: 22, text: "Und wenn ihr aus Versehen sündigt* und nicht alle diese Gebote tut, die der HERR zu Mose geredet hat,", footnotes: ["℘ 3Mo 4,2"] },
      { number: 23, text: "alles, was der HERR für euch durch Mose aufgetragen hat von dem Tag an, als der HERR Gebote gab, und weiterhin für eure Generationen," },
      { number: 24, text: "dann soll es geschehen, wenn es vor den Augen der Gemeinde verborgen, aus Versehen geschehen ist, dann soll die ganze Gemeinde einen Jungstier als Brandopfer opfern zum wohlgefälligen Geruch* dem HERRN samt seinem Speisopfer und seinem Trankopfer, nach der Vorschrift, und einen Ziegenbock* als Sündopfer*.", footnotes: ["o. angefeuchtet", "w. Haarigen der Ziegen", "℘ 3Mo 4,13-18; 23,19"] },
      { number: 25, text: "Und der Priester soll Sühnung erwirken für die ganze Gemeinde der Söhne Israel, und es wird ihnen vergeben werden*; denn es war ein Versehen, und sie haben ihre Opfergabe, ein Feueropfer für den HERRN, und ihr Sündopfer vor den HERRN gebracht wegen ihrer Sünde aus Versehen*.", footnotes: ["℘ 3Mo 4,20.26", "w. wegen ihres Versehens"] },
      { number: 26, text: "Und es wird der ganzen Gemeinde der Söhne Israel vergeben werden und dem Fremden, der in ihrer Mitte wohnt; denn dem ganzen Volk <geschah es> aus Versehen*.", footnotes: ["℘ Hebr 5,2"] },
      { number: 27, text: "Und wenn eine einzelne Person* aus Versehen sündigt, dann soll sie eine einjährige Ziege als Sündopfer darbringen*.", footnotes: ["o. Seele", "℘ 3Mo 4,27.28"] },
      { number: 28, text: "Und der Priester soll Sühnung erwirken für die Person*, die sich versehentlich vergangen hat durch eine Sünde aus Versehen vor dem HERRN, um Sühnung für sie zu erwirken; und es wird ihr vergeben werden*.", footnotes: ["o. Seele", "℘ 3Mo 4,20.26"] },
      { number: 29, text: "Für den Einheimischen unter den Söhnen Israel und für den Fremden, der in ihrer Mitte wohnt, sollt ihr ein <und dasselbe> Gesetz haben* für den, der aus Versehen etwas tut.", footnotes: ["℘ 2Mo 12,49; Jos 8,33; 1Kö 8,41.42"] },
      { number: 30, text: "Aber die Person*, die mit erhobener Hand handelt, von den Einheimischen und von den Fremden, die lästert den HERRN; und diese Person* soll ausgerottet werden aus der Mitte ihres Volkes*,", footnotes: ["o. Seele", "o. Seele", "℘ Kap. 9,13; 2Mo 30,33.38; 5Mo 17,12; Hebr 2,2"] },
      { number: 31, text: "denn das Wort des HERRN hat sie verachtet und sein Gebot aufgehoben*; diese Person* soll unbedingt ausgerottet werden*: ihre Schuld ist auf ihr*.", footnotes: ["℘ 2Sam 12,9", "o. Seele", "℘ Kap. 9,13; 2Mo 30,33.38; 5Mo 17,12; Hebr 2,2", "℘ 1Sam 3,14"] },
      { number: 32, text: "Und als die Söhne Israel in der Wüste waren, da fanden sie einen Mann, der am Sabbattag Holz auflas*.", heading: "Steinigung nach Entweihung des Sabbats", footnotes: ["℘ 2Mo 20,8"] },
      { number: 33, text: "Und die ihn gefunden hatten, wie er Holz auflas, brachten ihn zu Mose und zu Aaron und zu der ganzen Gemeinde*.", footnotes: ["℘ 2Mo 18,22"] },
      { number: 34, text: "Und sie legten ihn in Gewahrsam, denn es war nicht genau bestimmt, was mit ihm getan werden sollte*.", footnotes: ["℘ 2Mo 18,14.15"] },
      { number: 35, text: "Da sprach der HERR zu Mose: Der Mann soll unbedingt getötet werden*; die ganze Gemeinde soll ihn außerhalb des Lagers steinigen*.", footnotes: ["℘ 2Mo 31,14", "℘ 3Mo 24,14"] },
      { number: 36, text: "Da führte ihn die ganze Gemeinde vor das Lager hinaus, und sie steinigten ihn, dass er starb*, so wie der HERR dem Mose geboten hatte.", footnotes: ["℘ 1Kö 21,13; Apg 7,58"] },
      { number: 37, text: "Und der HERR sprach zu Mose:", heading: "Erinnerungshilfe für Gottes Gebote" },
      { number: 38, text: "Rede zu den Söhnen Israel und sage zu ihnen, dass sie sich eine Quaste an den Zipfeln ihrer Oberkleider machen sollen* für <alle> ihre <künftigen> Generationen und dass sie an die Quaste des Zipfels eine Schnur aus violettem Purpur setzen sollen.", footnotes: ["℘ 5Mo 22,12; Mt 9,20; 23,5"] },
      { number: 39, text: "Und das soll euch zur <Merk>quaste werden, und ihr sollt sie ansehen und dabei an alle Gebote des HERRN denken und sie tun, und ihr sollt nicht eurem Herzen und euren Augen nachfolgen*, deren Gelüsten* ihr nachhurt*,", footnotes: ["w. nachforschen", "w. denen; d. i. auf Herz und Augen bezogen", "℘ Hi 31,7; Hes 6,9"] },
      { number: 40, text: "damit ihr an alle meine Gebote denkt und sie tut* und heilig seid eurem Gott*.", footnotes: ["℘ Ps 103,18; 2Petr 1,15", "℘ 3Mo 11,44; Röm 12,1"] },
      { number: 41, text: "Ich bin der HERR, euer Gott, der ich euch aus dem Land Ägypten herausgeführt habe, um euer Gott zu sein; ich bin der HERR, euer Gott*.", footnotes: ["℘ 2Mo 6,7; 3Mo 22,33"] },
    ]},
    { number: 16, verses: [
      { number: 1, text: "Und Korach, der Sohn Jizhars, des Sohnes Kehats, des Sohnes Levis*, unternahm es und <mit ihm> Datan und Abiram, die Söhne Eliabs, und On, der Sohn Pelets, die Söhne Rubens,", heading: "Aufruhr und Tod Korachs und seiner Anhänger", footnotes: ["℘ 2Mo 6,16-21"] },
      { number: 2, text: "und sie erhoben sich gegen Mose* mit 250 Männern von den Söhnen Israel, Fürsten der Gemeinde, Berufene der Zusammenkunft, namhafte Männer*.", footnotes: ["℘ Kap. 12,1", "℘ Kap. 1,16; 26,9; 27,3"] },
      { number: 3, text: "Und sie versammelten sich gegen Mose und gegen Aaron und sagten zu ihnen: Genug mit euch*! Denn die ganze Gemeinde, sie alle sind heilig*, und der HERR ist in ihrer Mitte*. Warum erhebt ihr euch über die Versammlung des HERRN?*", footnotes: ["o. <Ihr beansprucht> zu viel für euch", "℘ 2Mo 19,6", "℘ Kap. 23,21; 35,34; 2Mo 29,45", "℘ Ps 106,16; Jud 11"] },
      { number: 4, text: "Als Mose das hörte, fiel er auf sein Angesicht*.", footnotes: ["℘ V. 22; Kap. 14,5; 20,6; Hes 9,8"] },
      { number: 5, text: "Und er redete zu Korach und zu seiner ganzen Rotte und sagte: Morgen wird der HERR erkennen lassen, wer ihm gehört, wer der Heilige ist*, dass er ihn zu sich nahen lasse; und wen er erwählt, den wird er zu sich nahen lassen*.", footnotes: ["℘ 2Mo 28,41; 3Mo 21,6.8; 2Tim 2,19", "℘ Kap. 17,20; Hes 44,15.16"] },
      { number: 6, text: "Tut dies: Nehmt euch Feuerbecken*, Korach und seine ganze Rotte,", footnotes: ["Das sind Gefäße zur Aufbewahrung oder zum Transport brennender Kohlen."] },
      { number: 7, text: "und tut morgen Feuer hinein und legt Räucherwerk darauf vor dem HERRN! Und es soll geschehen, der Mann, den der HERR erwählen wird, der sei der Heilige. Genug mit euch*, ihr Söhne Levis!", footnotes: ["o. <Ihr beansprucht> zu viel für euch"] },
      { number: 8, text: "Und Mose sprach zu Korach: Hört doch, ihr Söhne Levis!" },
      { number: 9, text: "Ist es euch zu wenig, dass der Gott Israels euch aus der Gemeinde Israel ausgesondert hat, um euch zu sich nahen zu lassen, damit ihr den Dienst <an> der Wohnung des HERRN ausübt und vor der Gemeinde steht, um ihr zu dienen*,", footnotes: ["℘ Kap. 1,53; Hes 44,11"] },
      { number: 10, text: "dass er dich und alle deine Brüder, die Söhne Levis, mit dir hat herzunahen lassen*? Und ihr trachtet auch <noch> nach dem Priesteramt!", footnotes: ["℘ Kap. 3,6-9"] },
      { number: 11, text: "Darum seid ihr es, die sich zusammenrotten, du und deine ganze Rotte, gegen den HERRN! Denn Aaron, was ist er, dass ihr gegen ihn murrt?*", footnotes: ["℘ 2Mo 16,7.8; Ps 106,16"] },
      { number: 12, text: "Und Mose sandte hin, um Datan und Abiram, die Söhne Eliabs, zu rufen. Aber sie sagten: Wir kommen nicht hinauf!" },
      { number: 13, text: "Ist es zu wenig, dass du uns aus einem Land, das von Milch und Honig überfließt*, heraufgeführt hast, um uns in der Wüste sterben zu lassen?* Willst du dich auch noch zum Herrscher über uns aufwerfen*?", footnotes: ["℘ Kap. 13,27", "℘ 2Mo 16,3", "℘ 2Mo 2,14"] },
      { number: 14, text: "Du hast uns keineswegs in ein Land gebracht, das von Milch und Honig überfließt*, noch uns Äcker und Weinberge als Erbteil gegeben*! Willst du diesen Leuten <etwa> die Augen ausstechen? Wir kommen nicht hinauf!", footnotes: ["℘ Kap. 13,27", "℘ Kap. 20,5"] },
      { number: 15, text: "Da wurde Mose sehr zornig und sprach zu dem HERRN: Wende dich nicht zu ihrer Opfergabe!* Nicht einen <einzigen> Esel habe ich von ihnen genommen und keinem einzigen unter ihnen ein Leid getan*.", footnotes: ["℘ Spr 21,27", "℘ 1Sam 12,3"] },
      { number: 16, text: "Und Mose sagte zu Korach: Du und deine ganze Rotte, ihr sollt morgen vor dem HERRN erscheinen*, du und sie und Aaron!", footnotes: ["w. sein"] },
      { number: 17, text: "Und nehmt jeder sein Feuerbecken* und legt Räucherwerk darauf, und bringt jeder sein Feuerbecken dar vor dem HERRN, 250 Feuerbecken, du und Aaron, jeder sein Feuerbecken!", footnotes: ["Das sind Gefäße zur Aufbewahrung oder zum Transport brennender Kohlen."] },
      { number: 18, text: "Und sie nahmen jeder sein Feuerbecken und taten Feuer darauf und legten Räucherwerk darauf; und sie traten hin an den Eingang des Zeltes der Begegnung, auch Mose und Aaron." },
      { number: 19, text: "Und Korach versammelte gegen sie die ganze Gemeinde* an den Eingang des Zeltes der Begegnung. Da erschien die Herrlichkeit des HERRN vor der ganzen Gemeinde.", footnotes: ["℘ Kap. 14,10"] },
      { number: 20, text: "Und der HERR redete zu Mose und zu Aaron und sprach:" },
      { number: 21, text: "Sondert euch ab aus der Mitte dieser Gemeinde*, ich will sie in einem Augenblick vernichten*!", footnotes: ["℘ 2Kor 6,17", "℘ Kap. 17,10; 2Mo 32,10; Offb 18,4"] },
      { number: 22, text: "Und sie fielen auf ihr Angesicht* und sagten: Gott, du Gott des Lebensgeistes* allen Fleisches*! Ein einziger Mann sündigt, und du willst der ganzen Gemeinde zürnen?*", footnotes: ["℘ V. 4", "Im Hebr. steht die Mehrzahl.", "℘ Kap. 27,16; Hi 12,10; Jer 32,27; Hebr 12,9", "℘ 1Mo 18,25; 3Mo 10,6; Jos 22,18; 2Sam 24,17; Ps 99,6"] },
      { number: 23, text: "Und der HERR redete zu Mose und sprach:" },
      { number: 24, text: "Rede zur Gemeinde und sprich: Entfernt euch ringsum von der Wohnung Korachs, Datans und Abirams!" },
      { number: 25, text: "Da stand Mose auf und ging zu Datan und Abiram, und ihm nach gingen die Ältesten Israels." },
      { number: 26, text: "Und er redete zu der Gemeinde und sprach: Weicht doch von den Zelten dieser gottlosen Männer, und rührt nichts an, was ihnen gehört, damit ihr nicht weggerafft werdet in allen ihren Sünden!*", footnotes: ["℘ 1Mo 19,12.13; Jes 52,11; Jer 51,6; 2Tim 2,19"] },
      { number: 27, text: "Und sie entfernten sich ringsum von der Wohnung Korachs, Datans und Abirams. Und Datan und Abiram traten heraus und standen am Eingang ihrer Zelte mit ihren Frauen und ihren Söhnen und ihren kleinen Kindern." },
      { number: 28, text: "Und Mose sagte: Daran sollt ihr erkennen, dass der HERR mich gesandt hat, um alle diese Taten zu tun*, dass ich <also> nicht aus meinem Herzen gehandelt habe:", footnotes: ["℘ Joh 5,36"] },
      { number: 29, text: "Wenn diese sterben, wie alle Menschen sterben, und mit der Heimsuchung aller Menschen heimgesucht werden, dann hat der HERR mich nicht gesandt*;", footnotes: ["℘ 1Kö 18,36"] },
      { number: 30, text: "wenn aber der HERR ein Neues schafft* und der Erdboden seinen Mund öffnet und sie verschlingt mit allem, was ihnen angehört, und sie lebendig in den Scheol hinabfahren, dann werdet ihr erkennen, dass diese Männer den HERRN verachtet haben. —", footnotes: ["w. ein <neues> Schaffen schafft"] },
      { number: 31, text: "Und es geschah, als er alle diese Worte ausgeredet hatte, da spaltete sich der Erdboden, der unter ihnen war," },
      { number: 32, text: "und die Erde öffnete ihren Mund und verschlang sie und ihre Familien* und alle Menschen, die Korach angehörten, und <ihren> ganzen Besitz*.", footnotes: ["w. Häuser", "℘ Kap. 26,10.11; 5Mo 11,6; Ps 106,17"] },
      { number: 33, text: "Und sie fuhren, sie und alles, was ihnen gehörte, lebendig in den Scheol hinab*; und die Erde bedeckte sie, und sie wurden mitten aus der Versammlung weggerafft.", footnotes: ["℘ Ps 55,16"] },
      { number: 34, text: "Und ganz Israel, das um sie herum war, floh bei ihrem Geschrei; denn sie sagten: Dass uns die Erde nicht verschlinge!" },
      { number: 35, text: "Und Feuer ging aus von dem HERRN und fraß die 250 Männer, die das Räucherwerk dargebracht hatten*.", footnotes: ["℘ Kap. 3,4; 11,1; 14,37; 3Mo 10,2; Ps 106,18; Jud 11"] },
    ]},
    { number: 17, verses: [
      { number: 1, text: "Und der HERR redete zu Mose und sprach:" },
      { number: 2, text: "Sage zu Eleasar, dem Sohn Aarons, dem Priester*, dass er die Feuerbecken* aus der Brandstätte heraushebe — und streue das Feuer hinweg —, denn sie sind heilig*!", footnotes: ["o. des Priesters", "s. Anm. zu Kap. 16,6", "℘ Kap. 7,1; 2Mo 30,26-29"] },
      { number: 3, text: "Die Feuerbecken* dieser <Männer>, die durch ihre Sünden ihr Leben verloren* haben*, man mache daraus breit gehämmerte Bleche zum Überzug für den Altar! Denn sie haben sie vor dem HERRN dargebracht, und so sind sie heilig; und sie sollen den Söhnen Israel zum Zeichen sein*.", footnotes: ["s. Anm. zu Kap. 16,6", "w. Die Feuerbecken dieser Sünder gegen ihre Seelen", "℘ Jer 42,20", "℘ Kap. 26,10"] },
      { number: 4, text: "Und der Priester Eleasar nahm die bronzenen Feuerbecken*, die die Verbrannten herbeigebracht hatten, und man hämmerte sie breit zum Überzug für den Altar", footnotes: ["s. Anm. zu Kap. 16,6"] },
      { number: 5, text: "— als eine Erinnerung für die Söhne Israel*, damit kein Fremder, der nicht von den Nachkommen Aarons ist, herzunaht*, um Räucherwerk vor dem HERRN in Rauch aufgehen zu lassen, und es ihm nicht ergeht wie Korach und seiner Rotte* —, wie der HERR durch Mose zu ihm geredet hatte.", footnotes: ["℘ Jos 4,7", "℘ Esr 2,62", "℘ Kap. 1,51; 2Chr 26,16-18"] },
      { number: 6, text: "Und die ganze Gemeinde der Söhne Israel murrte am andern Morgen gegen Mose und gegen Aaron* und sagte: Ihr habt das Volk des HERRN getötet!", footnotes: ["℘ Kap. 14,2; 1Kor 10,10"] },
      { number: 7, text: "Und es geschah, als die Gemeinde sich gegen Mose und gegen Aaron versammelte, da wandten sie sich zum Zelt der Begegnung, und siehe, die Wolke bedeckte es*, und die Herrlichkeit des HERRN erschien*.", footnotes: ["℘ Kap. 9,15", "℘ Kap. 14,10"] },
      { number: 8, text: "Da kamen Mose und Aaron vor das Zelt der Begegnung." },
      { number: 9, text: "Und der HERR redete zu Mose und sprach:" },
      { number: 10, text: "Entfernt euch aus der Mitte dieser Gemeinde, und ich will sie vernichten in einem Augenblick*! Da fielen sie auf ihr Angesicht*.", footnotes: ["℘ Kap. 16,21", "℘ Kap. 14,5"] },
      { number: 11, text: "Und Mose sagte zu Aaron: Nimm das Feuerbecken* und tu Feuer vom Altar darauf und lege Räucherwerk auf, und bringe es schnell zur Gemeinde und erwirke Sühnung für sie!* Denn der Zorn ist von dem HERRN ausgegangen, die Plage hat begonnen*.", footnotes: ["s. Anm. zu Kap. 16,6", "℘ 3Mo 16,15.16", "℘ Kap. 11,33; 2Chr 19,10"] },
      { number: 12, text: "Und Aaron nahm <das Feuerbecken>, wie Mose gesagt hatte, und lief mitten in die Versammlung hinein, und siehe, die Plage hatte unter dem Volk begonnen; und er legte das Räucherwerk auf und erwirkte Sühnung für das Volk*.", footnotes: ["℘ Kap. 25,13"] },
      { number: 13, text: "Und er stand zwischen den Toten und den Lebenden. Da wurde der Plage gewehrt*.", footnotes: ["℘ Kap. 25,8; 2Sam 24,25"] },
      { number: 14, text: "Und <die Zahl> derer, die an der Plage starben, betrug 14 700, außer denen, die Korachs wegen gestorben waren." },
      { number: 15, text: "Und Aaron kam wieder zu Mose an den Eingang des Zeltes der Begegnung, als der Plage gewehrt war." },
      { number: 16, text: "Und der HERR redete zu Mose und sprach:", heading: "Der Stab Aarons" },
      { number: 17, text: "Rede zu den Söhnen Israel und nimm von ihnen je einen Stab für ein Vaterhaus von allen ihren Fürsten, nach ihren Vaterhäusern, <zusammen> zwölf Stäbe! Du sollst den Namen eines jeden auf seinen Stab schreiben*.", footnotes: ["℘ Hes 37,16"] },
      { number: 18, text: "Und den Namen Aaron sollst du auf den Stab Levis schreiben; denn <nur je> ein Stab ist für jedes Haupt ihrer Vaterhäuser da." },
      { number: 19, text: "Und du sollst sie in das Zelt der Begegnung vor das Zeugnis niederlegen, wo ich euch begegne*.", footnotes: ["℘ 2Mo 25,21.22"] },
      { number: 20, text: "Und es wird geschehen: Der Mann, den ich erwählen werde, dessen Stab wird sprossen; und so werde ich vor mir das Murren der Söhne Israel zum Schweigen bringen, mit dem sie gegen euch murren*.", footnotes: ["℘ Kap. 16,5.10"] },
      { number: 21, text: "Und Mose redete zu den Söhnen Israel, und alle ihre Fürsten gaben ihm je einen Stab für einen Fürsten, nach ihren Vaterhäusern, zwölf Stäbe; und der Stab Aarons war unter ihren Stäben." },
      { number: 22, text: "Und Mose legte die Stäbe vor dem HERRN nieder in das Zelt des Zeugnisses." },
      { number: 23, text: "Und es geschah am anderen Morgen, als Mose in das Zelt des Zeugnisses hineinging, siehe, da hatte der Stab Aarons vom Haus Levi gesprosst; er hatte Knospen hervorgebracht und Blüten getrieben und Mandeln reifen lassen." },
      { number: 24, text: "Und Mose brachte alle Stäbe von <der Stelle> vor dem HERRN zu allen Söhnen Israel hinaus. Und sie sahen sie und nahmen jeder seinen Stab." },
      { number: 25, text: "Und der HERR sprach zu Mose: Bring den Stab Aarons vor das Zeugnis zurück, um ihn als ein Zeichen für die Widerspenstigen* aufzubewahren*, damit du ihrem Murren vor mir ein Ende machst und sie nicht sterben!", footnotes: ["w. die Söhne der Widerspenstigkeit", "℘ 2Mo 16,34; Hebr 9,4"] },
      { number: 26, text: "Und Mose tat das. Wie der HERR ihm geboten hatte, so tat er es." },
      { number: 27, text: "Und die Söhne Israel sagten zu Mose: Siehe, wir vergehen, wir kommen um, wir alle kommen um.*", footnotes: ["℘ Ps 90,7; Jes 64,6"] },
      { number: 28, text: "Jeder, der irgend der Wohnung des HERRN naht, der stirbt*. Sollen wir denn ganz und gar vergehen?", footnotes: ["℘ Kap. 1,51"] },
    ]},
    { number: 18, verses: [
      { number: 1, text: "Und der HERR sprach zu Aaron: Du und deine Söhne und das Haus deines Vaters mit dir, ihr sollt die Schuld* am Heiligtum tragen; und du und deine Söhne mit dir, ihr sollt die Schuld* in eurem Priesteramt tragen*.", heading: "Dienst und Unterhalt der Priester und Leviten", footnotes: ["d. h. die Verantwortung für eine mögliche Schuld", "d. h. die Verantwortung für eine mögliche Schuld", "℘ 2Mo 28,38"] },
      { number: 2, text: "Und auch deine Brüder, den Stamm Levi, den Stamm deines Vaters, lass mit dir herzunahen, dass sie sich dir anschließen* und dir dienen*; du aber und deine Söhne mit dir, <ihr sollt> vor dem Zelt des Zeugnisses sein.", footnotes: ["℘ 1Mo 29,34; Mal 2,4", "℘ Kap. 3,6-10"] },
      { number: 3, text: "Und sie sollen deinen Dienst verrichten und den Dienst am ganzen Zelt*; nur den Geräten des Heiligtums und dem Altar sollen sie nicht nahen, damit sie nicht sterben, sowohl sie als auch ihr*.", footnotes: ["℘ Kap. 1,53; Hebr 9,6", "℘ Kap. 4,15.19.20; Hes 44,13"] },
      { number: 4, text: "Und sie sollen sich dir anschließen und den Dienst am Zelt der Begegnung verrichten nach aller Arbeit für das Zelt*; aber kein Fremder* soll euch nahen*.", footnotes: ["℘ Kap. 1,53; Hebr 9,6", "o. Unbefugter", "℘ Kap. 1,51"] },
      { number: 5, text: "Und ihr sollt den Dienst am Heiligtum und den Dienst am Altar verrichten*, damit kein Zorn mehr über die Söhne Israel kommt.", footnotes: ["℘ Kap. 1,50; 1Chr 23,24-32; Hes 44,15.16"] },
      { number: 6, text: "Und ich, siehe, ich habe eure Brüder, die Leviten, aus der Mitte der Söhne Israel herausgenommen; euch als Geschenk sind sie dem HERRN gegeben*, die Arbeit für das Zelt der Begegnung zu verrichten.", footnotes: ["w. Gegebene; als Dienstbezeichnung gedacht\n℘ Kap. 3,6.9.12.13"] },
      { number: 7, text: "Du aber und deine Söhne mit dir, ihr sollt euer Priesteramt versehen* in allem, was den Altar betrifft, und innerhalb des Vorhangs* und so die Arbeit tun; als eine geschenkte Aufgabe gebe ich euch das Priesteramt*. Der Fremde aber, der sich nähert, soll getötet werden*.", footnotes: ["℘ Kap. 3,10", "℘ 3Mo 16,2", "℘ 2Mo 28,1", "℘ Kap. 1,51"] },
      { number: 8, text: "Und der HERR redete zu Aaron: Und ich, siehe, ich habe dir den Dienst meiner Hebopfer gegeben*. Von allen heiligen Gaben* der Söhne Israel habe ich sie dir und deinen Söhnen gegeben als Anteil, als eine ewige Ordnung*.", footnotes: ["℘ Kap. 5,9.10; 3Mo 7,14", "o. heiligen Dingen", "o. ein ewiges Anrecht\n℘ 3Mo 7,35.36"] },
      { number: 9, text: "Dies soll dir gehören von dem Hochheiligen, <alles,> was nicht verbrannt wird*: Alle ihre Gaben an allen ihren Speisopfern* und an allen ihren Sündopfern und an allen ihren Schuldopfern, die sie mir darbringen*, als ein Hochheiliges soll es dir und deinen Söhnen gehören*.", footnotes: ["w. <abgesehen> vom Feuer", "℘ 3Mo 2,3.10", "w. zurückbringen, o. zurückgeben", "℘ 3Mo 6,19; 5Mo 18,1; 2Kö 12,17"] },
      { number: 10, text: "An einem hochheiligen <Ort> sollst du es essen*, jede männliche <Person> darf es essen; es soll dir heilig sein.", footnotes: ["℘ 3Mo 7,6"] },
      { number: 11, text: "Und dies soll dir gehören: Die Hebopfer ihrer Gaben an allen Schwingopfern der Söhne Israel; dir und deinen Söhnen und deinen Töchtern bei dir habe ich sie gegeben als eine ewige Ordnung*;* jeder Reine in deinem Hause darf es essen*.", footnotes: ["o. ein ewiges Anrecht", "℘ 2Mo 29,27.28", "℘ 3Mo 22,7"] },
      { number: 12, text: "Alles Beste* vom Öl und alles Beste* vom Most und Getreide, ihre Erstlinge, die sie dem HERRN geben, dir habe ich sie gegeben*.", footnotes: ["w. Fett", "w. Fett", "℘ 2Mo 23,19; 3Mo 23,17.20; 5Mo 18,4; 26,2; 2Kö 4,42; 2Chr 31,5"] },
      { number: 13, text: "Die ersten Früchte von allem, was in ihrem Land <wächst>, die sie dem HERRN bringen, sollen dir gehören*; jeder Reine in deinem Hause darf davon essen*.", footnotes: ["℘ 3Mo 22,7", "℘ 3Mo 22,7"] },
      { number: 14, text: "Alles Gebannte in Israel soll dir gehören*.", footnotes: ["℘ 3Mo 27,21"] },
      { number: 15, text: "Alles, was <zuerst> den Mutterschoß durchbricht, von allem Fleisch, das sie dem HERRN darbringen an Menschen und an Vieh, soll dir gehören; nur sollst du unbedingt den Erstgeborenen vom Menschen auslösen, und <auch> das Erstgeborene vom unreinen Vieh sollst du auslösen.*", footnotes: ["℘ 2Mo 13,13.15"] },
      { number: 16, text: "Und die zu Lösenden unter ihnen sollst du <im Alter> von einem Monat auslösen, nach deiner Einschätzung mit fünf Schekel Silber nach dem Schekel des Heiligtums, der zwanzig Gera beträgt*.", footnotes: ["℘ Kap. 3,47; 2Mo 30,13"] },
      { number: 17, text: "Aber das Erstgeborene vom Rind oder das Erstgeborene von den Schafen oder das Erstgeborene von den Ziegen sollst du nicht auslösen; sie sind heilig*. Ihr Blut sollst du an den Altar sprengen, und ihr Fett sollst du als Feueropfer in Rauch aufgehen lassen zum wohlgefälligen Geruch* für den HERRN*.", footnotes: ["℘ 5Mo 15,19", "o. zum Geruch der Befriedigung o. Beschwichtigung", "℘ 3Mo 3,2-5"] },
      { number: 18, text: "Und ihr Fleisch soll dir gehören; wie die Brust des Schwingopfers und die rechte Keule soll es dir gehören*.", footnotes: ["℘ 3Mo 7,32-34; Neh 10,37"] },
      { number: 19, text: "Alle Hebopfer der heiligen Gaben*, die die Söhne Israel dem HERRN abheben, habe ich dir gegeben und deinen Söhnen und deinen Töchtern mit dir*, als eine ewige Ordnung*; es ist ein ewiger Salzbund* vor dem HERRN für dich und für deine Nachkommen mit dir.", footnotes: ["o. der heiligen Dinge", "℘ 2Mo 29,27.28", "o. ein ewiges Anrecht\n℘ 2Mo 29,27.28", "℘ 2Chr 13,5"] },
      { number: 20, text: "Und der HERR sprach zu Aaron: In ihrem Land sollst du nichts erben* und sollst keinen Anteil in ihrer Mitte haben*; ich bin dein Anteil und dein Erbe inmitten der Söhne Israel.", footnotes: ["d. h. keinen Anteil an dem Israel unter Josua zugeteilten Landbesitz haben", "℘ Kap. 26,62; 5Mo 10,9; Jos 13,14.33"] },
      { number: 21, text: "Und siehe, den Söhnen Levi habe ich den gesamten Zehnten in Israel zum Erbteil gegeben* für ihre Arbeit, die sie verrichten, die Arbeit für das Zelt der Begegnung*.", footnotes: ["℘ 3Mo 27,30.32; Neh 10,38; 13,12; Hebr 7,5", "℘ Kap. 3,6-10"] },
      { number: 22, text: "Und die Söhne Israel sollen nicht mehr dem Zelt der Begegnung nahen, sonst laden sie* Sünde auf sich und müssen sterben*;", footnotes: ["w. sonst tragen sie", "℘ 2Mo 28,43"] },
      { number: 23, text: "die Leviten sollen vielmehr* die Arbeit am Zelt der Begegnung verrichten, und sie allein sollen ihre Schuld tragen: eine ewige Ordnung für <alle> eure Generationen*. Aber inmitten der Söhne Israel sollen sie kein Erbteil besitzen*;", footnotes: ["w. der Levit aber, er soll", "℘ Kap. 19,21; 35,29; 2Mo 27,21", "℘ Kap. 26,62; 5Mo 10,9; Jos 13,14.33"] },
      { number: 24, text: "denn den Zehnten der Söhne Israel, den sie dem HERRN als Hebopfer abheben, habe ich den Leviten zum Erbteil gegeben*; darum habe ich von ihnen gesagt, dass sie inmitten der Söhne Israel kein Erbteil besitzen sollen*.", footnotes: ["℘ Kap. 26,62; 5Mo 10,9; Jos 13,14.33", "℘ Kap. 26,62; 5Mo 10,9; Jos 13,14.33"] },
      { number: 25, text: "Und der HERR redete zu Mose und sprach:" },
      { number: 26, text: "Und zu den Leviten sollst du reden und zu ihnen sagen: Wenn ihr von den Söhnen Israel den Zehnten nehmt, den ich euch von ihnen als euer Erbteil gegeben habe, dann sollt ihr davon ein Hebopfer für den HERRN abheben, den Zehnten von dem Zehnten*.", footnotes: ["℘ Neh 10,39"] },
      { number: 27, text: "Und euer Hebopfer wird euch angerechnet werden wie das Getreide von der Tenne und wie die Fülle von der Kelterkufe." },
      { number: 28, text: "So sollt auch ihr ein Hebopfer für den HERRN abheben von allen euren Zehnten, die ihr von den Söhnen Israel nehmt, und davon das Hebopfer für den HERRN Aaron, dem Priester, geben*.", footnotes: ["℘ Kap. 31,29"] },
      { number: 29, text: "Von allem euch Gegebenen sollt ihr alle Hebopfer des HERRN abheben, von allem Besten* davon als heilige <Gabe>.", footnotes: ["w. Fett"] },
      { number: 30, text: "Und du sollst zu ihnen sagen: Wenn ihr das Beste* davon abhebt, dann soll es den Leviten angerechnet werden wie der Ertrag der Tenne und wie der Ertrag der Kelterkufe.", footnotes: ["w. Fett"] },
      { number: 31, text: "Und ihr dürft ihn essen an jedem Ort, ihr und euer Haus; denn das ist euer Lohn für eure Arbeit am Zelt der Begegnung*.", footnotes: ["℘ Mt 10,10; 1Kor 9,13"] },
      { number: 32, text: "Und ihr werdet deshalb keine Sünde auf euch laden, wenn ihr das Beste* davon abhebt, und werdet die heiligen Gaben* der Söhne Israel nicht entweihen und nicht sterben*.", footnotes: ["w. Fett", "o. heiligen Dinge", "℘ 2Mo 28,43"] },
    ]},
    { number: 19, verses: [
      { number: 1, text: "Und der HERR redete zu Mose und zu Aaron und sprach:", heading: "Verordnungen für das Opfer der roten Kuh und das Reinigungswasser" },
      { number: 2, text: "Dies ist die Ordnung des Gesetzes, das der HERR geboten hat, indem er sprach: Rede zu den Söhnen Israel, dass sie dir eine rote junge Kuh bringen, ohne Fehler, an der kein Makel ist*, auf die <noch> kein Joch gekommen ist*;", footnotes: ["℘ 3Mo 1,3.10", "℘ 5Mo 21,3"] },
      { number: 3, text: "und ihr sollt sie dem Priester Eleasar übergeben, und er soll sie vor das Lager hinausführen, und man soll sie vor ihm schlachten." },
      { number: 4, text: "Und der Priester Eleasar nehme <etwas> von ihrem Blut mit seinem Finger und sprenge von ihrem Blut siebenmal gegen die Vorderseite des Zeltes der Begegnung hin*.", footnotes: ["℘ 3Mo 4,6.17"] },
      { number: 5, text: "Und man soll die junge Kuh vor seinen Augen verbrennen; ihre Haut und ihr Fleisch und ihr Blut samt ihrem Mageninhalt* soll man verbrennen*.", footnotes: ["o. Darminhalt", "℘ 2Mo 29,14"] },
      { number: 6, text: "Und der Priester soll Zedernholz und Ysop und Karmesin nehmen* und es mitten in den Brand der jungen Kuh werfen.", footnotes: ["℘ 3Mo 14,4.6"] },
      { number: 7, text: "Und der Priester soll seine Kleider waschen und sein Fleisch im Wasser baden, und danach soll er in das Lager <zurück>gehen; und der Priester wird unrein sein bis zum Abend*.", footnotes: ["℘ V. 21.22; 3Mo 11,25; 16,28; Hebr 9,10"] },
      { number: 8, text: "Und der sie verbrennt, soll seine Kleider mit Wasser waschen und sein Fleisch im Wasser baden, und er wird unrein sein bis zum Abend*.", footnotes: ["℘ V. 21.22; 3Mo 11,25; 16,28; Hebr 9,10"] },
      { number: 9, text: "Und ein reiner Mann soll die Asche der jungen Kuh einsammeln und sie außerhalb des Lagers an einen reinen Ort schütten*, und sie soll für die Gemeinde der Söhne Israel aufbewahrt werden für das Wasser der Reinigung*; es ist eine Entsündigung*.", footnotes: ["w. niederlegen", "w. Wasser der Absonderung (durch das man die kultische Reinheit wiedererlangte)\n℘ Kap. 31,23; Hebr 9,13", "℘ Kap. 8,7"] },
      { number: 10, text: "Und der die Asche der jungen Kuh eingesammelt hat, soll seine Kleider waschen, und er wird unrein sein bis zum Abend*. Und es soll den Söhnen Israel und dem Fremden, der in ihrer Mitte weilt, zur ewigen Ordnung sein.", footnotes: ["℘ V. 21.22; 3Mo 11,25; 16,28; Hebr 9,10"] },
      { number: 11, text: "Wer einen Toten berührt, die Leiche irgendeines Menschen*, der wird sieben Tage unrein sein*.", footnotes: ["w. irgendeine Seele eines Menschen", "℘ Kap. 5,2; 6,6; 9,6; 3Mo 21,1.11; Hes 39,12.16; 44,26"] },
      { number: 12, text: "Dieser soll sich am dritten Tag damit entsündigen, und am siebten Tag wird er rein sein*; und wenn er sich nicht entsündigt am dritten Tag, dann wird er am siebten Tag nicht rein sein.", footnotes: ["℘ Kap. 31,19.24; 3Mo 14,7.9"] },
      { number: 13, text: "Jeder, der einen Toten berührt, die Leiche* eines Menschen, der gestorben ist, und sich nicht entsündigt, hat die Wohnung des HERRN unrein gemacht*; und diese Seele soll ausgerottet werden aus Israel*. Weil das Wasser der Reinigung* nicht auf ihn gesprengt wurde, ist er unrein; seine Unreinheit ist noch an ihm.", footnotes: ["w. die Seele", "℘ Kap. 9,13; 3Mo 15,31; 22,4", "℘ 2Mo 30,33.38", "w. Wasser der Absonderung (durch das man die kultische Reinheit wiedererlangte)"] },
      { number: 14, text: "Dies ist das Gesetz, wenn ein Mensch in einem Zelt stirbt: Jeder, der in das Zelt geht, und jeder, der in dem Zelt ist, wird sieben Tage unrein sein*.", footnotes: ["℘ Kap. 5,2; 6,6; 9,6; 3Mo 21,1.11; Hes 39,12.16; 44,26"] },
      { number: 15, text: "Und jedes offene Gefäß, auf dem kein festgebundener Deckel ist, wird unrein sein*. —", footnotes: ["℘ 3Mo 11,32.33"] },
      { number: 16, text: "Und jeder, der auf freiem Feld einen mit dem Schwert Erschlagenen oder einen Verstorbenen oder die Knochen eines Menschen oder ein Grab berührt, wird sieben Tage unrein sein*.", footnotes: ["℘ Kap. 5,2; 6,6; 9,6; 3Mo 21,1.11; Hes 39,12.16; 44,26"] },
      { number: 17, text: "Und man soll für den Unreinen <etwas> von dem Staub des zur Entsündigung Verbrannten nehmen und lebendiges* Wasser darauf in ein Gefäß geben;", footnotes: ["d. h. fließendes"] },
      { number: 18, text: "und ein reiner Mann soll ein Ysop<büschel> nehmen* und es in das Wasser eintauchen und soll <etwas> auf das Zelt sprengen und auf alle Gefäße und auf die Personen, die dort sind, und auf den, der die Knochen oder den Erschlagenen oder den Verstorbenen oder das Grab berührt hat.", footnotes: ["℘ Ps 51,9"] },
      { number: 19, text: "Und zwar soll der Reine den Unreinen am dritten Tag und am siebten Tag besprengen und ihn am siebten Tag entsündigen; und er soll seine Kleider waschen und sich im Wasser baden, und am Abend wird er rein sein*. —", footnotes: ["℘ Kap. 31,24"] },
      { number: 20, text: "Und wenn jemand unrein wird und sich nicht entsündigt, dann soll diese Seele ausgerottet werden* aus der Mitte der Versammlung*; denn er hat das Heiligtum des HERRN unrein gemacht*; das Wasser der Reinigung* ist nicht auf ihn gesprengt worden, er ist unrein.", footnotes: ["℘ 3Mo 17,16", "℘ Kap. 9,13; 3Mo 15,31; 22,4", "℘ Kap. 9,13; 3Mo 15,31; 22,4", "w. Wasser der Absonderung (durch das man die kultische Reinheit wiedererlangte)"] },
      { number: 21, text: "Das soll ihnen zur ewigen Ordnung sein*. Und wer das Wasser der Reinigung* sprengt, soll seine Kleider waschen; und wer das Wasser der Reinigung berührt, wird unrein sein bis zum Abend*.", footnotes: ["℘ 2Mo 27,21", "w. Wasser der Absonderung (durch das man die kultische Reinheit wiedererlangte)", "℘ V. 7.8.10"] },
      { number: 22, text: "Und alles, was der Unreine berührt, wird unrein sein*; und wer* ihn berührt, wird unrein sein bis zum Abend*.", footnotes: ["℘ 3Mo 15,1-11; Hag 2,13", "o. die Seele, die", "℘ V. 7.8.10"] },
    ]},
    { number: 20, verses: [
      { number: 1, text: "Und die Söhne Israel, die ganze Gemeinde, kamen in die Wüste Zin im ersten Monat*; und das Volk blieb in Kadesch*; und Mirjam* starb dort und wurde dort begraben. —", heading: "Mirjams Tod — Wasser aus dem Felsen — Moses und Aarons Vergehen", footnotes: ["℘ V. 28", "℘ Kap. 13,26; 1Mo 14,7; 5Mo 1,46; Hes 47,19", "℘ Kap. 26,59"] },
      { number: 2, text: "Und es war kein Wasser da für die Gemeinde; da versammelten sie sich gegen Mose und gegen Aaron*.", footnotes: ["℘ Kap. 14,2; 2Mo 17,1.2"] },
      { number: 3, text: "Und das Volk stritt mit Mose, und sie sagten: Wären wir doch umgekommen, als unsere Brüder vor dem HERRN umkamen*!", footnotes: ["℘ Kap. 14,36.37"] },
      { number: 4, text: "Und warum habt ihr die Versammlung des HERRN in diese Wüste gebracht, damit wir in ihr sterben, wir und unser Vieh*?", footnotes: ["℘ Kap. 11,20; 2Mo 16,3"] },
      { number: 5, text: "Und warum habt ihr uns aus Ägypten heraufgeführt, um uns an diesen bösen Ort zu bringen? Es ist nicht ein Ort für Saat und für Feigenbäume und Weinstöcke und Granatbäume, auch ist kein Wasser da zum Trinken*.", footnotes: ["℘ Kap. 16,14; 27,14"] },
      { number: 6, text: "Und Mose und Aaron gingen von der Versammlung fort zum Eingang des Zeltes der Begegnung und fielen auf ihr Angesicht nieder*; und die Herrlichkeit des HERRN erschien ihnen.", footnotes: ["℘ Kap. 16,4.22"] },
      { number: 7, text: "Und der HERR redete zu Mose und sprach:" },
      { number: 8, text: "Nimm den Stab* und versammle die Gemeinde, du und dein Bruder Aaron, und redet vor ihren Augen zu dem Felsen! Dann wird er sein Wasser geben; und du wirst ihnen Wasser aus dem Felsen hervorbringen und die Gemeinde tränken und ihr Vieh.", footnotes: ["℘ 2Mo 17,5"] },
      { number: 9, text: "Und Mose nahm den Stab <von dem Ort> vor dem HERRN, wie er ihm geboten hatte." },
      { number: 10, text: "Und Mose und Aaron versammelten die Versammlung vor dem Felsen; und er sagte zu ihnen: Hört doch, ihr Widerspenstigen! Werden wir für euch Wasser aus diesem Felsen hervorbringen?*", footnotes: ["℘ Ps 106,32.33"] },
      { number: 11, text: "Und Mose erhob seine Hand und schlug den Felsen mit seinem Stab zweimal; da kam viel Wasser heraus*, und die Gemeinde trank und ihr Vieh*.", footnotes: ["℘ Ri 15,19", "℘ 2Mo 17,6"] },
      { number: 12, text: "Da sprach der HERR zu Mose und zu Aaron: Weil ihr mir nicht geglaubt habt, mich vor den Augen der Söhne Israel zu heiligen*, darum sollt ihr diese Versammlung nicht in das Land bringen, das ich ihnen gegeben habe*.", footnotes: ["℘ 3Mo 10,3; 5Mo 32,51", "℘ Kap. 27,14; 5Mo 1,37; Ps 99,8"] },
      { number: 13, text: "Das ist das Wasser von Meriba, wo die Söhne Israel mit dem HERRN stritten* und er sich an ihnen heilig erwies*.", footnotes: ["℘ 2Mo 17,7; Ps 81,8", "℘ Jes 5,16; Hes 20,41"] },
      { number: 14, text: "Und Mose sandte Boten von Kadesch aus an den König von Edom*: So spricht dein Bruder Israel*: Du kennst all die Mühsal, die uns betroffen hat:", heading: "Edomiter stellen sich gegen den Durchzug Israels", footnotes: ["℘ 1Mo 36,31", "℘ 1Mo 25,25.26; 32,29"] },
      { number: 15, text: "Unsere Väter zogen nach Ägypten hinab*, und wir haben eine lange Zeit in Ägypten gewohnt; und die Ägypter behandelten uns und unsere Väter schlecht*.", footnotes: ["℘ 1Mo 46,6.7", "℘ 1Mo 15,13; 5Mo 26,6"] },
      { number: 16, text: "Da schrien wir zu dem HERRN, und er hat unsere Stimme gehört* und einen Engel gesandt* und uns aus Ägypten herausgeführt*; und siehe, wir sind in Kadesch, einer Stadt am Rand deines Gebiets.", footnotes: ["℘ 2Mo 2,23.24", "℘ 2Mo 23,20", "℘ 5Mo 4,34.37; Apg 7,35.36; Hebr 8,9"] },
      { number: 17, text: "Lass uns doch durch dein Land ziehen! Wir wollen nicht durch die Äcker und durch die Weinberge ziehen und wollen kein Wasser aus den Brunnen trinken; auf der Straße des Königs wollen wir gehen <und> nicht abbiegen zur Rechten oder zur Linken, bis wir durch dein Gebiet gezogen sind*.", footnotes: ["℘ Kap. 21,22"] },
      { number: 18, text: "Aber Edom sagte zu ihm: Du darfst nicht bei mir durchziehen, sonst ziehe ich dir mit dem Schwert entgegen*.", footnotes: ["℘ Kap. 21,23"] },
      { number: 19, text: "Und die Söhne Israel sagten zu ihm: Auf der Landstraße* wollen wir hinaufziehen; und wenn wir von deinem Wasser trinken, ich und mein Vieh, dann will ich den Preis dafür bezahlen*. Nur zu Fuß will ich hindurchziehen, weiter nichts*.", footnotes: ["d. i. ein aufgeschütteter, erhöhter Weg", "w. geben", "o. es bedeutet ja nichts\n℘ 5Mo 2,6.28"] },
      { number: 20, text: "Und er sagte: Du darfst nicht hindurchziehen! Und Edom zog aus, ihm entgegen, mit zahlreichem Volk und mit starker Hand*.", footnotes: ["℘ Ri 11,17; Am 1,11"] },
      { number: 21, text: "Und so weigerte sich Edom, Israel zu gestatten, durch sein Gebiet zu ziehen; und Israel bog ab*.", footnotes: ["w. bog von ihm ab\n℘ Kap. 21,4; 5Mo 2,4-8; 2Chr 20,10"] },
      { number: 22, text: "Und sie brachen auf von Kadesch; und die Söhne Israel, die ganze Gemeinde, kamen an den Berg Hor*.", heading: "Aarons Tod", footnotes: ["℘ Kap. 33,37"] },
      { number: 23, text: "Und der HERR redete zu Mose und zu Aaron am Berge Hor, an der Grenze des Landes Edom, und sprach:" },
      { number: 24, text: "Aaron soll zu seinen Völkern* versammelt werden*; denn er soll nicht in das Land kommen, das ich den Söhnen Israel gegeben habe, weil ihr gegen meinen Befehl widerspenstig gewesen seid bei dem Wasser von Meriba*.", footnotes: ["d. h. zu seinen Vorfahren", "℘ Kap. 27,13; 1Mo 25,8.17; 5Mo 32,50", "℘ V. 10-12"] },
      { number: 25, text: "Nimm Aaron und seinen Sohn Eleasar* und lass sie hinaufsteigen auf den Berg Hor;", footnotes: ["℘ 3Mo 10,6"] },
      { number: 26, text: "und ziehe Aaron seine Kleider aus und lege sie seinem Sohn Eleasar an! Und Aaron soll <zu seinen Vätern> versammelt werden und dort sterben." },
      { number: 27, text: "Und Mose tat, wie es der HERR befohlen hatte. Sie stiegen auf den Berg Hor vor den Augen der ganzen Gemeinde." },
      { number: 28, text: "Und Mose zog dem Aaron seine Kleider aus und legte sie seinem Sohn Eleasar an*. Und Aaron starb dort auf dem Gipfel des Berges*. Und Mose und Eleasar stiegen von dem Berg herab.", footnotes: ["℘ 2Mo 6,23; 29,29; 5Mo 10,6; Jos 24,33", "℘ Kap. 33,38.39; Hebr 7,23"] },
      { number: 29, text: "Und als die ganze Gemeinde sah, dass Aaron verschieden war, beweinte das ganze Haus Israel den Aaron dreißig Tage lang*.", footnotes: ["℘ 1Mo 23,2"] },
    ]},
    { number: 21, verses: [
      { number: 1, text: "Und der Kanaaniter, der König von Arad, der im Südland* wohnte, hörte, dass Israel den Weg nach Atarim* kam*, und er kämpfte gegen Israel und führte Gefangene von ihm weg.", heading: "Sieg über die Kanaaniter von Atarim", footnotes: ["hebr. Negev", "Alte Üs. lesen: auf dem Weg der Kundschafter", "℘ Kap. 33,40"] },
      { number: 2, text: "Da legte Israel dem HERRN gegenüber ein Gelübde ab* und sagte: Wenn du dieses Volk wirklich in meine Hand gibst, dann werde ich seine Städte mit dem Bann belegen*.", footnotes: ["℘ 1Mo 28,20", "℘ 3Mo 27,29; 5Mo 7,2.16; 13,16; Jos 6,17.18"] },
      { number: 3, text: "Und der HERR hörte auf die Stimme Israels* und gab die Kanaaniter <in seine Hand>; und es belegte sie und ihre Städte mit dem Bann. Und man gab dem Ort den Namen Horma*.", footnotes: ["℘ Ps 116,1", "d. h. Bann, o. Vernichtung\n℘ Kap. 14,45; Jos 12,14; 15,30"] },
      { number: 4, text: "Und sie brachen auf vom Berg Hor*, auf dem Weg zum Schilfmeer, um das Land Edom zu umgehen*. Und die Seele des Volkes wurde ungeduldig* auf dem Weg;", heading: "Feurige Schlangen und die eherne Schlange", footnotes: ["℘ Kap. 33,41", "℘ Kap. 20,21", "w. kurz"] },
      { number: 5, text: "und das Volk redete gegen Gott* und gegen Mose: Wozu habt ihr uns aus Ägypten heraufgeführt? Damit wir in der Wüste sterben?* Denn es ist kein Brot und kein Wasser da, und unserer Seele ekelt es vor dieser elenden Nahrung*.", footnotes: ["℘ Ps 78,19", "℘ 2Mo 16,3", "℘ Kap. 11,6"] },
      { number: 6, text: "Da sandte der HERR feurige Schlangen* unter das Volk, und sie bissen das Volk; und es starb viel Volk aus Israel*.", footnotes: ["w. die Schlangen, die Sarafen. — Das Wort Saraf kann von dem hebr. Wort saraf, »brennen«, abgeleitet werden.\n℘ 5Mo 8,15; Jes 30,6; Jer 8,17", "℘ 1Kor 10,9"] },
      { number: 7, text: "Da kam das Volk zu Mose, und sie sagten: Wir haben gesündigt*, dass wir gegen den HERRN und gegen dich geredet haben*. Bete zu dem HERRN, dass er die Schlangen von uns wegnimmt!* Und Mose betete für das Volk*.", footnotes: ["℘ 2Mo 9,27", "℘ Ps 78,34", "℘ 2Mo 9,28; 1Sam 12,19", "℘ Kap. 11,2; 2Mo 32,11"] },
      { number: 8, text: "Und der HERR sprach zu Mose: Mache dir eine Schlange* und tu sie auf eine Stange! Und es wird geschehen, jeder, der gebissen ist und sie ansieht, der wird am Leben bleiben.", footnotes: ["w. einen Saraf; vgl. Anm. zu V. 6"] },
      { number: 9, text: "Und Mose machte eine Schlange von Bronze* und tat sie auf die Stange; und es geschah, wenn eine Schlange jemanden gebissen hatte und er schaute auf zu der ehernen* Schlange, so blieb er am Leben*.", footnotes: ["℘ 2Kö 18,4", "w. zu der bronzenen", "℘ Joh 3,14.15"] },
      { number: 10, text: "Und die Söhne Israel brachen auf und lagerten sich in Obot*.", heading: "Siege über den Amoriterkönig Sihon und über Og, den König von Baschan", footnotes: ["℘ Kap. 33,43.44"] },
      { number: 11, text: "Und sie brachen auf von Obot und lagerten sich in Ije-Abarim in der Wüste, die vor Moab* gegen Osten ist.", footnotes: ["℘ Kap. 33,43.44"] },
      { number: 12, text: "Von dort brachen sie auf und lagerten sich am Bach Sered*.", footnotes: ["℘ 5Mo 2,13.18.24"] },
      { number: 13, text: "Von dort brachen sie auf und lagerten sich auf der andern Seite des Arnon*, der in der Wüste ist, der aus dem Gebiet der Amoriter hervorkommt. Denn der Arnon ist die Grenze von Moab*, zwischen Moab und den Amoritern.", footnotes: ["℘ 5Mo 2,13.18.24", "℘ Kap. 22,36; Ri 11,18; Jes 16,2"] },
      { number: 14, text: "Darum heißt es in dem Buch der Kämpfe des HERRN: Das Waheb in Sufa und die Bäche des Arnon;" },
      { number: 15, text: "und der Abfluss der Bäche, der sich erstreckt nach dem Wohnsitz von Ar* und sich anlehnt an das Gebiet von Moab.", footnotes: ["℘ 5Mo 2,9"] },
      { number: 16, text: "Und von dort <zogen sie> nach Beer*; das ist der Brunnen, von dem der HERR zu Mose sprach: Versammle das Volk! Und ich will ihnen Wasser geben.", footnotes: ["℘ Ri 9,21; Jes 15,8"] },
      { number: 17, text: "Damals sang Israel dieses Lied*: Steige herauf, Brunnen! Singt ihm zu!", footnotes: ["℘ 2Mo 15,1"] },
      { number: 18, text: "Brunnen, den Oberste gegraben, den die Edlen des Volkes gehöhlt haben mit dem Zepter, mit ihren Stäben! Und aus der Wüste* <zogen sie> nach Mattana;", footnotes: ["LXX: Und von Beer"] },
      { number: 19, text: "und von Mattana nach Nahaliël; und von Nahaliël nach Bamot;" },
      { number: 20, text: "und von Bamot in das Tal, das im Gebiet* von Moab ist, bei dem Gipfel des Pisga*, der hinunterblickt über die Fläche der Wildnis*.", footnotes: ["o. Feld", "℘ Kap. 23,14", "o. die Fläche von Jeschimon; d. i. das untere Jordantal\n℘ Kap. 23,28"] },
      { number: 21, text: "*Und Israel sandte Boten zu Sihon, dem König der Amoriter*, und ließ <ihm> sagen:", footnotes: ["℘ V. 21-35: Jos 12,1-6", "℘ 5Mo 2,26.27; Ri 11,19"] },
      { number: 22, text: "Lass mich durch dein Land ziehen! Wir wollen nicht auf die Äcker und in die Weinberge abbiegen, wir wollen kein Wasser aus den Brunnen trinken; auf der Straße des Königs wollen wir gehen, bis wir durch dein Gebiet gezogen sind*.", footnotes: ["℘ Kap. 20,17"] },
      { number: 23, text: "Aber Sihon gestattete Israel nicht, durch sein Gebiet zu ziehen; und Sihon sammelte all sein <Kriegs>volk und zog aus, Israel entgegen in die Wüste, und kam nach Jahaz* und kämpfte gegen Israel*.", footnotes: ["℘ 5Mo 2,30-32; Jes 15,4", "℘ Kap. 20,18; Ri 11,20"] },
      { number: 24, text: "Und Israel schlug ihn mit der Schärfe des Schwertes und nahm sein Land in Besitz* vom Arnon bis an den Jabbok, bis zu den Söhnen Ammon*; denn die Grenze der Söhne Ammon war fest*.", footnotes: ["℘ Kap. 32,4; 5Mo 4,46; 31,4; Ri 10,11", "℘ 5Mo 2,33-37; Ri 11,13; Ps 135,10.11", "LXX: denn Jaser ist die Grenze der Söhne Ammon"] },
      { number: 25, text: "Und Israel nahm alle diese Städte ein, und Israel wohnte in allen Städten der Amoriter, in Heschbon und in allen seinen Tochterstädten*.", footnotes: ["℘ Kap. 32,3.37; Jos 24,8"] },
      { number: 26, text: "Denn Heschbon* war die Stadt Sihons, des Königs der Amoriter*; und dieser hatte gegen den früheren König von Moab gekämpft und hatte sein ganzes Land bis an den Arnon aus seiner Hand weggenommen.", footnotes: ["℘ Hl 7,5; Jer 48,2", "℘ 5Mo 1,4"] },
      { number: 27, text: "Daher sagen die Spruchdichter: Kommt nach Heschbon! Aufgebaut und befestigt werde* die Stadt Sihons!", footnotes: ["o. wird"] },
      { number: 28, text: "Denn Feuer ging aus* von Heschbon, eine Flamme von der Stadt Sihons; es fraß Ar in Moab*, die Herren der Höhen des Arnon*.", footnotes: ["℘ Ri 9,15", "Andere lesen: die Städte Moabs\n℘ Jes 15,1", "LXX: verschlang die Höhen am Arnon"] },
      { number: 29, text: "Wehe dir, Moab! Du bist verloren, Volk des Kemosch!* Er hat seine Söhne zu Flüchtlingen gemacht und seine Töchter in die Gefangenschaft Sihons geführt*, des Königs der Amoriter.", footnotes: ["℘ Ri 11,24", "℘ Jer 48,45.46"] },
      { number: 30, text: "Da haben wir auf sie geschossen; Heschbon ist verloren bis Dibon*; da haben wir verödet bis Nofach, das bei Medeba* liegt*.", footnotes: ["LXX: ihr Geschlecht ist vernichtet von Heschbon bis Dibon\n℘ Kap. 32,3; Jos 13,17; Jer 48,18.22", "℘ Jos 13,9.16; Jes 15,2", "o. das bis Medeba geht"] },
      { number: 31, text: "Und Israel wohnte im Land der Amoriter*.", footnotes: ["℘ 1Mo 15,21; Jos 24,12.13"] },
      { number: 32, text: "Und Mose sandte <Männer> aus, um Jaser* zu erkunden; und sie nahmen seine Tochterstädte ein, und er trieb die Amoriter aus, die dort waren*.", footnotes: ["℘ Kap. 32,1; Jes 16,8.9", "℘ 1Mo 15,21; Jos 24,12.13"] },
      { number: 33, text: "Und sie wandten sich und zogen hinauf auf dem Weg nach Baschan*; und Og, der König von Baschan, zog aus ihnen entgegen, er und all sein <Kriegs>volk, zum Kampf nach Edreï*.", footnotes: ["℘ Am 4,1", "℘ 5Mo 2,30; 3,1.2"] },
      { number: 34, text: "Und der HERR sprach zu Mose: Fürchte ihn nicht*! Denn in deine Hand habe ich ihn gegeben und sein ganzes Volk und sein Land. Und tu ihm, wie du Sihon, dem König der Amoriter, getan hast, der zu Heschbon wohnte*.", footnotes: ["℘ 5Mo 7,17-19", "℘ 5Mo 2,30; 3,1.2"] },
      { number: 35, text: "Und sie schlugen ihn und seine Söhne und sein ganzes <Kriegs>volk*, bis ihm kein Entkommener übrig blieb; und sie nahmen sein Land in Besitz*.", footnotes: ["℘ Kap. 32,4; 5Mo 4,46; 31,4; Ri 10,11", "℘ 5Mo 3,3-11; 4,47; Ps 135,10-12"] },
    ]},
    { number: 22, verses: [
      { number: 1, text: "Und die Söhne Israel brachen auf und lagerten sich in den Ebenen* Moabs, jenseits des Jordan bei Jericho*.", heading: "Balaks Auftrag an Bileam", footnotes: ["o. Steppen", "℘ Kap. 26,3; 31,12; 33,48.50; 35,1; 36,13"] },
      { number: 2, text: "Und Balak, der Sohn Zippors*, sah alles, was Israel den Amoritern angetan hatte.", footnotes: ["℘ Ri 11,25"] },
      { number: 3, text: "Und Moab fürchtete sich sehr vor dem Volk, weil es <so> groß war, und es graute Moab* vor den Söhnen Israel*.", footnotes: ["o. Moab ekelte sich", "℘ 2Mo 1,12; 15,15; 23,27; 5Mo 2,25"] },
      { number: 4, text: "Und Moab sagte zu den Ältesten von Midian: Jetzt wird dieser Haufe unser ganzes <Land> ringsum abfressen, wie das Rind das Grüne des Feldes abfrisst. Balak aber, der Sohn Zippors, war zu jener Zeit König von Moab." },
      { number: 5, text: "Und er sandte Boten zu Bileam, dem Sohn Beors*, nach Petor, das am Strom* <liegt>, in das Land der Söhne von Ammo*, um ihn zu rufen. Und er ließ ihm sagen: Siehe, ein Volk ist aus Ägypten ausgezogen; siehe, es bedeckt die Fläche des Landes*, und es liegt mir gegenüber.", footnotes: ["℘ Kap. 31,8; 5Mo 23,5; Jos 24,9; Neh 13,1.2", "d. i. der Euphrat", "o. der Söhne seines Volkes. — 14 hebr. Handschr. und SamPent lesen: der Söhne Ammon", "℘ 2Mo 10,15"] },
      { number: 6, text: "Und nun komm doch, verfluche mir dieses Volk!* Denn es ist stärker als ich. Vielleicht gelingt es mir, dass wir es schlagen und ich es aus dem Land vertreibe. Denn ich habe erkannt: Wen du segnest, der ist gesegnet, und wen du verfluchst, der ist verflucht.", footnotes: ["℘ Kap. 23,7.13"] },
      { number: 7, text: "Und die Ältesten von Moab und die Ältesten von Midian zogen hin mit dem Wahrsagerlohn in ihrer Hand*. Und sie kamen zu Bileam und sagten ihm die Worte Balaks.", footnotes: ["℘ Jes 1,23; 56,11; Mi 3,11; 2Petr 2,15"] },
      { number: 8, text: "Und er sagte zu ihnen: Übernachtet hier diese Nacht! Und ich werde euch Antwort bringen, wie der HERR zu mir reden wird*. Und die Obersten von Moab blieben bei Bileam.", footnotes: ["℘ V. 18.38; Kap. 23,3; 24,13; 1Kö 13,8; 22,14; Joh 5,19.30"] },
      { number: 9, text: "Und Gott kam zu Bileam und sprach: Wer sind diese Männer bei dir*?", footnotes: ["℘ 2Kö 20,14"] },
      { number: 10, text: "Und Bileam sagte zu Gott: Balak, der Sohn Zippors, der König von Moab, hat <sie> zu mir gesandt:" },
      { number: 11, text: "»Siehe, das Volk, das aus Ägypten ausgezogen ist, bedeckt die Fläche des Landes. Komm jetzt, verfluche es mir! Vielleicht bin ich <dann> imstande, gegen es zu kämpfen und es zu vertreiben.«" },
      { number: 12, text: "Und Gott sprach zu Bileam: Du sollst nicht mit ihnen gehen; du sollst das Volk nicht verfluchen! Denn es ist gesegnet*.", footnotes: ["℘ 5Mo 2,7; 7,14; 2Chr 31,10; Jes 61,9; Eph 1,3"] },
      { number: 13, text: "Und Bileam stand am <nächsten> Morgen auf und sagte zu den Obersten von Balak: Geht <wieder> in euer Land! Denn der HERR hat sich geweigert, mir zu gestatten, mit euch zu gehen." },
      { number: 14, text: "Und die Obersten von Moab machten sich auf und kamen zu Balak und sagten: Bileam hat sich geweigert, mit uns zu gehen." },
      { number: 15, text: "Da sandte Balak noch einmal Oberste, mehr und angesehenere als jene." },
      { number: 16, text: "Und sie kamen zu Bileam und sagten zu ihm: So spricht Balak, der Sohn Zippors: Lass dich doch nicht abhalten, zu mir zu kommen!" },
      { number: 17, text: "Denn sehr hoch will ich dich belohnen*, und alles, was du mir sagen wirst, will ich tun. So komm doch, verfluche mir dieses Volk!", footnotes: ["w. ehren"] },
      { number: 18, text: "Und Bileam antwortete und sagte zu den Knechten Balaks: Wenn Balak mir sein Haus voller Silber und Gold gäbe, könnte ich nicht den Befehl des HERRN, meines Gottes, übertreten, um <etwas> Kleines oder Großes zu tun*.", footnotes: ["℘ V. 8.38"] },
      { number: 19, text: "Und nun bleibt doch auch ihr hier diese Nacht, und ich werde erkennen, was der HERR weiter mit mir reden wird." },
      { number: 20, text: "Da kam Gott nachts zu Bileam und sprach zu ihm: Wenn die Männer gekommen sind, um dich zu rufen, mache dich auf, geh mit ihnen! Aber nur das, was ich dir sagen werde, darfst du tun!" },
      { number: 21, text: "Und Bileam machte sich am Morgen auf und sattelte seine Eselin und ging mit den Obersten von Moab*.", heading: "Bileams Weg zu Balak", footnotes: ["℘ Spr 28,18"] },
      { number: 22, text: "Da entbrannte der Zorn Gottes, dass er ging. Und der Engel des HERRN stellte sich in den Weg, um ihm entgegenzutreten*. Er aber ritt auf seiner Eselin, und seine beiden Diener waren bei ihm.", footnotes: ["w. als sein Widersacher o. Gegner"] },
      { number: 23, text: "Und die Eselin sah den Engel des HERRN mit seinem gezückten Schwert in seiner Hand auf dem Weg stehen*, und die Eselin wich vom Weg ab und ging auf dem Feld <weiter>; und Bileam schlug die Eselin, um sie wieder auf den Weg zu lenken.", footnotes: ["℘ Jos 5,13; 1Chr 21,16"] },
      { number: 24, text: "Da trat der Engel des HERRN in einen Hohlweg zwischen den Weinbergen; eine Mauer war auf der einen und eine Mauer auf der andern Seite." },
      { number: 25, text: "Und die Eselin sah den Engel des HERRN und drückte sich an die Wand und drückte den Fuß Bileams an die Wand; und er schlug sie noch einmal." },
      { number: 26, text: "Da ging der Engel des HERRN noch einmal weiter und trat an eine enge Stelle, wo kein Weg war, um auszuweichen, weder zur Rechten noch zur Linken." },
      { number: 27, text: "Und als die Eselin den Engel des HERRN sah, legte sie sich hin unter Bileam. Da entbrannte der Zorn Bileams, und er schlug die Eselin mit dem Stock." },
      { number: 28, text: "Da öffnete der HERR den Mund der Eselin, und sie sagte zu Bileam: Was habe ich dir getan, dass du mich nun <schon> dreimal geschlagen hast*?", footnotes: ["℘ 2Petr 2,16"] },
      { number: 29, text: "Bileam sagte zu der Eselin: Weil du Mutwillen mit mir getrieben hast. Hätte ich doch ein Schwert in meiner Hand! Gewiss hätte ich dich jetzt erschlagen*!", footnotes: ["℘ Spr 12,10"] },
      { number: 30, text: "Und die Eselin sagte zu Bileam: Bin ich nicht deine Eselin, auf der du geritten bist von jeher* bis zum heutigen Tag? War es je meine Gewohnheit, dir so etwas zu tun*? Und er sagte: Nein.", footnotes: ["w. seitdem du bist", "℘ 2Petr 2,16"] },
      { number: 31, text: "Da enthüllte der HERR die Augen* Bileams, und er sah den Engel des HERRN mit seinem gezückten Schwert in seiner Hand auf dem Weg stehen*; und er neigte sich und fiel nieder auf sein Angesicht*.", footnotes: ["℘ 2Kö 6,17.20; Lk 24,31", "℘ Jos 5,13; 1Chr 21,16", "℘ Jos 5,14"] },
      { number: 32, text: "Und der Engel des HERRN sprach zu ihm: Warum hast du deine Eselin nun <schon> dreimal geschlagen? Siehe, ich selbst bin ausgegangen, um <dir> entgegenzutreten*, denn der Weg stürzt <dich ins Verderben> vor mir*.", footnotes: ["w. ich selbst bin als Widersacher ausgegangen", "℘ Spr 16,2"] },
      { number: 33, text: "Und die Eselin sah mich und wich vor mir aus, nun <schon> dreimal. Wenn sie nicht vor mir ausgewichen wäre, dann hätte ich dich jetzt auch erschlagen, sie aber am Leben gelassen." },
      { number: 34, text: "Und Bileam sagte zu dem Engel des HERRN: Ich habe gesündigt*, denn ich habe nicht erkannt, dass du mir auf dem Weg entgegentratest; und nun, wenn es böse ist in deinen Augen, dann will ich umkehren*.", footnotes: ["℘ 2Mo 9,27", "℘ Hi 34,31.32; Jud 11"] },
      { number: 35, text: "Und der Engel des HERRN sprach zu Bileam: Geh mit den Männern! Aber nur das, was ich dir sagen werde, sollst du reden! Und Bileam zog mit den Obersten des Balak*.", footnotes: ["℘ Spr 28,18"] },
      { number: 36, text: "Und als Balak hörte, dass Bileam gekommen sei, ging er aus, ihm entgegen, nach der Stadt Moabs*, an der Grenze des Arnon, der an der äußersten Grenze <fließt>*.", footnotes: ["hebr. Ir-Moab; dasselbe wie Ar oder Ar-Moab", "℘ Kap. 21,13"] },
      { number: 37, text: "Und Balak sagte zu Bileam: Habe ich nicht dringend zu dir gesandt, um dich zu rufen? Warum bist du nicht zu mir gekommen? Fürwahr, kann ich dich nicht belohnen*?*", footnotes: ["o. ehren", "℘ Kap. 24,11"] },
      { number: 38, text: "Und Bileam sagte zu Balak: Siehe, ich bin zu dir gekommen. Ob ich <aber> jetzt wirklich irgendetwas reden kann? Das Wort, das Gott mir in den Mund legt, das werde ich reden*.", footnotes: ["℘ V. 8.18"] },
      { number: 39, text: "Und Bileam ging mit Balak; und sie kamen nach Kirjat-Huzot." },
      { number: 40, text: "Und Balak opferte* Rinder und Schafe und schickte <davon> an Bileam und an die Obersten, die bei ihm waren.", footnotes: ["o. schlachtete"] },
      { number: 41, text: "Und es geschah am <nächsten> Morgen, da nahm Balak den Bileam und führte ihn hinauf auf die Höhen des Baal, und er sah von dort aus den äußersten <Teil> des Volkes <Israel>*.", footnotes: ["℘ Kap. 23,13"] },
    ]},
    { number: 23, verses: [
      { number: 1, text: "Und Bileam sagte zu Balak: Baue mir hier sieben Altäre, und stelle mir hier sieben Stiere bereit und sieben Widder*!", heading: "Bileams Segen: Erster und zweiter Spruch", footnotes: ["℘ Hi 42,8"] },
      { number: 2, text: "Und Balak tat es, wie Bileam gesagt hatte; und Balak und Bileam opferten einen Stier und einen Widder auf jedem Altar*.", footnotes: ["℘ V. 29.30"] },
      { number: 3, text: "Und Bileam sagte zu Balak: Stelle dich neben dein Brandopfer! Ich aber will hingehen; vielleicht wird der HERR mir entgegenkommen, und was er mich sehen lassen wird, das werde ich dir berichten*. Und er ging hin auf eine kahle Höhe.", footnotes: ["℘ V. 12.26; Kap. 22,8"] },
      { number: 4, text: "Und Gott kam dem Bileam entgegen; und der sagte zu ihm: Die sieben Altäre habe ich hergerichtet und auf jedem Altar einen Stier und einen Widder geopfert." },
      { number: 5, text: "Und der HERR legte ein Wort in den Mund Bileams und sprach: Kehre zu Balak zurück, und so sollst du reden*!", footnotes: ["℘ 5Mo 18,18"] },
      { number: 6, text: "Und er kehrte zu ihm zurück; und siehe, er stand neben seinem Brandopfer, er und alle Obersten von Moab." },
      { number: 7, text: "Da begann er seinen Spruch und sprach*: Aus Aram hat Balak mich hergeführt, von den Bergen des Ostens der König von Moab: Komm, verfluche mir Jakob! Ja, komm und verwünsche Israel!*", footnotes: ["℘ Ps 49,5", "℘ Kap. 22,5.6"] },
      { number: 8, text: "Wie soll ich verfluchen, wen Gott nicht verflucht*, und wie verwünschen, wen der HERR nicht verwünscht hat?", footnotes: ["℘ Spr 26,2"] },
      { number: 9, text: "Denn vom Gipfel der Felsen sehe ich es, und von den Höhen herab schaue ich es; siehe, ein Volk, das abgesondert wohnt* und sich nicht zu den Nationen rechnet*.", footnotes: ["℘ 5Mo 33,28; Est 3,8; Mi 7,14", "℘ 2Mo 33,16"] },
      { number: 10, text: "Wer könnte zählen den Staub Jakobs, und der Zahl nach, den vierten Teil Israels*? Meine Seele sterbe den Tod der Aufrichtigen, und mein Ende sei gleich dem ihren!*", footnotes: ["mit Textänderung: und wer die Zehntausende Israels berechnen\n℘ 1Mo 13,16", "℘ Kap. 31,8"] },
      { number: 11, text: "Da sagte Balak zu Bileam: Was hast du mir da angetan! Meine Feinde zu verfluchen, habe ich dich holen lassen, und siehe, du hast sie sogar noch gesegnet*!", footnotes: ["℘ Kap. 24,10"] },
      { number: 12, text: "Und er antwortete und sagte: Muss ich nicht darauf achten, das zu reden, was der HERR in meinen Mund legt*?", footnotes: ["℘ V. 3.26"] },
      { number: 13, text: "Und Balak sagte zu ihm: Komm doch mit mir an eine andere Stelle, von wo aus du es sehen kannst! Nur den äußersten <Teil> von ihm wirst du sehen, und du wirst es nicht ganz sehen*. Und verfluche es mir von dort aus!*", footnotes: ["℘ Kap. 22,41", "℘ Kap. 22,6"] },
      { number: 14, text: "Und er nahm ihn mit zu dem Feld der Späher, auf den Gipfel des Pisga*; und er baute sieben Altäre und opferte einen Stier und einen Widder auf jedem Altar.", footnotes: ["℘ Kap. 21,20; 5Mo 34,1"] },
      { number: 15, text: "Und er sagte zu Balak: Stelle dich hier neben dein Brandopfer, und ich, ich will dort <dem HERRN> begegnen." },
      { number: 16, text: "Und der HERR kam dem Bileam entgegen und legte ein Wort in seinen Mund und sprach: Kehre zu Balak zurück, und so sollst du reden*!", footnotes: ["℘ 5Mo 18,18"] },
      { number: 17, text: "Und er kam zu ihm, und siehe, er stand neben seinem Brandopfer und die Obersten von Moab bei ihm. Und Balak sagte zu ihm: Was hat der HERR geredet?*", footnotes: ["℘ 1Sam 3,17"] },
      { number: 18, text: "Da begann er seinen Spruch und sprach: Stehe auf, Balak, und höre!* Horche auf mich, Sohn des Zippor!", footnotes: ["℘ Ri 3,20"] },
      { number: 19, text: "Nicht ein Mensch ist Gott*, dass er lüge*, noch der Sohn eines Menschen, dass er bereue*. Sollte er gesprochen haben und es nicht tun und geredet haben und es nicht halten?*", footnotes: ["℘ Hos 11,9", "℘ Hab 2,3; Tit 1,2", "℘ 1Sam 15,29; Ps 132,11; Röm 9,6; 2Tim 2,13", "℘ Kap. 14,35; 1Mo 26,3; Jos 21,45; 1Sam 3,12; 1Kö 14,11; 2Kö 7,2; Ps 77,9; 89,35; Jes 21,17; Jer 4,28"] },
      { number: 20, text: "Siehe, zu segnen habe ich empfangen; er hat gesegnet*, und ich kann es nicht wenden*.*", footnotes: ["℘ Kap. 6,27", "o. und hat er gesegnet, so kann ich es nicht wenden", "℘ 1Chr 17,27"] },
      { number: 21, text: "Er erblickt kein Unrecht* in Jakob und sieht kein Verderben in Israel*; der HERR, sein Gott, ist mit ihm, und Königsjubel ist in ihm*.", footnotes: ["o. kein Unheil", "℘ 1Sam 25,28; Röm 4,7.8", "℘ Kap. 16,3; 3Mo 9,24; Ps 99,2; 135,21; Jes 12,6; 33,21; Hes 48,35; Joe 2,27"] },
      { number: 22, text: "Gott ist es, der es* aus Ägypten geführt*. Es hat <Kraft> wie die Hörner des Büffels*.", footnotes: ["w. sie", "℘ 2Mo 12,51; Mt 2,15", "℘ Kap. 24,8; 5Mo 33,17; Hi 39,10.11"] },
      { number: 23, text: "Denn es gibt keine Zauberei gegen Jakob und keine Wahrsagerei gegen Israel*. Jetzt wird zu Jakob und zu Israel gesagt: Was hat Gott gewirkt!*", footnotes: ["o. es ist keine Zauberei in Jakob und keine Wahrsagerei in Israel\n℘ Jes 44,25", "o. Zu seiner Zeit wird zu Jakob und zu Israel gesagt werden, was Gott wirkt.\n℘ 5Mo 3,24"] },
      { number: 24, text: "Siehe, ein Volk; wie eine Löwin steht es auf, und wie ein Löwe erhebt es sich*. Es legt sich nicht nieder, bis es die Beute verzehrt und das Blut der Erschlagenen getrunken hat!", footnotes: ["℘ Kap. 24,9"] },
      { number: 25, text: "Da sagte Balak zu Bileam: Willst du es schon nicht verfluchen, dann sollst du es auch nicht segnen.*", footnotes: ["w. Gar nicht verfluchen sollst du es, gar nicht segnen sollst du es!"] },
      { number: 26, text: "Und Bileam antwortete und sagte zu Balak: Habe ich nicht zu dir geredet und gesagt: Alles, was der HERR reden wird, das werde ich tun*?", footnotes: ["℘ V. 3.12"] },
      { number: 27, text: "Und Balak sagte zu Bileam: Komm doch, ich will dich an eine andere Stelle mitnehmen! Vielleicht wird es in den Augen Gottes recht sein, dass du es mir von dort aus verfluchst*.", footnotes: ["℘ Kap. 22,6"] },
      { number: 28, text: "Und Balak nahm den Bileam mit auf den Gipfel des Peor, der hinunterblickt über die Fläche der Wildnis*.*", footnotes: ["o. die Fläche von Jeschimon; d. i. das untere Jordantal", "℘ Kap. 21,20"] },
      { number: 29, text: "Und Bileam sagte zu Balak: Baue mir hier sieben Altäre, und stelle mir hier sieben Stiere und sieben Widder* bereit!", footnotes: ["℘ V. 1.2"] },
      { number: 30, text: "Und Balak tat, wie Bileam gesagt hatte; und er opferte einen Stier und einen Widder auf jedem Altar*.", footnotes: ["℘ V. 1.2"] },
    ]},
    { number: 24, verses: [
      { number: 1, text: "Und als Bileam sah, dass es gut war in den Augen des HERRN, Israel zu segnen, ging er nicht wie die anderen Male auf Wahrsagerei aus*, sondern richtete sein Gesicht zur Wüste hin.", heading: "Bileams Segen: Dritter und vierter Spruch", footnotes: ["w. Wahrzeichen entgegen"] },
      { number: 2, text: "Und Bileam erhob seine Augen und sah Israel, gelagert nach seinen Stämmen*; und der Geist Gottes kam über ihn*.", footnotes: ["℘ Kap. 2,2", "℘ Kap. 11,25; 2Chr 15,1"] },
      { number: 3, text: "Und er begann seinen Spruch und sprach: Es spricht Bileam*, der Sohn Beors, und es spricht der Mann* mit geöffnetem* Auge*.", footnotes: ["w. Ausspruch Bileams", "w. Ausspruch des Mannes", "Wortbedeutung unsicher; andere üs. mit Textänderung: mit geschlossenem", "℘ 1Kö 22,17.19"] },
      { number: 4, text: "Es spricht*, der die Worte Gottes hört, der ein Gesicht des Allmächtigen sieht, der niederfällt mit enthüllten Augen*:", footnotes: ["w. Ausspruch dessen", "℘ 1Kö 22,17.19"] },
      { number: 5, text: "Wie schön sind deine Zelte, Jakob, deine Wohnungen, Israel!*", footnotes: ["℘ Ps 84,2"] },
      { number: 6, text: "Wie Täler breiten sie sich aus, wie Gärten am Strom*, wie Aloebäume, die der HERR gepflanzt hat, wie Zedern am Wasser*.", footnotes: ["℘ Ps 1,3", "℘ Ps 104,16"] },
      { number: 7, text: "Wasser rinnt aus seinen Eimern*, und seine Saat steht in reichlichen Wassern; und sein König wird höher werden als Agag*, und sein Königreich wird erhaben sein*.", footnotes: ["℘ Jes 30,25; Joe 4,18", "℘ 1Sam 15,8; Est 3,1", "℘ 2Sam 5,12; 1Kö 5,1; Ps 72,11; Offb 19,16"] },
      { number: 8, text: "Gott hat ihn aus Ägypten herausgeführt. Er hat <Kraft> wie die Hörner des Büffels*. Er wird die Nationen, seine Gegner, fressen und ihre Gebeine zermalmen, mit seinen Pfeilen sie durchbohren*.*", footnotes: ["℘ Kap. 23,22", "w. zerschmettern", "℘ 2Mo 23,22; Ps 45,6"] },
      { number: 9, text: "Er duckt sich, er legt sich nieder wie ein Löwe und wie eine Löwin*. Wer will ihn aufstören*? Die dich segnen, sind gesegnet*, und die dich verfluchen, sind verflucht*!*", footnotes: ["℘ Kap. 23,24", "℘ 1Mo 49,9", "o. sollen gesegnet sein", "o. sollen verflucht sein", "℘ 1Mo 12,3; 5Mo 30,7; Est 6,13"] },
      { number: 10, text: "Da entbrannte der Zorn Balaks gegen Bileam, und er schlug seine Hände zusammen; und Balak sagte zu Bileam: Meine Feinde zu verfluchen, habe ich dich gerufen, und siehe, du hast sie sogar gesegnet, jetzt <bereits> dreimal!*", footnotes: ["℘ Kap. 23,11; 5Mo 23,6; Jos 24,10; Neh 13,2"] },
      { number: 11, text: "Und nun fliehe an deinen Ort! Ich hatte gesagt, ich wolle dich hoch belohnen*, siehe, der HERR hat dir den Lohn* verwehrt*.", footnotes: ["w. ehren", "w. die Ehre", "℘ Kap. 22,37"] },
      { number: 12, text: "Und Bileam sagte zu Balak: Habe ich nicht schon zu deinen Boten, die du zu mir gesandt hast, geredet und gesagt:" },
      { number: 13, text: "Wenn Balak mir sein Haus voller Silber und Gold gäbe, so wäre ich nicht imstande, den Befehl des HERRN zu übertreten, um aus meinem eigenen Herzen <etwas> zu tun, Gutes oder Böses; <nur> was der HERR reden wird, das werde ich reden?*", footnotes: ["℘ Kap. 22,8"] },
      { number: 14, text: "Und nun siehe, ich gehe zu meinem Volk. Komm, ich will dir verkünden, was dieses Volk deinem Volk antun wird am Ende der Tage*.", footnotes: ["℘ 1Mo 49,1; Dan 10,14; Offb 1,1"] },
      { number: 15, text: "Und er begann seinen Spruch und sprach: Es spricht Bileam*, der Sohn Beors, und es spricht der Mann* mit geöffnetem* Auge.", footnotes: ["w. Ausspruch Bileams", "w. Ausspruch des Mannes", "Wortbedeutung unsicher; andere üs. mit Textänderung: mit geschlossenem"] },
      { number: 16, text: "Es spricht*, der die Worte Gottes hört, der die Erkenntnis des Höchsten* besitzt*, der ein Gesicht des Allmächtigen* sieht, der da liegt mit enthüllten Augen:", footnotes: ["w. Ausspruch dessen", "℘ 1Mo 14,18-20", "w. erkennt", "℘ 1Mo 17,1"] },
      { number: 17, text: "Ich sehe ihn, aber nicht jetzt*, ich schaue ihn, aber nicht nahe. Es tritt hervor ein Stern aus Jakob*, und ein Zepter erhebt sich aus Israel und zerschlägt die Schläfen Moabs* und zerschmettert alle Söhne Sets*.", footnotes: ["d. h. als noch nicht gegenwärtig", "℘ Mt 2,2; Offb 22,16", "℘ 2Sam 8,2; Jer 48", "SamPent liest: und die Schädel aller Söhne Sets"] },
      { number: 18, text: "Und Edom wird sein Besitz, und Seïr wird sein Besitz, seine Feinde*; und Israel wird Mächtiges tun.", footnotes: ["℘ 2Sam 8,14; 1Kö 11,14-16; Am 9,12"] },
      { number: 19, text: "Und einer aus Jakob wird herrschen*, und er wird den Rest aus der Stadt verloren gehen lassen.", footnotes: ["Die syr. und aram. Üs. lesen: wird herabsteigen\n℘ 1Mo 49,10"] },
      { number: 20, text: "Und er sah Amalek und begann seinen Spruch und sprach: Die erste der Nationen war Amalek, aber sein Ende <führt> zum Untergang*.", footnotes: ["o. aber sein Ende ist für immer <gekommen>\n℘ 2Mo 17,14; 1Sam 15,3-8"] },
      { number: 21, text: "Und er sah die Keniter und begann seinen Spruch und sprach: Fest ist dein Wohnsitz, und auf den Felsen gesetzt ist dein Nest;" },
      { number: 22, text: "jedoch ist Kain der Verwüstung verfallen. Wie lange noch! Dann führt Assur dich gefangen weg." },
      { number: 23, text: "Und er begann seinen Spruch und sprach: Wehe! Wer wird am Leben bleiben, wenn Gott das eintreten lässt?" },
      { number: 24, text: "Und Schiffe <kommen> von der Küste von Kittim* und demütigen Assur und demütigen Eber, aber auch das <führt> zum Untergang*. —", footnotes: ["d. i. Zypern\n℘ 1Mo 10,4; Dan 11,30", "o. und auch ihn für immer\n℘ Jes 10,5-12"] },
      { number: 25, text: "Und Bileam machte sich auf, ging weg und kehrte an seinen Ort zurück; und auch Balak ging seines Weges." },
    ]},
    { number: 25, verses: [
      { number: 1, text: "Und Israel blieb in Schittim*. Und das Volk fing an Unzucht zu treiben mit den Töchtern Moabs;", heading: "Opfer für den Baal-Peor — Einsatz des Pinhas für Gott", footnotes: ["℘ Kap. 33,49; Jos 2,1; Joe 4,18"] },
      { number: 2, text: "und diese luden das Volk zu den Opfern ihrer Götter* ein, und das Volk aß und warf sich nieder vor ihren Göttern*.*", footnotes: ["o. ihres Gottes", "o. vor ihrem Gott", "℘ 2Mo 23,24; 34,15.16; Mi 6,5"] },
      { number: 3, text: "Und Israel hängte sich an den Baal-Peor*. Da entbrannte der Zorn des HERRN gegen Israel*.", footnotes: ["℘ Kap. 31,16; Ri 2,11.13; Ps 106,28.36; Hos 4,14; 9,10; Offb 2,14.20", "℘ 5Mo 4,3"] },
      { number: 4, text: "Und der HERR sprach zu Mose: Nimm alle Häupter des Volkes und hänge sie dem HERRN auf* vor der Sonne, damit die Glut des Zornes des HERRN sich von Israel abwende*.", footnotes: ["o. setze sie für den HERRN mit gebrochenen Gliedern aus; o. pfähle sie für den HERRN\n℘ 5Mo 21,22; 2Sam 21,9", "℘ 5Mo 13,7-12"] },
      { number: 5, text: "Und Mose sagte zu den Richtern Israels: Erschlagt <sie>, jeder seine Leute, die sich an den Baal-Peor gehängt haben!*", footnotes: ["℘ 2Mo 32,27; Jos 22,17"] },
      { number: 6, text: "Und siehe, ein Mann von den Söhnen Israel kam und brachte eine Midianiterin zu seinen Brüdern vor den Augen Moses und vor den Augen der ganzen Gemeinde der Söhne Israel, als diese am Eingang des Zeltes der Begegnung weinten*.", footnotes: ["℘ Esr 9,1-4"] },
      { number: 7, text: "Und als der Priester Pinhas, der Sohn Eleasars, des Sohnes Aarons*, des Priesters, das sah, stand er aus der Mitte der Gemeinde auf und nahm einen Speer in seine Hand;", footnotes: ["℘ Kap. 31,6; 2Mo 6,25"] },
      { number: 8, text: "und er ging dem israelitischen Mann nach in das Innere <des Zeltes> und durchbohrte die beiden, den israelitischen Mann und die Frau, durch ihren Unterleib. Da wurde die Plage von den Söhnen Israel zurückgehalten*.", footnotes: ["℘ Kap. 17,13; Jos 7,26; 2Sam 21,14; 1Chr 21,22; Ps 106,29.30"] },
      { number: 9, text: "Und die <Zahl der> an der Plage Gestorbenen war 24 000*.", footnotes: ["℘ Kap. 26,1; 2Mo 32,35; 2Sam 24,15; 1Kor 10,8"] },
      { number: 10, text: "Und der HERR redete zu Mose und sprach:" },
      { number: 11, text: "Der Priester Pinhas, der Sohn Eleasars, des Sohnes Aarons, des Priesters, hat meinen Zorn von den Söhnen Israel abgewendet, indem er in meinem Eifer mitten unter ihnen geeifert hat. So habe ich die Söhne Israel in meinem Eifer nicht vernichtet*.", footnotes: ["℘ 2Mo 20,5; 5Mo 4,24; Hebr 12,29"] },
      { number: 12, text: "Darum sprich: Siehe, ich gebe ihm meinen Bund des Friedens*.", footnotes: ["℘ Mal 2,4.5"] },
      { number: 13, text: "Und ihm und seinen Nachkommen nach ihm wird ein Bund ewigen Priestertums zuteil werden*, weil er für seinen Gott geeifert* und für die Söhne Israel Sühnung erwirkt hat*. —", footnotes: ["℘ 2Mo 40,15; Ps 106,31", "℘ 1Kö 19,10", "℘ Kap. 17,12"] },
      { number: 14, text: "Und der Name des getöteten israelitischen Mannes, der mit der Midianiterin getötet wurde, war Simri, Sohn des Salu, der Fürst eines Vaterhauses der Simeoniter;" },
      { number: 15, text: "und der Name der getöteten midianitischen Frau war Kosbi, Tochter des Zur; er war Stammhaupt eines Vaterhauses unter den Midianitern*.", footnotes: ["℘ Kap. 31,8; Jos 13,21"] },
      { number: 16, text: "Und der HERR redete zu Mose und sprach:" },
      { number: 17, text: "Bedrängt die Midianiter und schlagt sie!*", footnotes: ["℘ Kap. 31,2.3; Ri 6,1"] },
      { number: 18, text: "Denn sie haben euch bedrängt durch ihre List, womit sie euch überlistet haben in der Sache des Peor und in der Sache der Kosbi, der Tochter eines Fürsten von Midian, ihrer Schwester, die am Tag der Plage wegen des Peor erschlagen wurde." },
      { number: 19, text: "Und es geschah nach der Plage*,", footnotes: ["℘ Kap. 25,9"] },
    ]},
    { number: 26, verses: [
      { number: 1, text: "da sprach der HERR zu Mose und zu Eleasar, dem Sohn des Aaron, dem Priester*:", heading: "Zählung der Männer wegen Verteilung des Landes Kanaan", footnotes: ["o. des Priesters"] },
      { number: 2, text: "Nehmt die Summe der ganzen Gemeinde der Söhne Israel auf, von zwanzig Jahren an und darüber, nach ihren Vaterhäusern, jeden, der mit dem Heer auszieht in Israel*!", footnotes: ["℘ Kap. 1,2.3"] },
      { number: 3, text: "Und Mose und der Priester Eleasar redeten zu ihnen* in den Ebenen von Moab, am Jordan <bei> Jericho*, und sagten:", footnotes: ["andere mit Textänderung: musterten sie", "℘ V. 63; Kap. 22,1"] },
      { number: 4, text: "Von zwanzig Jahren an und darüber — so wie der HERR dem Mose geboten hatte. Und die Söhne Israel, die aus dem Land Ägypten ausgezogen waren*<, sind folgende>:", footnotes: ["℘ 2Mo 12,51"] },
      { number: 5, text: "*Ruben, der Erstgeborene Israels; die Söhne Rubens*: von Henoch die Sippe der Henochiter; von Pallu die Sippe der Palluïter;", footnotes: ["℘ V. 5-7: 1Chr 5,1-10; V. 5-57: Kap. 1,20-42; 1Mo 35,23-26", "℘ 2Mo 6,14.15"] },
      { number: 6, text: "von Hezron die Sippe der Hezroniter; von Karmi die Sippe der Karmiter." },
      { number: 7, text: "Das sind die Sippen der Rubeniter; und ihre Gemusterten waren 43 730." },
      { number: 8, text: "Und die Söhne Pallus: Eliab." },
      { number: 9, text: "Und die Söhne Eliabs: Nemuël und Datan und Abiram; das sind Datan und Abiram, die Berufenen der Gemeinde, die gegen Mose und gegen Aaron stritten in der Rotte Korach, als sie gegen den HERRN stritten*.", footnotes: ["℘ Kap. 16,1.2"] },
      { number: 10, text: "Und die Erde öffnete ihren Mund und verschlang sie und Korach, als die Rotte starb, indem das Feuer die 250 Männer verzehrte und sie zu einem Zeichen wurden*.", footnotes: ["℘ Kap. 16,31-35; 17,3"] },
      { number: 11, text: "Aber die Söhne des Korach starben nicht*.", footnotes: ["℘ 2Mo 6,24; 1Chr 6,7; 9,19; Ps 42,1"] },
      { number: 12, text: "*Die Söhne Simeon* nach ihren Sippen: von Jemuël die Sippe der Jemuëliter; von Jamin die Sippe der Jaminiter; von Jachin die Sippe der Jachiniter;", footnotes: ["℘ V. 12-14: 1Chr 4,24-43", "℘ 2Mo 6,14.15"] },
      { number: 13, text: "von Serach die Sippe der Serachiter; von Schaul die Sippe der Schauliter." },
      { number: 14, text: "Das sind die Sippen der Simeoniter: 22 200." },
      { number: 15, text: "*Die Söhne Gad nach ihren Sippen: von Zifjon die Sippe der Zifjoniter; von Haggi die Sippe der Haggiter; von Schuni die Sippe der Schuniter;", footnotes: ["℘ V. 15-17: 1Chr 5,11-17"] },
      { number: 16, text: "von Osni die Sippe der Osniter; von Eri die Sippe der Eriter;" },
      { number: 17, text: "von Arod die Sippe der Aroditer; von Areli die Sippe der Areliter." },
      { number: 18, text: "Das sind die Sippen der Söhne Gad nach ihren Gemusterten, 40 500." },
      { number: 19, text: "*Die Söhne Judas: Er und Onan; Er und Onan aber starben im Land Kanaan*.", footnotes: ["℘ V. 19-22: 1Chr 4,1-23", "℘ 1Mo 38,7.10"] },
      { number: 20, text: "Und die Söhne Juda nach ihren Sippen waren: von Schela die Sippe der Schelaniter*; von Perez die Sippe der Pereziter; von Serach die Sippe der Serachiter.", footnotes: ["℘ 1Chr 9,5"] },
      { number: 21, text: "Und die Söhne des Perez waren: von Hezron die Sippe der Hezroniter; von Hamul die Sippe der Hamuliter*.", footnotes: ["℘ 1Mo 46,12"] },
      { number: 22, text: "Das sind die Sippen Judas nach ihren Gemusterten: 76 500." },
      { number: 23, text: "*Die Söhne Issaschar nach ihren Sippen: von Tola die Sippe der Tolaïter; von Puwa die Sippe der Puwaniter;", footnotes: ["℘ V. 23-25: 1Chr 7,1-5"] },
      { number: 24, text: "von Jaschub die Sippe der Jaschubiter; von Schimron die Sippe der Schimroniter." },
      { number: 25, text: "Das sind die Sippen Issaschars nach ihren Gemusterten: 64 300." },
      { number: 26, text: "Die Söhne Sebulon nach ihren Sippen: von Sered die Sippe der Serediter; von Elon die Sippe der Eloniter; von Jachleel die Sippe der Jachleeliter." },
      { number: 27, text: "Das sind die Sippen der Sebuloniter nach ihren Gemusterten: 60 500." },
      { number: 28, text: "*Die Söhne Josef nach ihren Sippen: Manasse und Ephraim*.", footnotes: ["℘ V. 28-37: 1Chr 7,14-29; 5,23.24", "℘ 1Mo 41,51.52"] },
      { number: 29, text: "Die Söhne Manasse: von Machir* die Sippe der Machiriter; und Machir zeugte Gilead*; von Gilead <kommt> die Sippe der Gileaditer.", footnotes: ["℘ Kap. 36,1", "℘ Jos 17,1; 1Chr 2,21"] },
      { number: 30, text: "Das sind die Söhne Gilead: <von> Iëser die Sippe der Iëseriter*; von Helek die Sippe der Helekiter;", footnotes: ["℘ Ri 6,11.34; 8,2"] },
      { number: 31, text: "und <von> Asriël die Sippe der Asriëliter; und <von> Sichem die Sippe der Sichemiter;" },
      { number: 32, text: "und <von> Schemida die Sippe der Schemidaïter; und <von> Hefer die Sippe der Heferiter*. —", footnotes: ["℘ Jos 17,2"] },
      { number: 33, text: "Und Zelofhad, der Sohn Hefers, hatte keine Söhne, sondern <nur> Töchter; und die Namen der Töchter Zelofhads waren: Machla und Noa, Hogla, Milka und Tirza*. —", footnotes: ["℘ Kap. 27,1; 36,11; Jos 17,3"] },
      { number: 34, text: "Das sind die Sippen Manasses: und ihre Gemusterten waren 52 700." },
      { number: 35, text: "Das sind die Söhne Ephraim nach ihren Sippen: von Schutelach die Sippe der Schutelachiter; von Becher die Sippe der Becheriter; von Tahan die Sippe der Tahaniter." },
      { number: 36, text: "Und das sind die Söhne Schutelach: von Eran die Sippe der Eraniter." },
      { number: 37, text: "Das sind die Sippen der Söhne Ephraim nach ihren Gemusterten: 32 500. Das sind die Söhne Josef nach ihren Sippen." },
      { number: 38, text: "*Die Söhne Benjamin nach ihren Sippen: von Bela die Sippe der Belaïter; von Aschbel die Sippe der Aschbeliter; von Ahiram die Sippe der Ahiramiter;", footnotes: ["℘ V. 38-41: 1Chr 7,6-12; 8,1-28"] },
      { number: 39, text: "von Schufam die Sippe der Schufamiter; von Hufam die Sippe der Hufamiter." },
      { number: 40, text: "Und die Söhne Belas waren: Ard und Naaman; <von Ard> die Sippe der Arditer, von Naaman die Sippe der Naamaniter." },
      { number: 41, text: "Das sind die Söhne Benjamin nach ihren Sippen; und ihre Gemusterten waren 45 600." },
      { number: 42, text: "Das sind die Söhne Dan nach ihren Sippen: von Schuham die Sippe der Schuhamiter;" },
      { number: 43, text: "das sind die Sippen Dans nach ihren Sippen. Alle Sippen der Schuhamiter nach ihren Gemusterten: 64 400." },
      { number: 44, text: "*Die Söhne Asser nach ihren Sippen: von Jimna die Sippe der Jimnaiter; von Jischwi die Sippe der Jischwiter; von Beria die Sippe der Beriïter.", footnotes: ["℘ V. 44-47: 1Chr 7,30-40"] },
      { number: 45, text: "Von den Söhnen Berias: von Heber die Sippe der Heberiter; von Malkiël die Sippe der Malkiëliter." },
      { number: 46, text: "Und der Name der Tochter Assers war Serach." },
      { number: 47, text: "Das sind die Sippen der Söhne Asser nach ihren Gemusterten: 53 400." },
      { number: 48, text: "*Die Söhne Naftali nach ihren Sippen: von Jachzeel die Sippe der Jachzeeliter; von Guni die Sippe der Guniter;", footnotes: ["℘ V. 48-50: 1Chr 7,13"] },
      { number: 49, text: "von Jezer die Sippe der Jezeriter; von Schillem die Sippe der Schillemiter." },
      { number: 50, text: "Das sind die Sippen Naftalis nach ihren Sippen; und ihre Gemusterten waren 45 400." },
      { number: 51, text: "Das sind die Gemusterten der Söhne Israel: 601 730*.", footnotes: ["℘ Kap. 1,46"] },
      { number: 52, text: "Und der HERR redete zu Mose und sprach:" },
      { number: 53, text: "An diese soll das Land nach der Zahl der Namen als Erbteil verteilt werden*.", footnotes: ["℘ 1Mo 12,7; Jos 1,6; 11,23"] },
      { number: 54, text: "Dem, der groß ist <an Zahl>, sollst du sein Erbteil groß bemessen, und dem, der klein ist <an Zahl>, sollst du sein Erbteil klein bemessen. Jedem soll entsprechend <der Zahl> seiner Gemusterten sein Erbteil gegeben werden*.", footnotes: ["℘ Kap. 33,54; 35,8; Jos 17,14.17; 19,9"] },
      { number: 55, text: "Jedoch soll das Land durchs Los verteilt werden*; nach den Namen der Stämme ihrer Väter sollen sie erben;", footnotes: ["℘ Kap. 33,54; 34,13; 36,2; Jos 14,2"] },
      { number: 56, text: "nach Maßgabe des Loses soll <jedem Stamm> sein Erbteil ausgeteilt werden *zwischen dem, der groß ist <an Zahl>, und dem, der klein ist <an Zahl>*.", footnotes: ["o. es sei viel oder wenig", "o. es sei viel oder wenig"] },
      { number: 57, text: "*Und das sind die Gemusterten Levis* nach ihren Sippen*: von Gerschon die Sippe der Gerschoniter; von Kehat die Sippe der Kehatiter; von Merari die Sippe der Merariter.", footnotes: ["℘ V. 57-62: Kap. 3,17-39; 1Chr 5,27-6,66", "℘ Kap. 3,15", "℘ 2Mo 6,25"] },
      { number: 58, text: "Das sind die Sippen Levis: die Sippe der Libniter, die Sippe der Hebroniter, die Sippe der Machliter, die Sippe der Muschiter, die Sippe der Korachiter. Und Kehat zeugte Amram." },
      { number: 59, text: "Und der Name der Frau des Amram war Jochebed, eine Tochter Levis, die sie* dem Levi in Ägypten gebar. Und sie gebar dem Amram Aaron und Mose* und ihre Schwester Mirjam*.", footnotes: ["d. h. die Frau Levis", "℘ 2Mo 2,2; 6,20", "℘ Kap. 12,1; 20,1; 2Mo 2,4"] },
      { number: 60, text: "Und dem Aaron wurden geboren Nadab und Abihu, Eleasar und Itamar*.", footnotes: ["℘ 2Mo 6,23"] },
      { number: 61, text: "Und Nadab und Abihu starben, als sie fremdes Feuer vor dem HERRN darbrachten*.", footnotes: ["℘ Kap. 3,4; 3Mo 10,2"] },
      { number: 62, text: "Und ihre Gemusterten, alles Männliche von einem Monat an und darüber, waren 23 000; denn sie wurden nicht unter den Söhnen Israel gemustert*, weil ihnen kein Erbteil unter den Söhnen Israel gegeben wurde*.", footnotes: ["℘ Kap. 1,47.49", "℘ Kap. 18,20.23.24"] },
      { number: 63, text: "Das sind die durch Mose und den Priester Eleasar Gemusterten, die die Söhne Israel in den Ebenen von Moab, am Jordan <bei> Jericho*, musterten.", footnotes: ["℘ V. 3"] },
      { number: 64, text: "Und unter diesen war kein Mann von denen, die von Mose und dem Priester Aaron gemustert worden waren, die die Söhne Israel in der Wüste Sinai gemustert hatten*.", footnotes: ["℘ Kap. 1,2.19"] },
      { number: 65, text: "Denn der HERR hatte von denen gesagt: Sie müssen in der Wüste sterben!* Und kein Mann von ihnen war übrig geblieben* außer Kaleb, dem Sohn des Jefunne, und Josua, dem Sohn des Nun.", footnotes: ["℘ Kap. 14,35; 27,3; Jos 5,4", "℘ Kap. 14,29.30; 5Mo 2,14; Ps 37,9"] },
    ]},
    { number: 27, verses: [
      { number: 1, text: "Und es traten heran die Töchter des Zelofhad, des Sohnes Hefers, des Sohnes Gileads, des Sohnes Machirs, des Sohnes Manasses, von den Sippen Manasses, des Sohnes Josefs*. Und dies waren die Namen seiner Töchter: Machla, Noa und Hogla und Milka und Tirza*.", heading: "Gesetz für Erbtöchter", footnotes: ["℘ Kap. 36,11", "℘ Kap. 26,33"] },
      { number: 2, text: "Und sie traten vor Mose und vor den Priester Eleasar* und vor die Fürsten und die ganze Gemeinde an den Eingang des Zeltes der Begegnung und sagten:", footnotes: ["℘ V. 21; Kap. 9,6; 36,1; 2Mo 18,22"] },
      { number: 3, text: "Unser Vater ist in der Wüste gestorben*; er war aber nicht inmitten der Rotte derer, die sich in der Rotte Korachs gegen den HERRN zusammenrotteten*, sondern er ist in seiner <eigenen> Sünde* gestorben*; aber er hatte keine Söhne.", footnotes: ["℘ Kap. 26,64.65", "℘ Kap. 16,1-3", "d. h. wie alle anderen", "℘ Röm 6,23"] },
      { number: 4, text: "Warum soll der Name unseres Vaters abgeschnitten werden aus der Mitte seiner Sippe, weil er keinen Sohn hat? Gib uns einen Grundbesitz inmitten der Brüder unseres Vaters!" },
      { number: 5, text: "Und Mose brachte ihre Rechtssache vor den HERRN*.", footnotes: ["℘ Kap. 9,8; 3Mo 24,12"] },
      { number: 6, text: "Und der HERR redete zu Mose und sprach:" },
      { number: 7, text: "Die Töchter Zelofhads reden recht*. Du musst ihnen in der Tat einen Erbbesitz inmitten der Brüder ihres Vaters geben*, und du sollst das Erbteil ihres Vaters auf sie übergehen lassen*!", footnotes: ["℘ Kap. 36,5", "℘ Jos 17,4; Hi 42,15", "℘ Kap. 36,1.2"] },
      { number: 8, text: "Und zu den Söhnen Israel sollst du Folgendes reden: Wenn ein Mann stirbt und keinen Sohn hat, dann sollt ihr sein Erbteil auf seine Tochter übergehen lassen." },
      { number: 9, text: "Und wenn er keine Tochter hat, dann sollt ihr sein Erbteil seinen Brüdern geben." },
      { number: 10, text: "Und wenn er keine Brüder hat, dann sollt ihr sein Erbteil den Brüdern seines Vaters geben." },
      { number: 11, text: "Und wenn sein Vater keine Brüder hat, dann sollt ihr sein Erbteil seinem Blutsverwandten geben, der ihm aus seiner Sippe am nächsten steht, damit der es erbe. Und das soll für die Söhne Israel zu einer Rechtsordnung werden, wie der HERR dem Mose geboten hat." },
      { number: 12, text: "Und der HERR sprach zu Mose: Steige auf das Gebirge Abarim* dort und sieh das Land, das ich den Söhnen Israel gegeben habe*!", heading: "Josuas Einsetzung als Nachfolger Moses", footnotes: ["℘ Kap. 33,47; 5Mo 3,27", "℘ 1Mo 17,8"] },
      { number: 13, text: "Und wenn du es gesehen hast, dann wirst auch du zu deinen Völkern* versammelt werden*, wie dein Bruder Aaron versammelt worden ist*,", footnotes: ["d. h. zu deinen Vorfahren", "℘ Kap. 31,2; 5Mo 31,14.16", "℘ Kap. 20,24.28"] },
      { number: 14, text: "weil ihr euch in der Wüste Zin, beim Streit der Gemeinde, meinem Befehl widersetzt habt, mich durch das Wasser vor ihren Augen als heilig zu erweisen* — das ist das Streitwasser von Kadesch in der Wüste Zin —.*", footnotes: ["℘ Kap. 20,12; Apg 7,51", "℘ Kap. 20,1-5"] },
      { number: 15, text: "Und Mose redete zu dem HERRN und sprach:" },
      { number: 16, text: "Der HERR, der Gott des Lebensgeistes* allen Fleisches*, setze einen Mann über die Gemeinde ein,", footnotes: ["Im Hebr. steht die Mehrzahl.", "℘ Kap. 16,22; Offb 22,6"] },
      { number: 17, text: "der vor ihnen her <zum Kampf> auszieht und vor ihnen her <ins Lager> einzieht und der sie ausführt und sie einführt*, damit die Gemeinde des HERRN nicht sei wie Schafe, die keinen Hirten haben*!", footnotes: ["℘ 2Chr 1,10", "℘ 1Kö 22,17; Mt 9,36"] },
      { number: 18, text: "Und der HERR sprach zu Mose: Nimm dir Josua, den Sohn des Nun*, einen Mann, in dem der Geist ist*, und lege deine Hand auf ihn!*", footnotes: ["℘ 2Mo 17,9; 5Mo 31,14", "℘ 1Mo 41,38", "℘ 5Mo 34,9; Apg 6,3.6"] },
      { number: 19, text: "Und stelle ihn vor den Priester Eleasar und vor die ganze Gemeinde*, und beauftrage ihn vor ihren Augen;", footnotes: ["℘ 5Mo 31,7"] },
      { number: 20, text: "und lege von deiner Würde* <einen Teil> auf ihn, damit die ganze Gemeinde der Söhne Israel ihm gehorche*!", footnotes: ["o. von deiner Hoheit", "℘ Jos 1,17"] },
      { number: 21, text: "Und er soll vor den Priester Eleasar treten, und der soll für ihn das Urteil* der Urim vor dem HERRN befragen*. Auf dessen Befehl sollen sie ausziehen, und auf dessen Befehl sollen sie einziehen, er und alle Söhne Israel mit ihm, ja, die ganze Gemeinde*.", footnotes: ["o. die Vorschrift", "℘ 2Mo 28,30; Jos 9,14; Ri 1,1; 1Sam 14,19", "℘ 5Mo 31,3"] },
      { number: 22, text: "Und Mose tat es, wie der HERR ihm geboten hatte, und nahm Josua und stellte ihn vor den Priester Eleasar und vor die ganze Gemeinde." },
      { number: 23, text: "Und er legte seine Hände auf ihn und beauftragte ihn, wie der HERR durch Mose geredet hatte*.", footnotes: ["℘ 5Mo 3,21"] },
    ]},
    { number: 28, verses: [
      { number: 1, text: "Und der HERR redete zu Mose und sprach:", heading: "Tägliche Opfer, Opfer am Sabbat, Neumond, Passah und am Fest der Erstlinge" },
      { number: 2, text: "Befiehl den Söhnen Israel und sprich zu ihnen: Ihr sollt darauf achthaben, mir meine Opfergabe, meine Speise*, in Form der mir <zukommenden> Feueropfer zu ihrer festgesetzten Zeit* darzubringen*, mir zum wohlgefälligen Geruch*!", footnotes: ["w. mein Brot", "℘ Kap. 29,39; 1Chr 23,31; Esr 3,2; Neh 10,34; Hes 45,17", "℘ 3Mo 3,11; 21,6; 2Chr 23,18; 31,3", "o. Geruch der Befriedigung o. Beschwichtigung"] },
      { number: 3, text: "Und sage zu ihnen: Das ist das Feueropfer, das ihr dem HERRN darbringen sollt: zwei einjährige Lämmer ohne Fehler, täglich als regelmäßiges Brandopfer*.", footnotes: ["℘ 2Mo 29,38-42; Dan 8,11; Am 4,4"] },
      { number: 4, text: "Das eine Lamm sollst du am Morgen bereiten, und das zweite Lamm sollst du zwischen den zwei Abenden* bereiten;", footnotes: ["d. h. entweder zwischen Sonnenuntergang und völliger Nacht oder zwischen Niedergang (15 Uhr) und Untergang der Sonne"] },
      { number: 5, text: "und zum Speisopfer ein zehntel Efa Weizengrieß, gemengt* mit einem viertel Hin gestoßenen Öles*", footnotes: ["o. angefeuchtet", "℘ Kap. 15,4; 3Mo 2,1"] },
      { number: 6, text: "— ein regelmäßiges Brandopfer, das am Berge Sinai eingesetzt wurde*, zum wohlgefälligen Geruch*, ein Feueropfer für den HERRN —;", footnotes: ["℘ 3Mo 27,34", "o. Geruch der Befriedigung o. Beschwichtigung"] },
      { number: 7, text: "und das dazugehörige Trankopfer, ein viertel Hin für je ein Lamm*; im Heiligtum sollst du als Trankopfer Rauschtrank für den HERRN spenden*.", footnotes: ["℘ Kap. 15,5; Joe 1,13", "℘ 3Mo 1,9"] },
      { number: 8, text: "Und das zweite Lamm sollst du zwischen den zwei Abenden* bereiten; wie das Morgen-Speisopfer und das dazugehörige Trankopfer sollst du es bereiten, ein Feueropfer von wohlgefälligem Geruch für den HERRN.", footnotes: ["s. Anm. zu V. 4"] },
      { number: 9, text: "Und am Sabbattag* zwei einjährige Lämmer ohne Fehler und als Speisopfer zwei Zehntel Weizengrieß, gemengt* mit Öl, und das dazugehörige Trankopfer.", footnotes: ["℘ Mt 12,5", "o. angefeuchtet"] },
      { number: 10, text: "<Es ist> das Brandopfer des Sabbats an jedem Sabbat*, <zusätzlich> zum regelmäßigen Brandopfer und dem dazugehörigen Trankopfer.", footnotes: ["℘ Jes 1,13; Hes 46,4"] },
      { number: 11, text: "Und am Anfang eurer Monate* sollt ihr dem HERRN ein Brandopfer darbringen: zwei Jungstiere und einen Widder, sieben einjährige Lämmer ohne Fehler*;", footnotes: ["℘ 2Kö 4,23; 2Chr 2,3; Esr 3,5; Ps 81,4; Hes 46,6", "℘ 3Mo 1,3.10"] },
      { number: 12, text: "und zu jedem Stier drei Zehntel Weizengrieß, gemengt* mit Öl, als Speisopfer; und zu dem einen Widder zwei Zehntel Weizengrieß, gemengt* mit Öl, als Speisopfer;", footnotes: ["o. angefeuchtet", "o. angefeuchtet"] },
      { number: 13, text: "und zu jedem Lamm je ein Zehntel Weizengrieß, gemengt* mit Öl*, als Speisopfer. <Es ist> ein Brandopfer, ein wohlgefälliger Geruch*, ein Feueropfer für den HERRN.", footnotes: ["o. angefeuchtet", "℘ Kap. 15,6-12", "o. Geruch der Befriedigung o. Beschwichtigung"] },
      { number: 14, text: "Und die dazugehörigen Trankopfer: ein halbes Hin Wein soll zum Stier gehören und ein drittel Hin zum Widder und ein viertel Hin zum Lamm*. Das ist das Brandopfer zum Neumond in jedem Monat nach den Monaten des Jahres*.", footnotes: ["℘ Jes 1,13; Hes 46,4", "℘ Jes 1,13; Hes 46,4"] },
      { number: 15, text: "Und ein Ziegenbock* zum Sündopfer für den HERRN soll <zusätzlich> zum regelmäßigen Brandopfer und dem dazugehörigen Trankopfer bereitet werden*.", footnotes: ["w. Haariger der Ziegen", "℘ V. 30; Kap. 29,5; 3Mo 16,15.16"] },
      { number: 16, text: "Und im ersten Monat, am vierzehnten Tag des Monats, ist Passah für den HERRN*.", footnotes: ["℘ 2Mo 12,6.11.21; Lk 22,15; Joh 2,13; 6,4; 13,1"] },
      { number: 17, text: "Und am fünfzehnten Tag dieses Monats ist ein Fest; sieben Tage sollen ungesäuerte Brote gegessen werden*.", footnotes: ["℘ 2Mo 12,15"] },
      { number: 18, text: "Am ersten Tag soll eine heilige Versammlung sein; keinerlei Dienstarbeit sollt ihr tun*.", footnotes: ["℘ 2Mo 12,16; 3Mo 23,8"] },
      { number: 19, text: "Und ihr sollt ein Feueropfer darbringen, ein Brandopfer für den HERRN: zwei Jungstiere und einen Widder und sieben einjährige Lämmer*; ohne Fehler sollen sie euch sein*;", footnotes: ["℘ 5Mo 16,2", "℘ 3Mo 1,3.10; 2Chr 35,12"] },
      { number: 20, text: "und das dazugehörige Speisopfer, Weizengrieß, gemengt* mit Öl: drei Zehntel sollt ihr opfern zum Stier und zwei Zehntel zum Widder;", footnotes: ["o. angefeuchtet"] },
      { number: 21, text: "je ein Zehntel sollst du bereiten zu jedem Lamm von den sieben Lämmern;" },
      { number: 22, text: "und einen Ziegenbock* als Sündopfer, um Sühnung für euch zu erwirken.", footnotes: ["w. Haarigen"] },
      { number: 23, text: "Außer dem Morgenbrandopfer, das zum regelmäßigen Brandopfer gehört, sollt ihr das bereiten." },
      { number: 24, text: "Solche <Opfer> sollt ihr sieben Tage lang täglich bereiten als Speise*, als Feueropfer von wohlgefälligem Geruch* für den HERRN*; <zusätzlich> zum regelmäßigen Brandopfer und dem dazugehörigen Trankopfer soll es bereitet werden.", footnotes: ["w. Brot", "o. Geruch der Befriedigung o. Beschwichtigung", "℘ Hes 45,23"] },
      { number: 25, text: "Und am siebten Tag sollt ihr eine heilige Versammlung halten; keinerlei Dienstarbeit sollt ihr tun." },
      { number: 26, text: "Und am Tag der Erstlinge*, wenn ihr dem HERRN ein neues Speisopfer darbringt, an eurem Wochenfest*, sollt ihr eine heilige Versammlung halten; keinerlei Dienstarbeit sollt ihr tun*.", footnotes: ["℘ 2Mo 23,16", "℘ 3Mo 23,15-22; 5Mo 16,9-12", "℘ 2Mo 12,16; 3Mo 23,8"] },
      { number: 27, text: "Und ihr sollt ein Brandopfer darbringen zum wohlgefälligen Geruch* für den HERRN: zwei Jungstiere, einen Widder, sieben einjährige Lämmer;", footnotes: ["o. Geruch der Befriedigung o. Beschwichtigung"] },
      { number: 28, text: "und das dazugehörige Speisopfer, Weizengrieß, gemengt* mit Öl: drei Zehntel zu jedem Stier, zwei Zehntel zu jedem Widder,", footnotes: ["o. angefeuchtet"] },
      { number: 29, text: "je ein Zehntel zu jedem Lamm von den sieben Lämmern;" },
      { number: 30, text: "<und> einen Ziegenbock*, um Sühnung für euch zu erwirken*.", footnotes: ["w. Haarigen der Ziegen", "℘ V. 15"] },
      { number: 31, text: "Außer dem regelmäßigen Brandopfer und dem dazugehörigen Speisopfer sollt ihr sie bereiten — ohne Fehler sollen sie euch sein* — mit den dazugehörigen Trankopfern.", footnotes: ["℘ 3Mo 1,3.10; 2Chr 35,12"] },
    ]},
    { number: 29, verses: [
      { number: 1, text: "*Und im siebten Monat, am Ersten des Monats*, sollt ihr eine heilige Versammlung halten; keinerlei Dienstarbeit sollt ihr tun*; ein Tag des <Horn>blasens soll es für euch sein.", heading: "Opfer am Fest des Hornblasens, am Versöhnungstag und am Laubhüttenfest", footnotes: ["℘ V. 1-6: 3Mo 23,23-25", "℘ Neh 8,2", "℘ V. 35; 3Mo 23,7"] },
      { number: 2, text: "Und ihr sollt ein Brandopfer bereiten* zum wohlgefälligen Geruch* für den HERRN: einen Jungstier, einen Widder, sieben einjährige Lämmer, ohne Fehler*;", footnotes: ["℘ Esr 3,6", "o. Geruch der Befriedigung o. Beschwichtigung", "℘ 3Mo 1,3.10"] },
      { number: 3, text: "und das dazugehörige Speisopfer, Weizengrieß, gemengt* mit Öl; drei Zehntel zum Stier, zwei Zehntel zum Widder", footnotes: ["o. angefeuchtet"] },
      { number: 4, text: "und ein Zehntel zu jedem Lamm von den sieben Lämmern;" },
      { number: 5, text: "und einen Ziegenbock* als Sündopfer, um Sühnung für euch zu erwirken*;", footnotes: ["w. Haarigen der Ziegen", "℘ Kap. 28,15"] },
      { number: 6, text: "außer dem Brandopfer zum Neumond und dem dazugehörigen Speisopfer und dem regelmäßigen Brandopfer und dem dazugehörigen Speisopfer und den dazugehörigen Trankopfern, nach ihrer Vorschrift*, zum wohlgefälligen Geruch*, ein Feueropfer für den HERRN.", footnotes: ["℘ Kap. 15,4-12", "o. Geruch der Befriedigung o. Beschwichtigung"] },
      { number: 7, text: "*Und am Zehnten dieses siebten Monats sollt ihr eine heilige Versammlung halten, und ihr sollt euch* demütigen; keinerlei Arbeit sollt ihr tun.", footnotes: ["℘ V. 7-11: 3Mo 16,29-32; 23,26-32", "w. eure Seelen"] },
      { number: 8, text: "Und ihr sollt dem HERRN ein Brandopfer darbringen als einen wohlgefälligen Geruch*: einen Jungstier, einen Widder, sieben einjährige Lämmer; ohne Fehler sollen sie euch sein*;", footnotes: ["o. Geruch der Befriedigung o. Beschwichtigung", "℘ 3Mo 1,3.10"] },
      { number: 9, text: "und das dazugehörige Speisopfer, Weizengrieß, gemengt* mit Öl: drei Zehntel zum Stier, zwei Zehntel zu jedem Widder,", footnotes: ["o. angefeuchtet"] },
      { number: 10, text: "je ein Zehntel zu jedem Lamm von den sieben Lämmern;" },
      { number: 11, text: "<und> einen Ziegenbock* als Sündopfer; außer dem Sündopfer der Versöhnung und dem regelmäßigen Brandopfer und dem dazugehörigen Speisopfer und den dazugehörigen Trankopfern.", footnotes: ["w. Haarigen der Ziegen"] },
      { number: 12, text: "*Und am fünfzehnten Tag des siebten Monats sollt ihr eine heilige Versammlung halten; keinerlei Dienstarbeit sollt ihr tun*, und ihr sollt dem HERRN ein Fest sieben Tage lang feiern.", footnotes: ["℘ V. 12-38: 3Mo 23,33-43", "℘ V. 35; 3Mo 23,7"] },
      { number: 13, text: "Und ihr sollt ein Brandopfer darbringen, ein Feueropfer von wohlgefälligem Geruch* für den HERRN: dreizehn Jungstiere, zwei Widder, vierzehn einjährige Lämmer; ohne Fehler sollen sie sein*;", footnotes: ["o. Geruch der Befriedigung o. Beschwichtigung", "℘ 3Mo 1,3.10"] },
      { number: 14, text: "und das dazugehörige Speisopfer, Weizengrieß, gemengt* mit Öl: drei Zehntel zu jedem Stier von den dreizehn Stieren, zwei Zehntel zu jedem Widder von den zwei Widdern", footnotes: ["o. angefeuchtet"] },
      { number: 15, text: "und je ein Zehntel zu jedem Lamm von den vierzehn Lämmern;" },
      { number: 16, text: "und einen Ziegenbock* als Sündopfer; außer dem regelmäßigen Brandopfer, dem dazugehörigen Speisopfer und dem dazugehörigen Trankopfer*.", footnotes: ["w. Haarigen der Ziegen", "℘ Kap. 28,15"] },
      { number: 17, text: "Und am zweiten Tag zwölf Jungstiere, zwei Widder, vierzehn einjährige Lämmer, ohne Fehler;" },
      { number: 18, text: "und das dazugehörige Speisopfer und die dazugehörigen Trankopfer, zu den Stieren, zu den Widdern und zu den Lämmern, nach ihrer Zahl, nach der Vorschrift;" },
      { number: 19, text: "und einen Ziegenbock* als Sündopfer; außer dem regelmäßigen Brandopfer und dem dazugehörigen Speisopfer und den dazugehörigen Trankopfern.", footnotes: ["w. Haarigen der Ziegen"] },
      { number: 20, text: "Und am dritten Tag elf Stiere, zwei Widder, vierzehn einjährige Lämmer, ohne Fehler;" },
      { number: 21, text: "und das dazugehörige Speisopfer und die dazugehörigen Trankopfer, zu den Stieren, zu den Widdern und zu den Lämmern, nach ihrer Zahl, nach der Vorschrift;" },
      { number: 22, text: "und einen Ziegenbock* als Sündopfer; außer dem regelmäßigen Brandopfer und dem dazugehörigen Speisopfer und dem dazugehörigen Trankopfer.", footnotes: ["w. Haarigen"] },
      { number: 23, text: "Und am vierten Tag zehn Stiere, zwei Widder, vierzehn einjährige Lämmer, ohne Fehler;" },
      { number: 24, text: "das dazugehörige Speisopfer und die dazugehörigen Trankopfer, zu den Stieren, zu den Widdern und zu den Lämmern, nach ihrer Zahl, nach der Vorschrift;" },
      { number: 25, text: "und einen Ziegenbock* als Sündopfer; außer dem regelmäßigen Brandopfer, dem dazugehörigen Speisopfer und dem dazugehörigen Trankopfer.", footnotes: ["w. Haarigen der Ziegen"] },
      { number: 26, text: "Und am fünften Tag neun Stiere, zwei Widder, vierzehn einjährige Lämmer, ohne Fehler;" },
      { number: 27, text: "und das dazugehörige Speisopfer und die dazugehörigen Trankopfer, zu den Stieren, zu den Widdern und zu den Lämmern, nach ihrer Zahl, nach der Vorschrift;" },
      { number: 28, text: "und einen Ziegenbock* als Sündopfer; außer dem regelmäßigen Brandopfer und dem dazugehörigen Speisopfer und dem dazugehörigen Trankopfer.", footnotes: ["w. Haarigen"] },
      { number: 29, text: "Und am sechsten Tag acht Stiere, zwei Widder, vierzehn einjährige Lämmer, ohne Fehler;" },
      { number: 30, text: "und das dazugehörige Speisopfer und die dazugehörigen Trankopfer, zu den Stieren, zu den Widdern und zu den Lämmern, nach ihrer Zahl, nach der Vorschrift;" },
      { number: 31, text: "und einen Ziegenbock* als Sündopfer; außer dem regelmäßigen Brandopfer, dem dazugehörigen Speisopfer und den dazugehörigen Trankopfern.", footnotes: ["w. Haarigen"] },
      { number: 32, text: "Und am siebten Tag sieben Stiere, zwei Widder, vierzehn einjährige Lämmer, ohne Fehler;" },
      { number: 33, text: "und das dazugehörige Speisopfer und die dazugehörigen Trankopfer zu den Stieren, zu den Widdern und zu den Lämmern, nach ihrer Zahl, nach ihrer Vorschrift;" },
      { number: 34, text: "und einen Ziegenbock* als Sündopfer; außer dem regelmäßigen Brandopfer, dem dazugehörigen Speisopfer und dem dazugehörigen Trankopfer.", footnotes: ["w. Haarigen"] },
      { number: 35, text: "Am achten Tag sollt ihr eine Festversammlung halten*; keinerlei Dienstarbeit sollt ihr tun*.", footnotes: ["℘ Joh 7,37", "℘ V. 1.12"] },
      { number: 36, text: "Und ihr sollt ein Brandopfer darbringen, ein Feueropfer von wohlgefälligem Geruch* für den HERRN: einen Stier, einen Widder, sieben einjährige Lämmer, ohne Fehler;", footnotes: ["o. Geruch der Befriedigung o. Beschwichtigung"] },
      { number: 37, text: "das dazugehörige Speisopfer und die dazugehörigen Trankopfer, zu dem Stier, zu dem Widder und zu den Lämmern, nach ihrer Zahl, nach der Vorschrift;" },
      { number: 38, text: "und einen Ziegenbock* als Sündopfer; außer dem regelmäßigen Brandopfer und dem dazugehörigen Speisopfer und dem dazugehörigen Trankopfer.", footnotes: ["w. Haarigen"] },
      { number: 39, text: "Das sollt ihr bei euren Festtagen* dem HERRN opfern*, außer euren Gelübden und euren freiwilligen Gaben an Brandopfern und an Speisopfern* und an Trankopfern und an Heilsopfern*.", footnotes: ["o. Festzeiten", "℘ Kap. 28,2.3; Esr 3,4.5", "w. an euren Brandopfern und an euren Speisopfern", "o. Friedensopfern; o. Abschlussopfern; o. Gemeinschaftsopfern\n℘ 3Mo 23,38"] },
    ]},
    { number: 30, verses: [
      { number: 1, text: "Und Mose sprach zu den Söhnen Israel nach allem, was der HERR dem Mose geboten hatte*.", heading: "Verordnungen über Gelübde", footnotes: ["℘ 2Mo 4,28"] },
      { number: 2, text: "Und Mose redete zu den Häuptern der Stämme der Söhne Israel und sagte: Das ist es, was der HERR geboten hat:" },
      { number: 3, text: "Wenn ein Mann dem HERRN ein Gelübde ablegt* oder einen Eid schwört, ein Enthaltungsgelübde auf seine Seele zu nehmen, dann soll er sein Wort nicht brechen; nach allem, was aus seinem Mund hervorgegangen ist, soll er tun*.", footnotes: ["℘ Kap. 6,2; 3Mo 27,2", "℘ Jos 9,18; Ri 11,35; 2Chr 36,13; Ps 50,14; Mt 5,33; 14,9"] },
      { number: 4, text: "Und wenn eine Frau dem HERRN ein Gelübde ablegt oder ein Enthaltungsgelübde auf sich nimmt im Haus ihres Vaters, in ihrer Jugend," },
      { number: 5, text: "und ihr Vater hört ihr Gelübde oder ihr Enthaltungsgelübde, das sie auf ihre Seele genommen hat, und ihr Vater schweigt ihr gegenüber, dann sollen alle ihre Gelübde gelten, und jedes Enthaltungsgelübde, das sie auf ihre Seele genommen hat, soll gelten." },
      { number: 6, text: "Wenn aber ihr Vater ihr gewehrt hat an dem Tag, als er es hörte, so sollen alle ihre Gelübde und alle ihre Enthaltungsgelübde, die sie auf ihre Seele genommen hat, nicht gelten; und der HERR wird ihr vergeben, weil ihr Vater ihr gewehrt hat." },
      { number: 7, text: "Und wenn sie etwa <die Frau> eines Mannes wird und ihre Gelübde auf ihr sind* oder ein unbedachter Ausspruch ihrer Lippen, mit dem sie ihre Seele gebunden hat,", footnotes: ["℘ 1Sam 1,11"] },
      { number: 8, text: "und ihr Mann hört es und schweigt ihr gegenüber an dem Tag, da er es hört; dann sollen ihre Gelübde gelten, und ihre Enthaltungsgelübde, die sie auf ihre Seele genommen hat, sollen gelten*.", footnotes: ["℘ 1Sam 1,23; Jer 44,19"] },
      { number: 9, text: "Wenn aber ihr Mann an dem Tag, da er es hört, ihr wehrt, dann hebt er ihr Gelübde auf, das auf ihr ist, und den unbedachten Ausspruch ihrer Lippen, wozu sie ihre Seele gebunden hat; und der HERR wird ihr vergeben." },
      { number: 10, text: "Aber das Gelübde einer Witwe und einer Verstoßenen, alles, womit sie ihre Seele gebunden hat, soll für sie gelten." },
      { number: 11, text: "Und wenn eine Frau im Haus ihres Mannes ein Gelübde abgelegt oder durch einen Eid ein Enthaltungsgelübde auf ihre Seele genommen hat," },
      { number: 12, text: "und ihr Mann hat es gehört und ihr gegenüber geschwiegen, er hat ihr nicht gewehrt; dann sollen alle ihre Gelübde gelten, und jedes Enthaltungsgelübde, das sie auf ihre Seele genommen hat, soll gelten*.", footnotes: ["℘ 1Sam 1,23; Jer 44,19"] },
      { number: 13, text: "Wenn aber ihr Mann diese <Gelübde> ausdrücklich aufgehoben hat an dem Tag, als er sie hörte, dann soll alles, was über ihre Lippen gegangen ist an Gelübden* und an Enthaltungsgelübden ihrer Seele, nicht gelten; ihr Mann hat sie aufgehoben, und der HERR wird ihr vergeben.", footnotes: ["w. an ihren Gelübden"] },
      { number: 14, text: "Jedes Gelübde und jeder Eid eines Enthaltungsgelübdes, sich selbst* zu demütigen; ihr Mann kann es bestätigen, und ihr Mann kann es aufheben.", footnotes: ["w. die Seele"] },
      { number: 15, text: "Und wenn ihr Mann von Tag zu Tag ihr gegenüber völlig schweigt, dann bestätigt er alle ihre Gelübde oder alle ihre Enthaltungsgelübde, die auf ihr sind; er hat sie bestätigt, denn er hat ihr gegenüber geschwiegen an dem Tag, als er davon hörte." },
      { number: 16, text: "Wenn er sie aber ausdrücklich aufhebt, nachdem er davon gehört hat, dann wird er ihre Schuld tragen." },
      { number: 17, text: "Das sind die Ordnungen, die der HERR dem Mose geboten hat, zwischen einem Mann und seiner Frau, zwischen einem Vater und seiner Tochter in ihrer Jugend im Haus ihres Vaters." },
    ]},
    { number: 31, verses: [
      { number: 1, text: "Und der HERR redete zu Mose und sprach:", heading: "Bestrafung der Midianiter" },
      { number: 2, text: "Nimm Rache für die Söhne Israel an den Midianitern*! Danach sollst du zu deinen Völkern* versammelt werden*.", footnotes: ["℘ Kap. 25,17.18", "d. h. zu deinen Vorfahren", "℘ Kap. 27,13"] },
      { number: 3, text: "Und Mose redete zum Volk: Rüstet von euch Männer zum Heer<esdienst> aus*, dass sie gegen Midian ziehen, um die Rache des HERRN an Midian auszuführen!", footnotes: ["℘ 2Mo 17,9"] },
      { number: 4, text: "Je tausend von <jedem> Stamm, von allen Stämmen Israels, sollt ihr zum Heer<esdienst> aussenden." },
      { number: 5, text: "Und es wurden von den Tausendschaften Israels tausend von jedem Stamm ausgehoben: zwölftausend zum Heer<esdienst> Gerüstete." },
      { number: 6, text: "Und Mose sandte sie, tausend von jedem Stamm, zum Heer<esdienst> aus, sie und Pinhas, den Sohn des Priesters Eleasar*, zum Heer<esdienst>; und die heiligen Geräte, die Trompeten zum Lärmblasen*, <waren> in seiner Hand.", footnotes: ["℘ Kap. 25,7; 5Mo 20,2", "℘ Kap. 10,9"] },
      { number: 7, text: "Und sie kämpften gegen Midian, so wie der HERR dem Mose geboten hatte, und brachten alles Männliche um*.", footnotes: ["℘ 5Mo 20,13"] },
      { number: 8, text: "Und sie brachten die Könige von Midian um, <zusätzlich> zu den von ihnen Erschlagenen: Ewi und Rekem und Zur* und Hur und Reba, fünf Könige von Midian; und auch Bileam, den Sohn Beors*, brachten sie mit dem Schwert um*.", footnotes: ["℘ Kap. 25,15", "℘ Kap. 22,5", "℘ Kap. 23,10; Jos 13,21.22; Spr 11,3; 13,17"] },
      { number: 9, text: "Und die Söhne Israel führten die Frauen der Midianiter und ihre Kinder gefangen weg und erbeuteten all ihr Vieh und alle ihre Herden und all ihren Reichtum*;", footnotes: ["℘ V. 53; 5Mo 20,14"] },
      { number: 10, text: "und alle ihre Städte an ihren Wohnsitzen und alle ihre Zeltdörfer verbrannten sie mit Feuer*.", footnotes: ["℘ Jos 6,24"] },
      { number: 11, text: "Und sie nahmen alle Beute und alles Geraubte an Menschen und an Vieh*", footnotes: ["℘ 1Mo 34,29"] },
      { number: 12, text: "und brachten die Gefangenen und das Geraubte und die Beute zu Mose und zu dem Priester Eleasar und zu der Gemeinde der Söhne Israel ins Lager, in die Ebenen von Moab, die am Jordan von Jericho sind*.", footnotes: ["℘ Kap. 22,1"] },
      { number: 13, text: "Und Mose und der Priester Eleasar und alle Fürsten der Gemeinde gingen ihnen entgegen außerhalb des Lagers." },
      { number: 14, text: "Und Mose wurde zornig über die Befehlshaber des Heeres, die Obersten über die Tausendschaften und die Obersten über die Hundertschaften, die von dem Kriegszug kamen;" },
      { number: 15, text: "und Mose sagte zu ihnen: Habt ihr alle Frauen* am Leben gelassen?", footnotes: ["w. alles Weibliche"] },
      { number: 16, text: "Siehe, sie sind ja auf den Rat* Bileams den Söhnen Israel ein Anlass geworden, in der Sache mit dem Peor eine Untreue gegen den HERRN zu begehen*, so dass die Plage über die Gemeinde des HERRN kam*.", footnotes: ["w. auf das Wort", "℘ Offb 2,14", "℘ Kap. 25,1-5"] },
      { number: 17, text: "So bringt nun alles Männliche unter den Kindern um*, und bringt alle Frauen um, die einen Mann im Beischlaf erkannt haben*!", footnotes: ["℘ 5Mo 20,13", "℘ Ri 21,11"] },
      { number: 18, text: "Aber alle Kinder, alle Mädchen*, die den Beischlaf eines Mannes nicht gekannt haben, lasst für euch am Leben!", footnotes: ["w. Aber alle Kinder unter den Frauen"] },
      { number: 19, text: "Ihr aber lagert sieben Tage außerhalb des Lagers! Jeder, der einen Menschen* umgebracht, und jeder, der einen Erschlagenen berührt hat. Ihr sollt euch entsündigen am dritten Tag und am siebten Tag*, ihr und eure Gefangenen.", footnotes: ["w. eine Seele", "℘ Kap. 19,11.12"] },
      { number: 20, text: "Und alle Kleider und alles Zeug aus Leder und alle Arbeit aus Ziegenhaar und alles Gerät aus Holz sollt ihr entsündigen." },
      { number: 21, text: "Und der Priester Eleasar sprach zu den Kriegsleuten, die in den Kampf gezogen waren: Das ist die Ordnung des Gesetzes, das der HERR dem Mose geboten hat:" },
      { number: 22, text: "Nur das Gold und das Silber, die Bronze, das Eisen, das Zinn und das Blei," },
      { number: 23, text: "alles was Feuer verträgt, sollt ihr durchs Feuer gehen lassen, und es wird rein sein; jedoch soll es mit dem Wasser der Reinigung* entsündigt werden; und alles, was Feuer nicht verträgt, sollt ihr durchs Wasser gehen lassen*.", footnotes: ["w. Wasser der Absonderung (durch das man die kultische Reinheit wiedererlangte)", "℘ Kap. 19,9.17.18"] },
      { number: 24, text: "Und am siebten Tag sollt ihr eure Kleider waschen, und ihr werdet rein sein; und danach könnt ihr <wieder> ins Lager kommen*.", footnotes: ["℘ Kap. 19,19"] },
      { number: 25, text: "Und der HERR redete zu Mose und sprach:" },
      { number: 26, text: "Nimm die Summe der weggeführten Beute auf, an Menschen und an Vieh, du und der Priester Eleasar und die Familienoberhäupter* der Gemeinde!", footnotes: ["w. die Häupter der Väter"] },
      { number: 27, text: "Und teile die Beute je zur Hälfte zwischen denen, die den Krieg geführt haben, die ins Feld gezogen sind, und der ganzen Gemeinde*!", footnotes: ["℘ Jos 22,8; 1Sam 30,24; Ps 68,13"] },
      { number: 28, text: "Und erhebe von den Kriegsleuten, die ins Feld gezogen sind, eine Abgabe für den HERRN*: je eine Seele von fünfhundert, von den Menschen und von den Rindern und von den Eseln und von den Schafen.", footnotes: ["℘ 2Chr 15,11"] },
      { number: 29, text: "Von ihrer Hälfte sollt ihr sie nehmen, und du sollst sie dem Priester Eleasar geben als eine Opfergabe für den HERRN*.", footnotes: ["℘ Kap. 18,28"] },
      { number: 30, text: "Und von der Hälfte der Söhne Israel sollst du je eins nehmen, von fünfzig herausgegriffen, von den Menschen, von den Rindern, von den Eseln und von den Schafen, von allem Vieh; und du sollst es den Leviten geben, die den Dienst an der Wohnung des HERRN versehen*.", footnotes: ["℘ Kap. 1,53; Jos 9,27"] },
      { number: 31, text: "Und Mose und der Priester Eleasar taten, wie der HERR dem Mose geboten hatte*.", footnotes: ["℘ 2Mo 12,28"] },
      { number: 32, text: "Und das Erbeutete, der Rest von der Beute, die das Kriegsvolk gemacht hatte, war: 675 000 Schafe" },
      { number: 33, text: "und 72 000 Rinder" },
      { number: 34, text: "und 61 000 Esel;" },
      { number: 35, text: "Menschen aber* — an Frauen, die den Beischlaf eines Mannes <noch> nicht gekannt hatten — insgesamt 32 000 Seelen.", footnotes: ["w. und <die> Menschenseelen"] },
      { number: 36, text: "Die Hälfte, der Anteil derer, die zum Heer<esdienst> ausgezogen waren, die Zahl der Schafe war also: 337 500 Stück" },
      { number: 37, text: "und die Abgabe von den Schafen für den HERRN war 675 <Stück>," },
      { number: 38, text: "und <die Zahl> der Rinder 36 000 und die Abgabe davon für den HERRN 72," },
      { number: 39, text: "und <die Zahl> der Esel 30 500 und die Abgabe davon für den HERRN 61," },
      { number: 40, text: "und die <Zahl der> Menschen* <war> 16 000 und die Abgabe davon für den HERRN 32 Seelen.", footnotes: ["w. und <die> Menschenseelen"] },
      { number: 41, text: "Und Mose übergab die Abgabe als Opfergabe für den HERRN dem Priester Eleasar, wie der HERR dem Mose geboten hatte*.", footnotes: ["℘ 2Mo 12,28"] },
      { number: 42, text: "Und von der Hälfte der Söhne Israel, die Mose von den zum Heer<esdienst> ausgezogenen Männern abgeteilt hatte" },
      { number: 43, text: "— die für die Gemeinde <bestimmte> Hälfte war nämlich: 337 500 <Stück> Schafe" },
      { number: 44, text: "und 36 000 Rinder" },
      { number: 45, text: "und 30 500 Esel" },
      { number: 46, text: "und 16 000 Menschen* —,", footnotes: ["w. Menschenseelen"] },
      { number: 47, text: "und von der den Söhnen Israel <gehörenden> Hälfte nahm Mose das Herausgegriffene, je eins von fünfzig, von den Menschen und von dem Vieh, und übergab sie den Leviten — die den Dienst an der Wohnung des HERRN versahen* —, wie der HERR dem Mose geboten hatte*.", footnotes: ["℘ 2Mo 12,28", "℘ 2Mo 12,28"] },
      { number: 48, text: "Und es traten zu Mose die Befehlshaber über die Tausendschaften des Heeres, die Obersten über die Tausendschaften und die Obersten über die Hundertschaften," },
      { number: 49, text: "und sagten zu Mose: Deine Knechte haben die Summe der Kriegsleute aufgenommen, die unter unserem Befehl waren, und es fehlt von uns nicht ein Mann*.", footnotes: ["℘ 1Sam 30,18.19"] },
      { number: 50, text: "Und so bringen wir eine Opfergabe für den HERRN dar — jeder, was er gefunden hat an goldenem Schmuck: Armspangen und Handspangen, Siegelringe, Ohrringe und Spangen —, um für unsere Seelen Sühnung zu erwirken vor dem HERRN*.", footnotes: ["℘ 2Mo 30,12"] },
      { number: 51, text: "Und Mose und der Priester Eleasar nahmen das Gold von ihnen, allerlei kunstvoll gearbeitete Gegenstände*.", footnotes: ["w. allerlei Gerät <kunstvoller> Arbeit"] },
      { number: 52, text: "Und alles Gold der Opfergabe, das sie für den HERRN abhoben, war 16 750 Schekel von den Obersten über die Tausendschaften und von den Obersten über die Hundertschaften" },
      { number: 53, text: "— die Kriegsleute <aber> hatten jeder <auch noch> für sich geplündert*. —", footnotes: ["℘ V. 9; 2Chr 20,25"] },
      { number: 54, text: "Und Mose und der Priester Eleasar nahmen das Gold von den Obersten über die Tausendschaften und über die Hundertschaften und brachten es in das Zelt der Begegnung als eine Erinnerung für die Söhne Israel vor dem HERRN*.", footnotes: ["℘ 2Mo 30,16"] },
    ]},
    { number: 32, verses: [
      { number: 1, text: "Und die Söhne Ruben und die Söhne Gad hatten viel Vieh, sehr zahlreich; und sie sahen das Land Jaser* und das Land Gilead*, und siehe, die Gegend war eine Gegend für Vieh*.", heading: "Verteilung des Ostjordanlandes an Ruben, Gad und den halben Stamm Manasse", footnotes: ["℘ Kap. 21,32; Jer 48,32", "℘ 5Mo 33,21; Jos 22,13; Jer 8,22", "℘ 1Chr 4,41; Jer 50,19; Mi 7,14"] },
      { number: 2, text: "Und die Söhne Gad und die Söhne Ruben kamen und sprachen zu Mose und zu dem Priester Eleasar und zu den Fürsten der Gemeinde und sagten:" },
      { number: 3, text: "Atarot und Dibon* und Jaser* und Nimra* und Heschbon* und Elale* und Sibma* und Nebo* und Beon,", footnotes: ["℘ Kap. 21,30", "℘ Kap. 21,32; Jer 48,32", "℘ Jes 15,6", "℘ V. 37; Kap. 21,25; Jos 21,39", "℘ V. 37; Jes 15,4", "℘ V. 38; Jes 16,8.9; Jer 48,32", "℘ Jes 15,2; Jer 48,1"] },
      { number: 4, text: "das Land, das der HERR vor der Gemeinde Israel geschlagen hat*, ist ein Land für Vieh, und deine Knechte haben Vieh*.", footnotes: ["℘ Kap. 21,24.35", "℘ 1Chr 4,41; Jer 50,19; Mi 7,14"] },
      { number: 5, text: "Und sie sagten: Wenn wir Gunst in deinen Augen gefunden haben, dann möge dieses Land deinen Knechten zum Eigentum gegeben werden! Lass uns nicht über den Jordan ziehen!" },
      { number: 6, text: "Und Mose sagte zu den Söhnen Gad und zu den Söhnen Ruben: Sollen eure Brüder in den Kampf ziehen, und ihr wollt hierbleiben*?", footnotes: ["℘ Ri 5,16.17"] },
      { number: 7, text: "Und warum wollt ihr das Herz der Söhne Israel davon abhalten, in das Land hinüberzuziehen, das der HERR ihnen gegeben hat?" },
      { number: 8, text: "So haben eure Väter getan, als ich sie von Kadesch-Barnea aussandte, das Land anzusehen*:", footnotes: ["℘ 5Mo 1,22.23"] },
      { number: 9, text: "Sie zogen hinauf bis zum Tal Eschkol und sahen das Land an; und sie hielten das Herz der Söhne Israel ab, so dass sie nicht in das Land hineinzogen, das der HERR ihnen gegeben hatte*.", footnotes: ["℘ Kap. 13,26-33"] },
      { number: 10, text: "Und der Zorn des HERRN entbrannte an jenem Tag, und er schwor und sprach:" },
      { number: 11, text: "Wenn die Männer, die aus Ägypten hinaufgezogen sind, von zwanzig Jahren an und darüber das Land sehen werden, das ich Abraham und Isaak und Jakob zugeschworen habe*! Denn sie sind mir nicht treu gefolgt*,", footnotes: ["Der Satz ist eine hebr. Schwurformel, deren zweite Hälfte nicht ausgesprochen wurde.", "w. sie haben <die Nachfolge> hinter mir her nicht erfüllt"] },
      { number: 12, text: "ausgenommen Kaleb, der Sohn des Jefunne, der Kenasiter*, und Josua, der Sohn des Nun; denn sie sind dem HERRN treu nachgefolgt*.", footnotes: ["℘ Jos 15,17", "w. sie haben <die Nachfolge> hinter dem HERRN her erfüllt\n℘ Kap. 14,22-24"] },
      { number: 13, text: "Und der Zorn des HERRN entbrannte gegen Israel*, und er ließ sie vierzig Jahre lang* in der Wüste umherirren, bis die ganze Generation aufgerieben war, die getan hatte, was böse in den Augen des HERRN war.", footnotes: ["℘ Ri 2,14.20", "℘ Kap. 14,33.34; 2Mo 16,35; Ps 95,10; Am 2,10; Apg 7,36.42; 13,18"] },
      { number: 14, text: "Und siehe, ihr seid an die Stelle eurer Väter getreten, eine Brut von sündigen Männern, um die Glut des Zornes des HERRN gegen Israel noch zu vermehren*.", footnotes: ["℘ 5Mo 9,24; 2Chr 28,13; Neh 13,18"] },
      { number: 15, text: "Wenn ihr euch von ihm abwendet*, dann wird er es noch länger in der Wüste <bleiben> lassen, und ihr werdet dieses ganze Volk zugrunde richten*.", footnotes: ["w. von <der Nachfolge> hinter ihm her abwendet", "℘ Jos 22,16-18"] },
      { number: 16, text: "Und sie traten zu ihm und sagten: Schafhürden wollen wir hier bauen für unsere Herden und Städte für unsere Kinder.*", footnotes: ["℘ 5Mo 3,19"] },
      { number: 17, text: "Wir selbst aber wollen uns eilends rüsten <und> vor den Söhnen Israel her<ziehen>, bis wir sie an ihren Ort gebracht haben; und <nur> unsere Kinder sollen in den befestigten Städten bleiben wegen der Bewohner des Landes." },
      { number: 18, text: "Wir wollen nicht in unsere Häuser zurückkehren, bis jeder von den Söhnen Israel sein Erbteil empfangen hat*.", footnotes: ["℘ 5Mo 3,20; Jos 22,4"] },
      { number: 19, text: "Denn wir wollen nicht mit ihnen erben jenseits des Jordan und darüber hinaus, denn unser Erbteil ist uns diesseits des Jordan nach Osten hin zuteilgeworden*.", footnotes: ["℘ Jos 13,8"] },
      { number: 20, text: "Da sagte Mose zu ihnen: Wenn ihr das tut, wenn ihr euch vor dem HERRN zum Kampf rüstet" },
      { number: 21, text: "und alle unter euch, die gerüstet sind, vor dem HERRN über den Jordan ziehen, bis er seine Feinde vor sich her vertrieben hat*", footnotes: ["℘ Jos 1,13-15"] },
      { number: 22, text: "und das Land vor dem HERRN unterworfen ist*, und ihr danach zurückkehrt, dann sollt ihr schuldlos sein gegenüber dem HERRN und gegenüber Israel; und dieses Land soll euch als Eigentum gehören vor dem HERRN*.", footnotes: ["℘ Jos 18,1", "℘ Jos 22,9"] },
      { number: 23, text: "Wenn ihr aber nicht so handelt, siehe, dann habt ihr gegen den HERRN gesündigt; und ihr sollt erkennen, dass eure Sünde euch finden wird*.", footnotes: ["℘ 1Mo 44,16; 2Sam 3,39; 1Kö 2,32.33; Spr 13,21; Jes 3,11; Gal 6,7"] },
      { number: 24, text: "Baut euch Städte für eure Kinder und Hürden für eure Schafe, und tut, was aus eurem Munde hervorgegangen ist!" },
      { number: 25, text: "Und die Söhne Gad und die Söhne Ruben sagten zu Mose: Deine Knechte werden tun, wie mein Herr es befiehlt*.", footnotes: ["℘ Jos 1,16"] },
      { number: 26, text: "Unsere Kinder, unsere Frauen, unsere Herden und all unser Vieh sollen dort in den Städten Gileads sein.*", footnotes: ["℘ 5Mo 3,19"] },
      { number: 27, text: "Deine Knechte aber, alle zum Heer<esdienst> Gerüsteten, werden vor dem HERRN hinüberziehen in den Kampf, wie mein Herr redet." },
      { number: 28, text: "Und Mose befahl ihretwegen dem Priester Eleasar und Josua, dem Sohn des Nun, und den Familienoberhäuptern* der Stämme der Söhne Israel;", footnotes: ["w. den Häuptern der Väter"] },
      { number: 29, text: "und Mose sagte zu ihnen: Wenn die Söhne Gad und die Söhne Ruben, alle zum Kampf Gerüsteten, mit euch vor dem HERRN über den Jordan ziehen und das Land vor euch unterworfen sein wird, dann sollt ihr ihnen das Land Gilead zum Eigentum geben.*", footnotes: ["℘ Jos 22,9"] },
      { number: 30, text: "Wenn sie aber nicht gerüstet mit euch hinüberziehen, dann sollen sie sich unter euch ansässig machen im Land Kanaan." },
      { number: 31, text: "Und die Söhne Gad und die Söhne Ruben antworteten und sagten: Wie der HERR zu deinen Knechten geredet hat, so wollen wir es machen*.", footnotes: ["℘ Jos 1,16"] },
      { number: 32, text: "Wir wollen gerüstet vor dem HERRN in das Land Kanaan hinüberziehen, und unser Erbbesitz soll uns diesseits des Jordan <erhalten bleiben>.*", footnotes: ["℘ V. 19; Kap. 34,15; Jos 12,1-6"] },
      { number: 33, text: "*Und Mose gab ihnen, den Söhnen Gad und den Söhnen Ruben und der Hälfte des Stammes Manasse, des Sohnes des Josef*, das Königreich des Sihon, des Königs der Amoriter, und das Königreich des Og, des Königs von Baschan, das Land samt seinen Städten mit ihren <Stadt>gebieten*, die Städte des Landes ringsum.", footnotes: ["℘ V. 33-42: 5Mo 3,12-17; Jos 13,8-33", "℘ 1Chr 5,18", "℘ Kap. 34,15; Jos 22,7"] },
      { number: 34, text: "Und die Söhne Gad bauten Dibon* und Atarot und Aroër*", footnotes: ["℘ Kap. 33,45", "℘ Ri 11,33"] },
      { number: 35, text: "und Atrot-Schofan und Jaser* und Jogboha*", footnotes: ["℘ Jes 16,8", "℘ Ri 8,11"] },
      { number: 36, text: "und Bet-Nimra und Bet-Haram, feste Städte und Schafhürden." },
      { number: 37, text: "Und die Söhne Ruben bauten Heschbon* und Elale* und Kirjatajim*", footnotes: ["℘ V. 3", "℘ Jos 1,16", "℘ Jer 48,1"] },
      { number: 38, text: "und Nebo und Baal-Meon*, deren Namen geändert wurden, und Sibma*; und sie benannten die Städte, die sie bauten, mit anderen Namen.", footnotes: ["℘ Jer 48,23", "℘ V. 3"] },
      { number: 39, text: "Und die Söhne Machirs*, des Sohnes Manasses, zogen nach Gilead und nahmen es ein; und sie vertrieben die Amoriter, die darin <wohnten>*.", footnotes: ["℘ Ri 5,14", "℘ Ri 10,8"] },
      { number: 40, text: "Und Mose gab Gilead dem Machir, dem Sohn Manasses; und er wohnte darin*.", footnotes: ["℘ Jos 17,1"] },
      { number: 41, text: "Und Jaïr, der Sohn Manasses, zog hin und nahm ihre Zeltdörfer ein und nannte sie »Zeltdörfer Jaïrs«.*", footnotes: ["℘ Ri 10,4; 1Kö 4,13; 1Chr 2,21-23"] },
      { number: 42, text: "Und Nobach zog hin und nahm Kenat und seine Tochterstädte ein und nannte es Nobach* nach seinem Namen.", footnotes: ["℘ Ri 8,11"] },
    ]},
    { number: 33, verses: [
      { number: 1, text: "Dies sind die Lagerplätze* der Söhne Israel, die aus dem Land Ägypten ausgezogen sind, nach ihren Heer<esverbänd>en <geordnet>, unter der Hand des Mose und des Aaron*.", heading: "Lagerplätze Israels während der vierzig Jahre in der Wüste", footnotes: ["w. Aufbrüche(n)", "℘ 2Mo 6,26"] },
      { number: 2, text: "Und Mose schrieb ihre Aufbruchsorte auf nach ihren Lagerplätzen* nach dem Befehl des HERRN; und das sind ihre Lagerplätze* nach ihren Aufbruchsorten:", footnotes: ["w. Aufbrüche(n)", "w. Aufbrüche(n)"] },
      { number: 3, text: "Sie brachen auf von Ramses* im ersten Monat, am fünfzehnten Tag des ersten Monats. Am zweiten Tag nach dem Passah zogen die Söhne Israel aus* mit erhobener Hand vor den Augen aller Ägypter*,", footnotes: ["℘ 1Mo 47,11", "℘ 2Mo 12,37.51", "℘ 2Mo 14,8"] },
      { number: 4, text: "während die Ägypter die begruben, die der HERR unter ihnen geschlagen hatte, alle Erstgeborenen*; und der HERR hatte an ihren Göttern Gericht geübt*.", footnotes: ["℘ Kap. 3,13; 2Mo 12,29", "℘ 2Mo 12,12; 18,11; Jes 19,1"] },
      { number: 5, text: "Und die Söhne Israel brachen auf von Ramses und lagerten in Sukkot*.", footnotes: ["℘ 2Mo 12,37"] },
      { number: 6, text: "Und sie brachen auf von Sukkot und lagerten in Etam*, das am Rand der Wüste <liegt>.", footnotes: ["℘ 2Mo 13,20"] },
      { number: 7, text: "Und sie brachen auf von Etam und wandten sich nach Pi-Hahirot, das Baal-Zefon gegenüber <liegt>, und lagerten vor Migdol*.", footnotes: ["℘ 2Mo 14,2.9"] },
      { number: 8, text: "Und sie brachen auf von Pi-Hahirot und zogen mitten durchs Meer in die Wüste, und sie zogen drei Tagereisen in der Wüste Etam und lagerten in Mara*.", footnotes: ["℘ 2Mo 15,22.23"] },
      { number: 9, text: "Und sie brachen auf von Mara und kamen nach Elim; und in Elim waren zwölf Wasserquellen und siebzig Palmbäume; und sie lagerten dort*.", footnotes: ["℘ 2Mo 15,27"] },
      { number: 10, text: "Und sie brachen auf von Elim und lagerten am Schilfmeer." },
      { number: 11, text: "Und sie brachen auf vom Schilfmeer und lagerten in der Wüste Sin*.", footnotes: ["℘ 2Mo 16,1"] },
      { number: 12, text: "Und sie brachen auf aus der Wüste Sin und lagerten in Dofka." },
      { number: 13, text: "Und sie brachen auf von Dofka und lagerten in Alusch." },
      { number: 14, text: "Und sie brachen auf von Alusch und lagerten in Refidim; und das Volk hatte dort kein Wasser zu trinken*.", footnotes: ["℘ 2Mo 17,1"] },
      { number: 15, text: "Und sie brachen auf von Refidim und lagerten in der Wüste Sinai*.", footnotes: ["℘ Kap. 10,12"] },
      { number: 16, text: "Und sie brachen auf aus der Wüste Sinai und lagerten in Kibrot-Hattaawa*.", footnotes: ["℘ Kap. 11,34"] },
      { number: 17, text: "Und sie brachen auf von Kibrot-Hattaawa und lagerten in Hazerot*.", footnotes: ["℘ Kap. 11,35"] },
      { number: 18, text: "Und sie brachen auf von Hazerot und lagerten in Ritma*.", footnotes: ["℘ Kap. 12,16"] },
      { number: 19, text: "Und sie brachen auf von Ritma und lagerten in Rimmon-Perez." },
      { number: 20, text: "Und sie brachen auf von Rimmon-Perez und lagerten in Libna." },
      { number: 21, text: "Und sie brachen auf von Libna und lagerten in Rissa." },
      { number: 22, text: "Und sie brachen auf von Rissa und lagerten in Kehelata." },
      { number: 23, text: "Und sie brachen auf von Kehelata und lagerten am Berg Schefer." },
      { number: 24, text: "Und sie brachen auf vom Berg Schefer und lagerten in Harada." },
      { number: 25, text: "Und sie brachen auf von Harada und lagerten in Makhelot." },
      { number: 26, text: "Und sie brachen auf von Makhelot und lagerten in Tahat." },
      { number: 27, text: "Und sie brachen auf von Tahat und lagerten in Tarach." },
      { number: 28, text: "Und sie brachen auf von Tarach und lagerten in Mitka." },
      { number: 29, text: "Und sie brachen auf von Mitka und lagerten in Haschmona." },
      { number: 30, text: "Und sie brachen auf von Haschmona und lagerten in Moserot*.", footnotes: ["℘ Kap. 20,28; 5Mo 10,6; 32,50"] },
      { number: 31, text: "Und sie brachen auf von Moserot und lagerten in Bene-Jaakan." },
      { number: 32, text: "Und sie brachen auf von Bene-Jaakan und lagerten in Hor-Gidgad." },
      { number: 33, text: "Und sie brachen auf von Hor-Gidgad und lagerten in Jotbata*.", footnotes: ["℘ 5Mo 10,7"] },
      { number: 34, text: "Und sie brachen auf von Jotbata und lagerten in Abrona." },
      { number: 35, text: "Und sie brachen auf von Abrona und lagerten in Ezjon-Geber*.", footnotes: ["℘ 5Mo 2,8; 1Kö 9,26"] },
      { number: 36, text: "Und sie brachen auf von Ezjon-Geber und lagerten in der Wüste Zin, das ist Kadesch*.", footnotes: ["℘ Kap. 13,26"] },
      { number: 37, text: "Und sie brachen auf von Kadesch und lagerten am Berg Hor, am Rand des Landes Edom*.", footnotes: ["℘ Kap. 20,22.23"] },
      { number: 38, text: "Und der Priester Aaron stieg auf den Berg Hor nach dem Befehl des HERRN; und er starb dort* im vierzigsten Jahr nach dem Auszug der Söhne Israel aus dem Land Ägypten, im fünften Monat, am Ersten des Monats*.", footnotes: ["℘ Kap. 20,28; 5Mo 10,6; 32,50", "℘ 5Mo 1,3"] },
      { number: 39, text: "Und Aaron war 123 Jahre alt, als er auf dem Berg Hor starb*.", footnotes: ["℘ 2Mo 7,7"] },
      { number: 40, text: "Und die Kanaaniter, der König von Arad, der im Süden wohnte im Land Kanaan, hörte von dem Kommen der Söhne Israel*.", footnotes: ["℘ Kap. 21,1"] },
      { number: 41, text: "Und sie brachen auf vom Berg Hor* und lagerten in Zalmona.", footnotes: ["℘ Kap. 21,4"] },
      { number: 42, text: "Und sie brachen auf von Zalmona und lagerten in Punon." },
      { number: 43, text: "Und sie brachen auf von Punon und lagerten in Obot*.", footnotes: ["℘ Kap. 21,10"] },
      { number: 44, text: "Und sie brachen auf von Obot und lagerten in Ije-Abarim, im Gebiet von Moab*.", footnotes: ["℘ Kap. 21,11"] },
      { number: 45, text: "Und sie brachen auf von Ijim und lagerten in Dibon-Gad*.", footnotes: ["℘ Kap. 32,34"] },
      { number: 46, text: "Und sie brachen auf von Dibon-Gad und lagerten in Almon-Diblatajim*.", footnotes: ["℘ Jer 48,22; Hes 6,14"] },
      { number: 47, text: "Und sie brachen auf von Almon-Diblatajim und lagerten im Gebirge Abarim östlich von Nebo*.", footnotes: ["℘ Kap. 27,12"] },
      { number: 48, text: "Und sie brachen auf vom Gebirge Abarim und lagerten in den Steppen von Moab, am Jordan <gegenüber> von Jericho*.", footnotes: ["℘ Kap. 22,1"] },
      { number: 49, text: "Und sie lagerten am Jordan von Bet-Jeschimot* bis Abel-Schittim* in den Steppen von Moab.", footnotes: ["℘ Jos 13,20; Hes 25,9", "℘ Kap. 25,1"] },
      { number: 50, text: "Und der HERR redete zu Mose in den Steppen von Moab, am Jordan <gegenüber> von Jericho*, und sprach:", footnotes: ["℘ Kap. 22,1"] },
      { number: 51, text: "Rede zu den Söhnen Israel und sage zu ihnen: Wenn ihr über den Jordan in das Land Kanaan zieht*,", footnotes: ["℘ 5Mo 9,1"] },
      { number: 52, text: "dann sollt ihr alle Bewohner des Landes vor euch her vertreiben* und all ihre Götzenbilder zugrunde richten; und alle ihre gegossenen Bilder sollt ihr zugrunde richten, und alle ihre Höhen sollt ihr austilgen*.", footnotes: ["℘ Jos 11,15", "℘ 2Mo 34,12.13; 1Kö 11,7"] },
      { number: 53, text: "Und ihr sollt das Land in Besitz nehmen und darin wohnen, denn euch habe ich das Land gegeben, es zu besitzen*.", footnotes: ["℘ 1Mo 15,7; 5Mo 3,18; Jos 1,6; 23,5"] },
      { number: 54, text: "Und ihr sollt das Land durchs Los als Erbteil empfangen nach euren Sippen: Dem, der groß ist <an Zahl>, sollt ihr sein Erbteil groß bemessen, und dem, der klein ist <an Zahl>, sollt ihr* sein Erbteil klein bemessen; wohin das Los für einen fällt, das soll ihm gehören; nach den Stämmen eurer Väter sollt ihr <es> unter euch <als Erbteil> verteilen*.", footnotes: ["w. sollst du", "℘ Kap. 26,54.55"] },
      { number: 55, text: "Wenn ihr aber die Bewohner des Landes nicht vor euch her vertreibt, dann werden die, die ihr von ihnen übrig lasst, zu Dornen in euren Augen und zu Stacheln in euren Seiten werden*, und sie werden euch bedrängen in dem Land, in dem ihr wohnt.", footnotes: ["℘ Jos 23,7.13; Hes 28,24"] },
      { number: 56, text: "Und es wird geschehen: Wie ich gedachte, ihnen zu tun, so werde ich euch tun*.", footnotes: ["℘ Jos 23,16"] },
    ]},
    { number: 34, verses: [
      { number: 1, text: "*Und der HERR redete zu Mose und sprach:", heading: "Grenzen und Aufteilung des Landes Kanaan", footnotes: ["℘ V. 1-12: Hes 47,13-20"] },
      { number: 2, text: "Befiehl den Söhnen Israel und sage zu ihnen: Wenn ihr in das Land Kanaan kommt, dann ist dies das Land, das euch als Erbteil zufallen soll*; das Land Kanaan nach seinen Grenzen*.", footnotes: ["℘ Jos 21,43", "℘ 2Mo 23,31; Jos 13,1-8; Hes 47,13"] },
      { number: 3, text: "*Und die Südseite soll für euch sein von der Wüste Zin* an, an Edom entlang, und die Südgrenze soll für euch sein vom Ende des Salzmeers gegen Osten.", footnotes: ["℘ V. 3-5: Jos 15,1-4", "℘ Kap. 13,21"] },
      { number: 4, text: "Und die Grenze soll sich für euch südlich von der Anhöhe Akrabbim* wenden und nach Zin hinübergehen, und ihr Ausläufer sei südlich von Kadesch-Barnea; und sie soll nach Hazar-Addar hin laufen und nach Azmon hinübergehen;", footnotes: ["℘ Ri 1,36"] },
      { number: 5, text: "und die Grenze soll sich von Azmon nach dem Bach Ägyptens wenden, und ihr Ausläufer soll zum Meer hin sein*.", footnotes: ["℘ Dan 11,45"] },
      { number: 6, text: "Und die Westgrenze: Sie soll für euch das große Meer und das <Küsten>gebiet sein; das soll für euch die Westgrenze sein*.", footnotes: ["℘ 5Mo 34,2; Jos 15,12"] },
      { number: 7, text: "Und das soll für euch die Nordgrenze sein: Vom großen Meer aus sollt ihr euch eine Linie ziehen <bis zum> Berg Hor;" },
      { number: 8, text: "vom Berge Hor sollt ihr eine Linie ziehen, bis man nach Hamat* kommt, und der Ausläufer der Grenze sei nach Zedad hin;", footnotes: ["℘ Kap. 13,21; Jos 13,5; 2Sam 8,9; 1Kö 8,65; 2Kö 14,25; 1Chr 13,5"] },
      { number: 9, text: "und die Grenze soll nach Sifron hin verlaufen, und ihr Ausläufer sei bei Hazar-Enan. Das soll für euch die Nordgrenze sein." },
      { number: 10, text: "Und als Ostgrenze sollt ihr euch eine Linie ziehen von Hazar-Enan nach Schefam*.", footnotes: ["so mit LXX; Mas. T.: Und als Ostgrenze sollt ihr euch wünschen die Linie von Hazar-Enan nach Schefam\n℘ 1Chr 27,27"] },
      { number: 11, text: "Und die Grenze soll von Schefam nach Ribla* östlich von Ajin hinabgehen; und <weiter> soll die Grenze hinuntergehen und an die Seite* des Sees Kinneret* gegen Osten stoßen;", footnotes: ["℘ 2Kö 23,33", "w. Schulter", "d. i. Genezareth\n℘ 5Mo 3,17; Jos 11,2; 12,3; 13,27; Lk 5,1"] },
      { number: 12, text: "und die Grenze soll an den Jordan hinabgehen, und ihr Ausläufer sei am Salzmeer*. Das soll euer Land sein mit seinen Grenzen ringsum*.", footnotes: ["℘ Jos 15,5", "℘ 2Mo 23,31; Jos 13,1-8; Hes 47,13"] },
      { number: 13, text: "Und Mose befahl den Söhnen Israel und sprach: Das ist das Land, das ihr durchs Los als Erbteil empfangen sollt*, das der HERR den neun Stämmen und dem halben Stamm zu geben befohlen hat*.", footnotes: ["℘ Kap. 26,55", "℘ Jos 13,7"] },
      { number: 14, text: "Denn der Stamm der Söhne der Rubeniter nach ihren Vaterhäusern und der Stamm der Söhne der Gaditer nach ihren Vaterhäusern und die Hälfte des Stammes Manasse, die haben ihr Erbteil empfangen." },
      { number: 15, text: "Die zwei Stämme und der halbe Stamm haben ihr Erbteil empfangen diesseits des Jordan von Jericho gegen Osten, gegen <Sonnen>aufgang*.", footnotes: ["℘ Kap. 32,32.33"] },
      { number: 16, text: "Und der HERR redete zu Mose und sprach:" },
      { number: 17, text: "Das sind die Namen der Männer*, die euch das Land als Erbe austeilen sollen: der Priester Eleasar und Josua, der Sohn des Nun*.", footnotes: ["℘ Kap. 13,1-3", "℘ 5Mo 1,38; Jos 14,1.2"] },
      { number: 18, text: "Und je einen Fürsten von einem Stamm sollt ihr nehmen*, um das Land als Erbe auszuteilen*.", footnotes: ["℘ Kap. 13,1-3", "℘ Jos 19,51"] },
      { number: 19, text: "*Und das sind die Namen der Männer: für den Stamm Juda: Kaleb, der Sohn des Jefunne*;", footnotes: ["℘ V. 19-28: Kap. 13,4-15; 1Mo 35,23-26", "℘ Kap. 13,6"] },
      { number: 20, text: "und für den Stamm der Söhne Simeon: Schemuël, der Sohn des Ammihud;" },
      { number: 21, text: "für den Stamm Benjamin: Elidad, der Sohn des Kislon;" },
      { number: 22, text: "und für den Stamm der Söhne Dan ein Fürst: Bukki, der Sohn des Jogli;" },
      { number: 23, text: "für die Söhne Josefs: für den Stamm der Söhne Manasse ein Fürst: Hanniël, der Sohn des Efod;" },
      { number: 24, text: "und für den Stamm der Söhne Ephraim ein Fürst: Kemuël, der Sohn des Schiftan;" },
      { number: 25, text: "und für den Stamm der Söhne Sebulon ein Fürst: Elizafan, der Sohn des Parnach;" },
      { number: 26, text: "und für den Stamm der Söhne Issaschar ein Fürst: Paltiël, der Sohn des Asan;" },
      { number: 27, text: "und für den Stamm der Söhne Asser ein Fürst: Ahihud, der Sohn des Schelomi;" },
      { number: 28, text: "und für den Stamm der Söhne Naftali ein Fürst: Pedahel, der Sohn des Ammihud." },
      { number: 29, text: "Diese sind es, denen der HERR befahl, den Söhnen Israel ihr Erbe im Land Kanaan auszuteilen*.", footnotes: ["℘ Jos 19,51"] },
    ]},
    { number: 35, verses: [
      { number: 1, text: "*Und der HERR redete zu Mose in den Ebenen von Moab am Jordan von Jericho* und sprach:", heading: "Städte der Leviten und Zufluchtsstädte", footnotes: ["℘ V. 1-8: Jos 21,1-8", "℘ Kap. 22,1"] },
      { number: 2, text: "Befiehl den Söhnen Israel, dass sie von ihrem Erbbesitz den Leviten Städte zum Wohnen geben*! Und zu den Städten sollt ihr Weideland rings um sie her den Leviten geben*.", footnotes: ["℘ 3Mo 25,32; Jos 14,4; 1Chr 13,2; Neh 13,10", "℘ Hes 45,5"] },
      { number: 3, text: "Und die Städte sollen ihnen zum Wohnen dienen, und deren Weidegebiete sollen für ihr Vieh und für ihren Besitz und für alle ihre Tiere sein." },
      { number: 4, text: "Und die Weidegebiete der Städte, die ihr den Leviten geben sollt, sollen von der Stadtmauer nach außen hin tausend Ellen betragen ringsum;" },
      { number: 5, text: "und ihr sollt außerhalb der Stadt auf der Ostseite zweitausend Ellen abmessen und auf der Südseite zweitausend Ellen und auf der Westseite zweitausend Ellen und auf der Nordseite zweitausend Ellen; die Stadt selbst aber soll in der Mitte sein; das sollen die Weidegebiete ihrer Städte sein*.", footnotes: ["℘ 5Mo 18,6"] },
      { number: 6, text: "Und die Städte, die ihr den Leviten geben sollt: Sechs Zufluchtsstädte sollen es sein, die ihr <ihnen> geben sollt, damit dorthin fliehen kann, wer einen Totschlag begangen hat*. Und zu diesen hinzu sollt ihr <noch> 42 Städte geben.", footnotes: ["℘ 2Mo 21,13; Jos 20,2"] },
      { number: 7, text: "Alle die Städte, die ihr den Leviten geben sollt, sie und ihre Weidegebiete, <sollen> 48 Städte <sein>*.", footnotes: ["℘ Jos 21,41"] },
      { number: 8, text: "Und was die Städte betrifft, die ihr von dem Eigentum der Söhne Israel hergeben sollt: von dem <Stamm>, der viel hat, sollt ihr viel nehmen, und von dem, der wenig hat, sollt ihr wenig nehmen*; jeder <Stamm> soll entsprechend dem Erbteil, das er erben wird, <einige> von seinen Städten den Leviten geben*.", footnotes: ["w. von dem Großen sollt ihr Großes nehmen, und von dem Kleinen sollt ihr Kleines nehmen", "℘ Kap. 26,54; 1Mo 49,7; 2Chr 11,14"] },
      { number: 9, text: "*Und der HERR redete zu Mose und sprach:", footnotes: ["℘ V. 9-29: 5Mo 19,1-13; Jos 20,1-9"] },
      { number: 10, text: "Rede zu den Söhnen Israel und sage zu ihnen: Wenn ihr über den Jordan in das Land Kanaan zieht," },
      { number: 11, text: "sollt ihr euch Städte bestimmen: Zufluchtsstädte sollen sie für euch sein, dass dorthin ein Totschläger fliehe, der einen Menschen aus Versehen erschlagen hat*.", footnotes: ["℘ 2Mo 21,13; Jos 20,2"] },
      { number: 12, text: "Und die Städte sollen euch als Zuflucht vor dem Rächer* dienen, damit der Totschläger nicht sterbe, bis er angesichts der Gemeinde vor Gericht gestanden hat.", footnotes: ["w. Löser; d. h. der nächste Verwandte"] },
      { number: 13, text: "Und die Städte, die ihr hergeben sollt, sollen sechs Zufluchtsstädte für euch sein." },
      { number: 14, text: "Drei Städte sollt ihr diesseits des Jordan geben*, und drei Städte sollt ihr im Land Kanaan geben; Zufluchtsstädte sollen sie sein.", footnotes: ["℘ 5Mo 4,41"] },
      { number: 15, text: "Für die Söhne Israel und den Fremden und den Beisassen* in ihrer Mitte* sollen diese sechs Städte als Zuflucht dienen, damit dorthin jeder fliehen kann, der einen Menschen aus Versehen erschlagen hat.", footnotes: ["d. i. ein Ansässiger ohne Bürgerrecht", "℘ 2Mo 12,49"] },
      { number: 16, text: "Wenn er ihn aber mit einem eisernen Gerät geschlagen hat, so dass er gestorben ist, dann ist er ein Mörder*; der Mörder soll unbedingt getötet werden*.", footnotes: ["Hier steht dasselbe hebr. Wort wie für »Totschläger« in V. 11ff; so auch im Folgenden.", "℘ 1Mo 9,5.6; Hes 16,38"] },
      { number: 17, text: "Und wenn er ihn mit einem Stein <in> der Hand, durch den man sterben kann, geschlagen hat, so dass er gestorben ist, dann ist er ein Mörder; der Mörder soll unbedingt getötet werden*.", footnotes: ["℘ 1Mo 9,5.6; Hes 16,38"] },
      { number: 18, text: "Oder wenn er ihn mit einem hölzernen Gerät <in> der Hand, durch das man sterben kann, geschlagen hat, so dass er gestorben ist, dann ist er ein Mörder; der Mörder soll unbedingt getötet werden*.", footnotes: ["℘ 1Mo 9,5.6; Hes 16,38"] },
      { number: 19, text: "Der Bluträcher, der soll den Mörder töten*; wenn er ihn trifft, soll er ihn töten.", footnotes: ["℘ Ri 8,19; 2Sam 3,27.30; 14,11"] },
      { number: 20, text: "Und wenn er ihn aus Hass gestoßen oder in böser Absicht* <etwas> gegen ihn geworfen hat, so dass er gestorben ist,", footnotes: ["o. oder bei Nachstellung"] },
      { number: 21, text: "oder ihn aus Feindschaft mit seiner Hand geschlagen hat, so dass er gestorben ist, dann soll der Schläger unbedingt getötet werden*; er ist ein Mörder; der Bluträcher soll den Mörder töten, wenn er ihn trifft.", footnotes: ["℘ 1Mo 9,5.6; Hes 16,38"] },
      { number: 22, text: "Wenn er ihn aber unversehens, nicht aus Feindschaft gestoßen oder ohne böse Absicht* irgendein Gerät auf ihn geworfen hat", footnotes: ["o. ohne Nachstellung"] },
      { number: 23, text: "oder, ohne es zu sehen, irgendeinen Stein, durch den man sterben kann, auf ihn hat fallen lassen, so dass er gestorben ist — er war ihm aber nicht feind und suchte seinen Schaden nicht —," },
      { number: 24, text: "dann soll die Gemeinde zwischen dem Schläger und dem Bluträcher nach diesen Rechtsbestimmungen richten:" },
      { number: 25, text: "Und die Gemeinde soll den Totschläger aus der Hand des Bluträchers retten, und die Gemeinde soll ihn in seine Zufluchtsstadt zurückbringen, in die er geflohen ist; und er soll in ihr bleiben bis zum Tod des Hohenpriesters, den man mit dem heiligen Öl gesalbt hat*.", footnotes: ["℘ 2Mo 29,7"] },
      { number: 26, text: "Wenn aber der Totschläger über die Grenze seiner Zufluchtsstadt, in die er geflohen ist, jemals hinausgeht," },
      { number: 27, text: "und der Bluträcher findet ihn außerhalb der Grenze seiner Zufluchtsstadt, und der Bluträcher tötet den Totschläger, dann hat er keine Blutschuld." },
      { number: 28, text: "Denn der <Totschläger> soll in seiner Zufluchtsstadt bleiben bis zum Tod des Hohenpriesters; und nach dem Tod des Hohenpriesters darf der Totschläger in das Land seines Eigentums zurückkehren." },
      { number: 29, text: "Und das soll euch zu einer Rechtsordnung sein bei euren Generationen in allen euren Wohnsitzen*.", footnotes: ["℘ 2Mo 27,21"] },
      { number: 30, text: "Für jeden, der einen Menschen erschlägt<, gilt>: Auf die Aussage von Zeugen soll man den Mörder töten*; aber ein einzelner Zeuge kann nicht gegen einen Menschen aussagen*, dass er sterben muss*.", footnotes: ["℘ 2Mo 21,12", "w. antworten", "℘ 5Mo 17,6; Mt 18,16; 26,60"] },
      { number: 31, text: "Und ihr sollt kein Sühnegeld annehmen für das Leben* eines Mörders, der schuldig ist zu sterben, sondern er soll unbedingt getötet werden*.", footnotes: ["o. für die Seele", "℘ 1Mo 9,5.6; Hes 16,38"] },
      { number: 32, text: "Auch sollt ihr kein Sühnegeld annehmen für den in seine Zufluchtsstadt Geflohenen, so dass er vor* dem Tod des Priesters zurückkehren könnte, um im Land zu wohnen.", footnotes: ["w. bis zu"] },
      { number: 33, text: "Und ihr sollt das Land nicht entweihen, in dem ihr seid; denn das Blut, das entweiht das Land*; und dem Land kann für das Blut, das in ihm vergossen worden ist, keine Sühnung erwirkt werden, außer durch das Blut dessen, der es vergossen hat*.", footnotes: ["℘ Ps 106,38", "℘ 5Mo 19,13; 2Sam 3,29; 21,9.14; 2Kö 24,4; 2Chr 23,15; Jer 26,15"] },
      { number: 34, text: "Und du sollst das Land nicht unrein machen, in dem ihr wohnt*, in dessen Mitte ich wohne*; denn ich, der HERR, wohne inmitten der Söhne Israel*.", footnotes: ["℘ 3Mo 18,25; 5Mo 21,23", "℘ Kap. 16,3", "℘ 2Mo 29,45.46; 5Mo 6,15; Hes 35,10"] },
    ]},
    { number: 36, verses: [
      { number: 1, text: "Und es traten herzu die Familienoberhäupter* von der Sippe der Söhne des Gilead, des Sohnes des Machir, des Sohnes des Manasse, aus den Sippen der Söhne Josefs*; und sie redeten vor Mose und vor den Fürsten, den Häuptern der Väter der Söhne Israel*,", heading: "Gesetz für Erbtöchter", footnotes: ["w. die Häupter der Väter", "℘ Kap. 26,29; 27,1", "℘ Kap. 27,2"] },
      { number: 2, text: "und sagten: Der HERR hat meinem Herrn befohlen, den Söhnen Israel das Land durchs Los als Erbteil zu geben*; und meinem Herrn ist von dem HERRN befohlen worden, das Erbteil Zelofhads, unseres Bruders, seinen Töchtern zu geben*.", footnotes: ["℘ Kap. 26,55.56", "℘ Kap. 27,7"] },
      { number: 3, text: "Werden sie nun einem von den Söhnen der <anderen> Stämme der Söhne Israel als Frauen <zuteil>, dann wird ihr Erbteil dem Erbteil unserer Väter entzogen und zu dem Erbteil des Stammes hinzugefügt werden, dem sie <dann> angehören werden; und dem Los unseres Erbteils wird es entzogen werden." },
      { number: 4, text: "Und <auch> wenn das Jobel<jahr>* der Söhne Israel kommt*, wird ihr Erbteil zu dem Erbteil des Stammes hinzugefügt werden, dem sie <dann> angehören werden; und ihr Erbteil wird dem Erbteil des Stammes unserer Väter entzogen werden.", footnotes: ["s. Anm. zu 3Mo 25,10", "℘ 3Mo 25,8-13"] },
      { number: 5, text: "Da befahl Mose den Söhnen Israel nach der Anweisung des HERRN und sagte: Der Stamm der Söhne Josef redet recht*.", footnotes: ["℘ Kap. 27,7"] },
      { number: 6, text: "Dies ist das Wort, das der HERR betreffs der Töchter Zelofhads geboten hat, indem er sprach: Sie mögen dem, der in ihren Augen gut ist, als Frauen zuteil werden; nur sollen sie <einem aus> der Sippe des Stammes ihres Vaters als Frauen zuteil werden*,", footnotes: ["℘ 1Chr 23,22"] },
      { number: 7, text: "damit nicht ein Erbteil der Söhne Israel von Stamm zu Stamm übergehe; denn die Söhne Israel sollen jeder am Erbteil des Stammes seiner Väter festhalten*.", footnotes: ["℘ Jos 24,28; 1Sam 26,19; 1Kö 21,3"] },
      { number: 8, text: "Und jede Tochter, die ein Erbteil aus den Stämmen der Söhne Israel besitzt, soll einem aus der Sippe des Stammes ihres Vaters als Frau zuteil werden, damit die Söhne Israel <ihr Erbteil>, jeder das Erbteil seiner Väter, besitzen" },
      { number: 9, text: "und nicht ein Erbteil von einem Stamm auf einen anderen Stamm übergehe. Denn die Stämme der Söhne Israel sollen jeder an seinem Erbteil festhalten*.", footnotes: ["℘ Jos 24,28; 1Sam 26,19; 1Kö 21,3"] },
      { number: 10, text: "So wie der HERR dem Mose geboten hatte, so machten es die Töchter Zelofhads*.", footnotes: ["℘ Kap. 1,54; 2Mo 12,50"] },
      { number: 11, text: "Und Machla, Tirza und Hogla und Milka und Noa, die Töchter Zelofhads*, wurden den Söhnen ihrer Onkel als Frauen zuteil.", footnotes: ["℘ Kap. 26,33; 27,1"] },
      { number: 12, text: "<Männern> aus den Sippen der Söhne Manasse, des Sohnes des Josef, wurden sie als Frauen zuteil. Und so verblieb ihr Erbteil bei dem Stamm der Sippen ihres Vaters*.", footnotes: ["℘ Jos 17,14"] },
      { number: 13, text: "Das sind die Gebote und die Rechtsbestimmungen, die der HERR in den Ebenen von Moab am Jordan von Jericho* den Söhnen Israel durch Mose geboten hat*.", footnotes: ["℘ Kap. 22,1", "℘ 3Mo 27,34"] },
    ]},
  ]
};
